import { format } from 'date-fns'
import { db, logAudit, newEnvelope } from '@/db/db'
import { useOwned } from '@/db/hooks'
import type { Envelope, Owned } from '@/types/domain'
import { patchFinance, removeFinance } from './store'
import type { MoneySpace } from './money'

/**
 * Persistence for arisan groups (F20).
 *
 * ponytail: no new Dexie store. One arisan is one `ledger` row (kind:'arisan',
 * accountId:''), the same trick as budget/income/debt/savings. The round state
 * lives on the row: `round` counts up across cycles, `collected` is who has paid
 * into the current round, and advancing a round resets `collected`. All the
 * arithmetic ("whose turn", "who owes") is in the pure `arisan.ts`; this file
 * only reads and writes.
 */

const NO_ACCOUNT = '' as const

export type ArisanGroup = Owned<{
  kind: 'arisan'
  accountId: typeof NO_ACCOUNT
  /** Group name; also the ledger `label` backup requires. */
  label: string
  /** Contribution per member per round. Stored as the ledger `amount`. */
  amount: number
  /** Everyone in the group, by user-typed name — never invented. */
  members: string[]
  /** Payout rotation. Defaults to member order if left empty. */
  order: string[]
  /** 0-based index of the current round across all cycles. */
  round: number
  /** Members who have paid into the current round. */
  collected: string[]
  space: MoneySpace
  /** When the arisan started; the ledger `date` backup requires. */
  date: string
  category: 'arisan'
  planned: false
}>

const dataClassFor = (space: MoneySpace) => (space === 'shared' ? 'C2_shared_ops' : 'C1_personal')
const visibilityFor = (space: MoneySpace): Envelope['visibility'] =>
  space === 'shared' ? 'shared' : 'private'

export function useArisan(viewerProfileId: string | undefined): ArisanGroup[] | undefined {
  const rows = useOwned<ArisanGroup>('ledger', viewerProfileId, (a, b) => a.label.localeCompare(b.label))
  return rows?.filter((r) => r.kind === 'arisan')
}

export async function addArisan(
  ownerProfileId: string,
  input: { name: string; amount: number; members: string[]; space: MoneySpace; startDate?: string },
): Promise<string> {
  const members = input.members.map((m) => m.trim()).filter(Boolean)
  const env = newEnvelope(ownerProfileId, dataClassFor(input.space), {
    visibility: visibilityFor(input.space),
  })
  await db.ledger.put({
    ...env,
    kind: 'arisan',
    accountId: NO_ACCOUNT,
    label: input.name.trim(),
    amount: Math.max(0, Math.round(input.amount)),
    members,
    order: members,
    round: 0,
    collected: [],
    space: input.space,
    date: input.startDate ?? format(new Date(), 'yyyy-MM-dd'),
    category: 'arisan',
    planned: false,
  } as never)
  await logAudit({
    actorProfileId: ownerProfileId,
    action: 'create',
    objectStore: 'ledger',
    objectId: env.id,
    summary: 'ledger dibuat',
  })
  return env.id
}

/** Toggle whether one member has paid into the current round. */
export async function toggleCollected(group: ArisanGroup, member: string): Promise<void> {
  const collected = group.collected.includes(member)
    ? group.collected.filter((m) => m !== member)
    : [...group.collected, member]
  await patchFinance('ledger', group.id, { collected } as never)
}

/** Close this round (the recipient took the pot) and open the next one. */
export async function advanceRound(group: ArisanGroup): Promise<void> {
  await patchFinance('ledger', group.id, { round: group.round + 1, collected: [] } as never)
}

export async function removeArisan(id: string, actorProfileId: string): Promise<void> {
  await removeFinance('ledger', id, actorProfileId)
}
