import { format } from 'date-fns'
import { db, logAudit, newEnvelope } from '@/db/db'
import { useOwned } from '@/db/hooks'
import type { Envelope, Owned } from '@/types/domain'
import { removeFinance } from './store'
import type { MoneySpace } from './money'

/**
 * Persistence for savings goals + their contributions (F17) and the emergency
 * fund (F18).
 *
 * ponytail: no new Dexie store. A goal and each contribution are `ledger` rows
 * discriminated by `kind` and pinned to `accountId: ''` — the same trick batch 3
 * used for budget/income/debt, so account screens never render them and backup's
 * required ledger fields (accountId, label, amount, date) are all satisfied.
 *
 * The saved amount is NOT stored on the goal: it is the sum of the goal's
 * contribution rows. That is what makes the history real — every top-up is its
 * own dated row you can see and remove, not a single number quietly overwritten.
 * The emergency fund is simply a goal flagged `emergency`; its balance is its
 * saved total, which F18 divides by the monthly-expense basis.
 */

const NO_ACCOUNT = '' as const

export type SavingsGoal = Owned<{
  kind: 'savings_goal'
  accountId: typeof NO_ACCOUNT
  /** Goal name; also the ledger `label` backup requires. */
  label: string
  /** Target amount. Stored as the ledger `amount`. */
  amount: number
  space: MoneySpace
  /** When it was created; the ledger `date` backup requires. */
  date: string
  /** Optional soft target date. A target, never a deadline that can be "missed". */
  targetDate?: string
  /** This goal is the household emergency fund (F18). At most one, by convention. */
  emergency: boolean
  category: 'savings'
  planned: false
}>

export type SavingContribution = Owned<{
  kind: 'saving'
  accountId: typeof NO_ACCOUNT
  /** The goal this tops up. */
  goalId: string
  /** Goal name copied for backup's required `label`. */
  label: string
  amount: number
  date: string
  category: 'saving'
  planned: false
}>

const dataClassFor = (space: MoneySpace) => (space === 'shared' ? 'C2_shared_ops' : 'C1_personal')
const visibilityFor = (space: MoneySpace): Envelope['visibility'] =>
  space === 'shared' ? 'shared' : 'private'

export function useGoals(viewerProfileId: string | undefined): SavingsGoal[] | undefined {
  const rows = useOwned<SavingsGoal>('ledger', viewerProfileId, (a, b) => a.label.localeCompare(b.label))
  return rows?.filter((r) => r.kind === 'savings_goal')
}

export function useContributions(viewerProfileId: string | undefined): SavingContribution[] | undefined {
  const rows = useOwned<SavingContribution>('ledger', viewerProfileId, (a, b) => b.date.localeCompare(a.date))
  return rows?.filter((r) => r.kind === 'saving')
}

async function putLedger(ownerProfileId: string, space: MoneySpace, body: object): Promise<string> {
  const env = newEnvelope(ownerProfileId, dataClassFor(space), { visibility: visibilityFor(space) })
  await db.ledger.put({ ...env, ...body } as never)
  await logAudit({
    actorProfileId: ownerProfileId,
    action: 'create',
    objectStore: 'ledger',
    objectId: env.id,
    summary: 'ledger dibuat',
  })
  return env.id
}

export async function addGoal(
  ownerProfileId: string,
  input: { name: string; target: number; space: MoneySpace; targetDate?: string; emergency?: boolean },
  todayISO = format(new Date(), 'yyyy-MM-dd'),
): Promise<string> {
  return putLedger(ownerProfileId, input.space, {
    kind: 'savings_goal',
    accountId: NO_ACCOUNT,
    label: input.name,
    amount: Math.max(0, Math.round(input.target)),
    space: input.space,
    date: todayISO,
    ...(input.targetDate ? { targetDate: input.targetDate } : {}),
    emergency: Boolean(input.emergency),
    category: 'savings',
    planned: false,
  })
}

/** Record one contribution as its own dated row — this is the history. */
export async function addContribution(
  ownerProfileId: string,
  goal: SavingsGoal,
  amount: number,
  todayISO = format(new Date(), 'yyyy-MM-dd'),
): Promise<string> {
  return putLedger(ownerProfileId, goal.space, {
    kind: 'saving',
    accountId: NO_ACCOUNT,
    goalId: goal.id,
    label: goal.label,
    amount: Math.max(0, Math.round(amount)),
    date: todayISO,
    category: 'saving',
    planned: false,
  })
}

/** Soft-delete a goal. Its contribution rows stay as history unless removed too. */
export async function removeGoal(id: string, actorProfileId: string): Promise<void> {
  await removeFinance('ledger', id, actorProfileId)
}

export async function removeContribution(id: string, actorProfileId: string): Promise<void> {
  await removeFinance('ledger', id, actorProfileId)
}
