import { useEffect, useMemo, useState } from 'react'
import { format } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { useI18n } from '@/i18n'
import { formatRupiah, whenLabel } from '@/i18n/format'
import { OptionList, amountOf } from './parts'
import { useFinance, type FinanceAccount, type LedgerEntry } from './store'
import { useBills } from './ledgerStore'
import { usePots, addPot, editPot, removePot, rollPot, type PotRecord } from './budgetStore'
import {
  advancePot,
  monthOf,
  potStatus,
  spaceSafeToSpend,
  spentInPeriod,
  type SpentInput,
} from './budget'
import { MONEY_SPACES, type MoneySpace, type PlannedOutflow } from './money'
import { spendTone, TONE_BAR, TONE_CHIP } from './conflictSafe'

/**
 * Amplop & sisa aman (FIN F10–F11).
 *
 * An envelope is money the couple already spoke for: a monthly budget per
 * category, in one of the three spaces, that can roll its leftover forward or
 * reset. Safe-to-spend then answers, per space, what is *genuinely* free — after
 * the bills that are committed and the budget still sitting in envelopes. It is
 * always a range with its reason attached, never a single confident number.
 */

const today = () => format(new Date(), 'yyyy-MM-dd')

/** Bill.space ('mine'|'partner'|'shared') → the viewer's MoneySpace, or null. */
function billSpace(s: 'mine' | 'partner' | 'shared'): MoneySpace | null {
  if (s === 'shared') return 'shared'
  if (s === 'mine') return 'mine'
  return null
}

export default function Envelopes({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const [open, setOpen] = useState(false)

  const accounts = useFinance<'accounts'>('accounts', me)
  const ledger = useFinance<'ledger'>('ledger', me)
  const bills = useBills(me)
  const pots = usePots(me)

  const month = monthOf(today())

  // Real transaction outflows only: budget/income rows sit in the same store with
  // an empty accountId, so joining on a real account drops them here.
  const byAccount = useMemo(() => {
    const m = new Map<string, FinanceAccount>()
    for (const a of accounts ?? []) if (a.kind === 'account') m.set(a.id, a)
    return m
  }, [accounts])

  const outflows: SpentInput[] = useMemo(() => {
    const out: SpentInput[] = []
    for (const e of (ledger ?? []) as LedgerEntry[]) {
      const acc = byAccount.get(e.accountId)
      if (!acc || e.amount >= 0) continue
      out.push({ amount: e.amount, category: e.category, date: e.date, space: acc.space })
    }
    return out
  }, [ledger, byAccount])

  // Roll any pot whose stored period has passed. One-time per load; the pure
  // `advancePot` decides carry vs reset, this only persists the result.
  useEffect(() => {
    if (!pots) return
    for (const p of pots) {
      const spentStored = spentInPeriod(outflows, p, p.periodMonth)
      const rolled = advancePot(
        { monthly: p.amount, carried: p.carried, rollover: p.rollover, periodMonth: p.periodMonth },
        month,
        spentStored,
      )
      if (rolled) void rollPot(p.id, rolled.carried, rolled.periodMonth)
    }
    // Only react to the set of pots + the current month, not every outflow tick.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pots?.map((p) => p.id + p.periodMonth).join(), month])

  const spaces = MONEY_SPACES.filter(
    (s) => (accounts ?? []).some((a) => a.kind === 'account' && a.space === s),
  )

  return (
    <div className="stack">
      {/* F11 — what is genuinely free, per space */}
      {spaces.map((space) => {
        const accs = (accounts ?? []).filter((a) => a.kind === 'account' && a.space === space)
        const balance = accs.reduce((n, a) => n + Math.round(a.balance), 0)
        const paydayDom = accs.reduce((min, a) => Math.min(min, a.paydayDom || 25), 31)
        const spaceBills: PlannedOutflow[] = (bills ?? [])
          .filter((b) => !b.deletedAt && b.status === 'unpaid' && billSpace(b.space) === space)
          .map((b) => ({ amount: b.amount, ...(b.dueDate ? { dueDate: b.dueDate } : {}) }))
        const reserved = (pots ?? [])
          .filter((p) => p.space === space)
          .reduce((n, p) => n + potStatus(p.amount, p.carried, spentInPeriod(outflows, p, month)).reserved, 0)
        const sts = spaceSafeToSpend({ balance, today: today(), paydayDom, bills: spaceBills, reserved })
        return (
          <Card key={space} title={t(`finance2.space.${space}`)} icon="money" hint={t('finance2.freeHint')}>
            <p style={{ fontSize: 20, fontWeight: 700, margin: 0 }}>
              {sts.low === sts.high
                ? formatRupiah(sts.low, locale)
                : `${formatRupiah(sts.low, locale)} – ${formatRupiah(sts.high, locale)}`}
            </p>
            <p className="card__hint">
              {t('finance2.freeUntil', { date: whenLabel(sts.until, t, locale) })}
              {sts.undated > 0 ? ` · ${t('finance2.freeUndated', { amount: formatRupiah(sts.undated, locale) })}` : ''}
            </p>
          </Card>
        )
      })}

      {/* F10 — the envelopes themselves */}
      <Card
        title={t('finance2.potsTitle')}
        icon="money"
        hint={t('finance2.potsHint')}
        action={
          <button className="btn btn--sm" onClick={() => setOpen(true)}>
            <Icon name="plus" size={16} /> {t('finance2.addPot')}
          </button>
        }
      >
        {(pots ?? []).length === 0 ? (
          <EmptyState icon="money" title={t('finance2.noPots')} hint={t('finance2.noPotsHint')} />
        ) : (
          <ul className="list">
            {(pots ?? []).map((p) => (
              <PotRow key={p.id} me={me} pot={p} spent={spentInPeriod(outflows, p, month)} />
            ))}
          </ul>
        )}
      </Card>

      <p className="disclaimer">{t('finance2.freeCaveat')}</p>
      <NewPot me={me} open={open} onClose={() => setOpen(false)} />
    </div>
  )
}

function PotRow({ me, pot, spent }: { me: string; pot: PotRecord; spent: number }) {
  const { t, locale } = useI18n()
  const s = potStatus(pot.amount, pot.carried, spent)
  const pct = s.budget > 0 ? Math.min(100, Math.round((s.spent / s.budget) * 100)) : 0
  return (
    <li className="list__item" style={{ alignItems: 'flex-start' }}>
      <Icon name="money" size={18} />
      <span className="grow stack stack--tight">
        <strong style={{ fontSize: 14 }}>{pot.label}</strong>
        <span className="card__hint">
          {t(`finance2.space.${pot.space}`)} · {pot.category}
          {pot.carried > 0 ? ` · ${t('finance2.potCarried', { amount: formatRupiah(pot.carried, locale) })}` : ''}
        </span>
        <span
          aria-hidden
          style={{ height: 6, borderRadius: 3, background: 'var(--surface-2, #e5e5e5)', overflow: 'hidden' }}
        >
          <span
            style={{
              display: 'block',
              height: '100%',
              width: `${pct}%`,
              // F22: over budget is a fact to notice, never a red alarm on shared money.
              background: TONE_BAR[spendTone(s.over)],
            }}
          />
        </span>
        <span className={TONE_CHIP[spendTone(s.over)]}>
          <Icon name="info" size={14} />
          {s.over
            ? t('finance2.potOver', {
                amount: formatRupiah(s.spent, locale),
                budget: formatRupiah(s.budget, locale),
              })
            : t('finance2.potLeft', {
                remaining: formatRupiah(s.remaining, locale),
                budget: formatRupiah(s.budget, locale),
              })}
        </span>
      </span>
      <button
        className="btn btn--soft btn--sm"
        onClick={() => editPot(pot.id, { rollover: !pot.rollover })}
        aria-pressed={pot.rollover}
        title={t(pot.rollover ? 'finance2.rolloverOn' : 'finance2.rolloverOff')}
      >
        <Icon name={pot.rollover ? 'backup' : 'close'} size={16} />
        {t(pot.rollover ? 'finance2.rolloverOn' : 'finance2.rolloverOff')}
      </button>
      <button className="btn btn--soft btn--sm" onClick={() => removePot(pot.id, me)}>
        <Icon name="close" size={16} label={t('common.delete')} />
      </button>
    </li>
  )
}

function NewPot({ me, open, onClose }: { me: string; open: boolean; onClose: () => void }) {
  const { t } = useI18n()
  const [label, setLabel] = useState('')
  const [category, setCategory] = useState('')
  const [space, setSpace] = useState<MoneySpace>('shared')
  const [monthly, setMonthly] = useState('')
  const [rollover, setRollover] = useState(true)

  async function save() {
    if (!label.trim() || amountOf(monthly) <= 0) return
    await addPot(me, {
      label: label.trim(),
      category: (category.trim() || label.trim()),
      space,
      monthly: amountOf(monthly),
      rollover,
    })
    setLabel('')
    setCategory('')
    setMonthly('')
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={t('finance2.addPot')}>
      <div className="stack">
        <Field label={t('finance2.potName')}>
          {(p) => (
            <input
              {...p}
              type="text"
              value={label}
              placeholder={t('finance2.potNamePlaceholder')}
              onChange={(e) => setLabel(e.target.value)}
            />
          )}
        </Field>
        <Field label={t('finance2.potCategory')} hint={t('finance2.potCategoryHint')}>
          {(p) => (
            <input
              {...p}
              type="text"
              value={category}
              placeholder={label || t('finance2.potNamePlaceholder')}
              onChange={(e) => setCategory(e.target.value)}
            />
          )}
        </Field>
        <OptionList
          legend={t('finance2.potSpace')}
          options={MONEY_SPACES}
          value={space}
          onChange={setSpace}
          label={(s) => t(`finance2.space.${s}`)}
          describe={(s) => t(`finance2.space.${s}Hint`)}
        />
        <Field label={t('finance2.potMonthly')}>
          {(p) => (
            <input
              {...p}
              type="number"
              min="0"
              inputMode="numeric"
              value={monthly}
              onChange={(e) => setMonthly(e.target.value)}
            />
          )}
        </Field>
        <label className="row" style={{ gap: 'var(--space-2)' }}>
          <input type="checkbox" checked={rollover} onChange={(e) => setRollover(e.target.checked)} />
          <span style={{ fontSize: 13 }}>{t('finance2.potRollover')}</span>
        </label>
        <p className="field__hint">{t('finance2.potRolloverHint')}</p>
        <button
          className="btn btn--block"
          onClick={save}
          disabled={!label.trim() || amountOf(monthly) <= 0}
        >
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}
