import { CONTRIBUTION_PRESETS, allocate, type ContributionModel, type RuleTerms } from './money'

/**
 * The contribution calculator (FIN-02) — pure, no React, no Dexie, no copy.
 *
 * One job: take what this couple actually typed in and show what each of the
 * eight presets would mean for *them*, side by side.
 *
 * What it deliberately does not do:
 *   - rank the models, mark one "recommended", "fairest", or "best fit";
 *   - score the couple, or compare the two people to each other;
 *   - fill in a number nobody gave it and present it as theirs.
 *
 * There is no `score`, no `recommended` and no ordering key in the output, and
 * `CONTRIBUTION_PRESETS` fixes the order, so nothing downstream can sort by
 * "best" even by accident. Where an input is missing the model still shows its
 * base split, but the gap is named in `missing` and the screen prints it next to
 * the numbers — the numbers are arithmetic, and their basis is stated.
 */

/** An input a model needs. Message keys resolve these; this module has no copy. */
export type MissingInput = 'incomes' | 'needs' | 'fixed' | 'byCategory' | 'rotation' | 'payer'

export interface CalcInput {
  /** The amount being divided. Whole rupiah. */
  amount: number
  participants: string[]
  /** Whatever the couple has supplied — from their agreement or the form. */
  terms: Omit<RuleTerms, 'model'>
  /** Which category this expense is, for per-category ownership. */
  category?: string
  /** Position in a rotation, normally the count of expenses already recorded. */
  turn?: number
}

export interface ModelOutcome {
  model: ContributionModel
  /** profileId → whole rupiah. Always sums back to `amount` exactly. */
  shares: Record<string, number>
  /** Inputs this model needs that are not there yet. Empty means fully theirs. */
  missing: MissingInput[]
  complete: boolean
}

const anyPositive = (participants: string[], src: Record<string, number> | undefined): boolean =>
  participants.some((p) => (src?.[p] ?? 0) > 0)

/**
 * What a model is still waiting for. "Present but all zeroes" counts as missing:
 * an income of zero for both people is an empty form, not an agreement, and
 * `distribute` would quietly fall back to halves without saying so.
 */
function missingFor(model: ContributionModel, input: CalcInput): MissingInput[] {
  const { participants: who, terms } = input
  switch (model) {
    case 'proporsional':
      return anyPositive(who, terms.incomes) ? [] : ['incomes']
    case 'sesuai_kebutuhan':
      return [
        ...(anyPositive(who, terms.incomes) ? [] : (['incomes'] as const)),
        ...(anyPositive(who, terms.needs) ? [] : (['needs'] as const)),
      ]
    case 'nominal_tetap':
      return anyPositive(who, terms.fixed) ? [] : ['fixed']
    case 'campuran':
      return [
        ...(anyPositive(who, terms.fixed) ? [] : (['fixed'] as const)),
        ...(anyPositive(who, terms.incomes) ? [] : (['incomes'] as const)),
      ]
    case 'per_kategori': {
      const cat = input.category?.trim()
      const owner = cat ? terms.byCategory?.[cat] : undefined
      return owner && who.includes(owner) ? [] : ['byCategory']
    }
    case 'gantian': {
      const order = (terms.rotation ?? []).filter((p) => who.includes(p))
      return order.length > 1 ? [] : ['rotation']
    }
    case 'satu_pihak':
      return terms.payerProfileId && who.includes(terms.payerProfileId) ? [] : ['payer']
    case 'sama_rata':
    default:
      // Equal split needs nothing at all, which is exactly why couples reach for
      // it first — and exactly what the other seven rows are here to complicate.
      return []
  }
}

/**
 * The eight presets against one amount, in spec order. Same input, same output:
 * `allocate` is deterministic, so two people on two devices see the same table.
 */
export function compareModels(input: CalcInput): ModelOutcome[] {
  const participants = [...new Set(input.participants)].filter(Boolean)
  const amount = Math.max(0, Math.round(input.amount))
  return CONTRIBUTION_PRESETS.map((model) => {
    const missing = missingFor(model, input)
    // `gantian` with no agreed order still has to show something, so the fallback
    // is the participant order — named in `missing`, never presented as agreed.
    const rotation =
      input.terms.rotation && input.terms.rotation.length > 0 ? input.terms.rotation : participants
    const shares = allocate(
      amount,
      participants,
      { ...input.terms, model, rotation },
      {
        ...(input.category?.trim() ? { category: input.category.trim() } : {}),
        turn: input.turn ?? 0,
      },
    )
    return { model, shares, missing, complete: missing.length === 0 }
  })
}

/** Whose turn it is under a rotation, for the screen to name. */
export function turnHolder(
  participants: string[],
  rotation: string[] | undefined,
  turn: number,
): string | undefined {
  const ring = (rotation ?? []).filter((p) => participants.includes(p))
  const order = ring.length > 0 ? ring : participants
  if (order.length === 0) return undefined
  const n = Number.isFinite(turn) ? Math.max(0, Math.trunc(turn)) : 0
  return order[n % order.length]
}
