/**
 * Uang berdua (FIN-01/02/04) — the money module.
 *
 * The whole feature turns on one idea from the spec: a money object is not
 * "mine" or "ours", it is four separate answers — ownership, visibility,
 * responsibility, decision rights. They are stored separately because couples
 * really do split them (her account, both can see it, he pays it from there,
 * only she decides). Collapsing them into one flag is what makes most joint
 * finance tools feel like surveillance.
 *
 * Nothing here compares the two people. There is no spender ranking, no
 * "who contributed more" — only positions and what was agreed.
 */

type Tab =
  | 'summary'
  | 'spaces'
  | 'splits'
  | 'bills'
  | 'envelopes'
  | 'income'
  | 'savings'
  | 'debts'
  | 'arisan'
  | 'categories'
  | 'agreement'
  | 'proposals'
  | 'review'
  | 'privacy'
const TABS: readonly Tab[] = [
  'summary',
  'spaces',
  'splits',
  'bills',
  'envelopes',
  'income',
  'savings',
  'debts',
  'arisan',
  'categories',
  'agreement',
  'proposals',
  'review',
  'privacy',
]

