function Spaces({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const { partner } = useSession()
  const nameOf = useNameOf()
  const people = useParticipants()
  const [asPartner, setAsPartner] = useState(false)
  const [creating, setCreating] = useState(false)
  const [openId, setOpenId] = useState<string | null>(null)

  const accounts = useFinance<'accounts'>('accounts', me, (a, b) => a.name.localeCompare(b.name))
  const entries = useFinance<'ledger'>('ledger', me)

  // The preview answers "what does my partner actually see of my accounts?"
  // using the same pure functions the real partner session would use, so it can
  // never drift from the truth. Their own accounts are left out — this is a
  // check on my own disclosure choices, not a window into theirs.
  const viewer = asPartner && partner ? partner.id : me
  const pool = (accounts ?? []).filter((a) => viewer === me || a.ownerProfileId === me)
  // Saya / kamu / kita are a view, not a stored label: the same account is
  // "uang saya" to its owner and "uang kamu" to their partner. `partitionSpaces`
  // is also the leak gate — a row the viewer may not see reaches no space at all.
  const view = partitionSpaces(pool, viewer)
  const shownCount = VIEWER_SPACES.reduce((n, s) => n + view[s].length, 0)
  // Only ever a count of *my own* accounts, told to me. Never the reverse.
  const hidden = asPartner ? pool.length - shownCount : 0

  const open = (accounts ?? []).find((a) => a.id === openId) ?? null

  return (
    <div className="stack">
      {partner && (
        <div className="row row--between">
          <button
            className={asPartner ? 'btn btn--sm' : 'btn btn--soft btn--sm'}
            onClick={() => setAsPartner((v) => !v)}
          >
            <Icon name={asPartner ? 'private' : 'shared'} size={16} />
            {asPartner
              ? t('finance2.partnerViewOff')
              : t('finance2.partnerView', { name: partner.displayName })}
          </button>
          <button className="btn btn--sm" onClick={() => setCreating(true)}>
            <Icon name="plus" size={16} /> {t('finance2.addAccount')}
          </button>
        </div>
      )}
      {!partner && (
        <div className="row row--between">
          <span className="card__hint">{t('finance2.noPartner')}</span>
          <button className="btn btn--sm" onClick={() => setCreating(true)}>
            <Icon name="plus" size={16} /> {t('finance2.addAccount')}
          </button>
        </div>
      )}

      {asPartner && partner && (
        <p className="banner">
          <Icon name="info" size={16} />
          {t('finance2.partnerViewOn', { name: partner.displayName })}
          {hidden > 0 ? ` · ${t('finance2.hiddenCount', { n: hidden })}` : ''}
        </p>
      )}

      {VIEWER_SPACES.map((space) => {
        const list = view[space]
        const sums = spaceTotal(list, viewer)
        return (
          <Card
            key={space}
            title={t(`finance2.space.${space}`)}
            icon="money"
            hint={t(`finance2.space.${space}Hint`)}
          >
            {list.length === 0 ? (
              <EmptyState
                icon="money"
                title={t('finance2.noAccounts')}
                hint={t(space === 'kamu' ? 'finance2.noAccountsKamuHint' : 'finance2.noAccountsHint')}
              />
            ) : (
              <>
                {sums.counted > 0 && (
                  <p className="card__hint">
                    {t('finance2.spaceTotal', {
                      amount: formatRupiah(sums.total, locale),
                      n: sums.counted,
                    })}
                  </p>
                )}
                <ul className="list">
                {list.map((a) => {
                  const fields = visibleFields(a, viewer)
                  const mine = (entries ?? []).filter((e) => e.accountId === a.id)
                  const planned = mine.filter((e) => e.planned && e.amount < 0)
                  const sts = safeToSpend({
                    balance: a.balance,
                    today: format(new Date(), 'yyyy-MM-dd'),
                    paydayDom: a.paydayDom,
                    planned: planned.map((e) => ({
                      amount: -e.amount,
                      ...(e.dueDate ? { dueDate: e.dueDate } : {}),
                    })),
                  })
                  const showBalance = fields.balance
                  return (
                    <li key={a.id} className="list__item" style={{ alignItems: 'flex-start' }}>
                      <Icon name="money" size={18} />
                      <span className="grow stack stack--tight">
                        <strong style={{ fontSize: 14 }}>{a.name}</strong>
                        <span className="card__hint">
                          {t('finance2.owner', { name: nameOf(a.ownerProfileId) })}
                          {showBalance ? ` · ${formatRupiah(a.balance, locale)}` : ''}
                        </span>
                        {showBalance && (
                          <span className="card__hint">
                            {t('finance2.safeToSpend')}:{' '}
                            {sts.low === sts.high
                              ? t('finance2.safeToSpendExact', {
                                  amount: formatRupiah(sts.low, locale),
                                  until: whenLabel(sts.until, t, locale),
                                })
                              : t('finance2.safeToSpendRange', {
                                  low: formatRupiah(sts.low, locale),
                                  high: formatRupiah(sts.high, locale),
                                  until: whenLabel(sts.until, t, locale),
                                })}
                            {planned.length > 0
                              ? ` · ${t('finance2.plannedCount', { n: planned.length })}`
                              : ''}
                          </span>
                        )}
                        <span className="row" style={{ flexWrap: 'wrap', gap: 'var(--space-1)' }}>
                          <span className={a.disclosure === 'privat' ? 'chip' : 'chip--mint chip'}>
                            <Icon name={a.disclosure === 'privat' ? 'private' : 'shared'} size={14} />
                            {t(`finance2.vis.${a.disclosure}`)}
                          </span>
                          {a.responsibleProfileIds.length > 0 && (
                            <span className="chip chip--blue">
                              <Icon name="check" size={14} />
                              {a.responsibleProfileIds.map(nameOf).join(' · ')}
                            </span>
                          )}
                        </span>
                      </span>
                      <button className="btn btn--soft btn--sm" onClick={() => setOpenId(a.id)}>
                        <Icon name="chevron-right" size={16} label={a.name} />
                      </button>
                    </li>
                  )
                })}
                </ul>
              </>
            )}
          </Card>
        )
      })}

      <NewAccount
        me={me}
        people={people}
        open={creating}
        onClose={() => setCreating(false)}
      />
      <AccountSheet
        me={me}
        account={open}
        entries={(entries ?? []).filter((e) => e.accountId === openId)}
        onClose={() => setOpenId(null)}
      />
    </div>
  )
}

const today = () => format(new Date(), 'yyyy-MM-dd')

function NewAccount({
  me,
  people,
  open,
  onClose,
}: {
  me: string
  people: string[]
  open: boolean
  onClose: () => void
}) {
  const { t } = useI18n()
  const [name, setName] = useState('')
  const [space, setSpace] = useState<MoneySpace>('mine')
  const [balance, setBalance] = useState('')
  const [payday, setPayday] = useState('25')
  const [responsible, setResponsible] = useState<string[]>([me])
  const [decider, setDecider] = useState<string[]>([me])
  const [disclosure, setDisclosure] = useState<Disclosure>('privat')

  // The space is a shorthand for the three *defaults*, never a lock. All four
  // answers stay separate fields below, and the owner can move any one of them
  // without touching the others.
  function pickSpace(next: MoneySpace) {
    setSpace(next)
    const d = defaultRights(me, next, people.find((p) => p !== me))
    setDisclosure(d.disclosure)
    setResponsible(d.responsibleProfileIds)
    setDecider(d.deciderProfileIds)
  }

  async function save() {
    if (!name.trim()) return
    await addFinance(
      'accounts',
      me,
      space === 'shared' ? 'C2_shared_ops' : 'C1_personal',
      {
        kind: 'account',
        name: name.trim(),
        space,
        balance: amountOf(balance),
        responsibleProfileIds: responsible,
        deciderProfileIds: decider,
        disclosure,
        paydayDom: Math.min(31, Math.max(1, amountOf(payday) || 25)),
      },
      { visibility: disclosure === 'privat' ? 'private' : 'shared' },
    )
    setName('')
    setBalance('')
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={t('finance2.addAccount')}>
      <div className="stack">
        <Field label={t('finance2.accountName')}>
          {(p) => (
            <input
              {...p}
              type="text"
              value={name}
              placeholder={t('finance2.accountNamePlaceholder')}
              onChange={(e) => setName(e.target.value)}
            />
          )}
        </Field>
        <OptionList
          legend={t('finance2.accountSpace')}
          options={MONEY_SPACES}
          value={space}
          onChange={pickSpace}
          label={(s) => t(`finance2.space.${s}`)}
          describe={(s) => t(`finance2.space.${s}Hint`)}
        />
        <Field label={t('finance2.balance')}>
          {(p) => (
            <input
              {...p}
              type="number"
              min="0"
              inputMode="numeric"
              value={balance}
              onChange={(e) => setBalance(e.target.value)}
            />
          )}
        </Field>
        <Field label={t('finance2.payday')} hint={t('finance2.paydayHint')}>
          {(p) => (
            <input
              {...p}
              type="number"
              min="1"
              max="31"
              inputMode="numeric"
              value={payday}
              onChange={(e) => setPayday(e.target.value)}
            />
          )}
        </Field>
        <PeoplePicker
          legend={t('finance2.responsible')}
          hint={t('finance2.pickHint')}
          people={people}
          value={responsible}
          onChange={setResponsible}
        />
        <PeoplePicker
          legend={t('finance2.decider')}
          hint={t('finance2.pickHint')}
          people={people}
          value={decider}
          onChange={setDecider}
        />
        <OptionList
          legend={t('finance2.disclosure')}
          options={DISCLOSURES}
          value={disclosure}
          onChange={setDisclosure}
          label={(d) => t(`finance2.vis.${d}`)}
          describe={(d) => t(`finance2.vis.${d}Desc`)}
        />
        <button className="btn btn--block" onClick={save} disabled={!name.trim()}>
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}

function AccountSheet({
  me,
  account,
  entries,
  onClose,
}: {
  me: string
  account: FinanceAccount | null
  entries: LedgerEntry[]
  onClose: () => void
}) {
  const { t, locale } = useI18n()
  const nameOf = useNameOf()
  const people = useParticipants()
  const [label, setLabel] = useState('')
  const [amount, setAmount] = useState('')
  const [category, setCategory] = useState('')
  const [dir, setDir] = useState<'out' | 'in'>('out')
  const [date, setDate] = useState(today)
  const [planned, setPlanned] = useState(false)
  const [due, setDue] = useState('')
  // Null means "whatever the account says". A bill on her account that he pays
  // is an ordinary arrangement, so the row may carry its own answer.
  const [entryResponsible, setEntryResponsible] = useState<string[] | null>(null)
  const [entryDecider, setEntryDecider] = useState<string[] | null>(null)
  // F23: a widening of visibility is an explicit act, never a stray tap. A change
  // that lets the partner see *more* is held here until confirmed; narrowing
  // applies straight away — closing a door should never be slowed down.
  const [pendingDisclosure, setPendingDisclosure] = useState<Disclosure | null>(null)

  const owner = account?.ownerProfileId === me
  const totals = useMemo(() => categoryTotals(entries), [entries])
  const accountRights = account ? resolveRights(account) : null
  const responsible = entryResponsible ?? accountRights?.responsibleProfileIds ?? []
  const decider = entryDecider ?? accountRights?.deciderProfileIds ?? []

  async function addEntry() {
    if (!account || !label.trim()) return
    const signed = dir === 'out' ? -amountOf(amount) : amountOf(amount)
    if (signed === 0) return
    await addFinance(
      'ledger',
      me,
      account.dataClass,
      {
        kind: 'ledger',
        accountId: account.id,
        label: label.trim(),
        amount: signed,
        category: category.trim() || t('finance2.entryCategoryPlaceholder'),
        date,
        planned,
        ...(planned && due ? { dueDate: due } : {}),
        // Frozen on the row, not looked up later: who was on the hook for this
        // bill is part of what happened, and it must survive the account's
        // arrangement changing next month.
        responsibleProfileIds: responsible,
        deciderProfileIds: decider,
      },
      // Entries inherit the account's visibility: opening a bank statement is
      // the owner's decision, and it should be one decision, not one per row.
      { visibility: account.visibility },
    )
    // A real (not planned) entry moves the balance. Planned ones only reserve
    // money in the safe-to-spend estimate until they are marked paid.
    if (!planned) await patchFinance('accounts', account.id, { balance: account.balance + signed })
    setLabel('')
    setAmount('')
    setCategory('')
    setDue('')
    setEntryResponsible(null)
    setEntryDecider(null)
  }

  async function markPaid(e: LedgerEntry) {
    if (!account) return
    await patchFinance('ledger', e.id, { planned: false })
    await patchFinance('accounts', account.id, { balance: account.balance + e.amount })
  }

  return (
    <Sheet open={account !== null} onClose={onClose} title={account?.name ?? t('finance2.title')}>
      {account && (
        <div className="stack">
          <div className="row" style={{ flexWrap: 'wrap', gap: 'var(--space-1)' }}>
            <VisibilityBadge visibility={account.visibility} />
            <span className="chip">
              <Icon name="money" size={14} />
              {formatRupiah(account.balance, locale)}
            </span>
            <span className="chip chip--lavender">
              <Icon name="self" size={14} />
              {t('finance2.owner', { name: nameOf(account.ownerProfileId) })}
            </span>
          </div>

          <OptionList
            legend={t('finance2.disclosure')}
            options={DISCLOSURES}
            value={account.disclosure}
            onChange={(d) => {
              if (requiresConfirm(account.disclosure, d)) setPendingDisclosure(d)
              else void setAccountDisclosure(account.id, me, d)
            }}
            label={(d) => t(`finance2.vis.${d}`)}
            describe={(d) => t(`finance2.vis.${d}Desc`)}
            disabled={!owner}
          />
          <p className="field__hint">
            {owner
              ? t('finance2.disclosureHint')
              : t('finance2.onlyOwnerCanShare', { name: nameOf(account.ownerProfileId) })}
          </p>

          <Sheet
            open={pendingDisclosure !== null}
            onClose={() => setPendingDisclosure(null)}
            title={t('finance2.trans.confirmTitle')}
          >
            <div className="stack">
              <p>
                {t('finance2.trans.confirmBody', {
                  level: pendingDisclosure ? t(`finance2.vis.${pendingDisclosure}`) : '',
                })}
              </p>
              <p className="field__hint">{t('finance2.trans.confirmHint')}</p>
              <button
                className="btn btn--block"
                onClick={() => {
                  if (pendingDisclosure) void setAccountDisclosure(account.id, me, pendingDisclosure)
                  setPendingDisclosure(null)
                }}
              >
                {t('finance2.trans.confirmYes')}
              </button>
              <button className="btn btn--soft btn--block" onClick={() => setPendingDisclosure(null)}>
                {t('common.cancel')}
              </button>
            </div>
          </Sheet>

          {account.deciderProfileIds.length > 0 && (
            <p className="card__hint">
              {t('finance2.decider')}: {account.deciderProfileIds.map(nameOf).join(' · ')}
            </p>
          )}

          {totals.length > 0 && (
            <div className="stack stack--tight">
              <strong style={{ fontSize: 13 }}>{t('finance2.byCategory')}</strong>
              <ul className="list">
                {totals.map((c) => (
                  <li key={c.category} className="list__item">
                    <Icon name="money" size={16} />
                    <span className="grow">{c.category}</span>
                    <span>{formatRupiah(c.amount, locale)}</span>
                  </li>
                ))}
              </ul>
            </div>
          )}

          <div className="stack stack--tight">
            <strong style={{ fontSize: 13 }}>{t('finance2.recentEntries')}</strong>
            {entries.length === 0 ? (
              <p className="card__hint">{t('finance2.noEntries')}</p>
            ) : (
              <ul className="list">
                {[...entries]
                  .sort((a, b) => b.date.localeCompare(a.date))
                  .slice(0, 12)
                  .map((e) => (
                    <li key={e.id} className="list__item">
                      <Icon name={e.amount < 0 ? 'money' : 'backup'} size={16} />
                      <span className="grow stack stack--tight">
                        <span style={{ fontSize: 14 }}>{e.label}</span>
                        <span className="card__hint">
                          {whenLabel(e.date, t, locale)} · {e.category}
                          {e.planned ? ` · ${t('finance2.plannedTag')}` : ''}
                        </span>
                        <span className="card__hint">
                          {t('finance2.entryResponsible', {
                            names:
                              resolveRights(e, account).responsibleProfileIds.map(nameOf).join(' · ') ||
                              t('finance2.rightsUndecided'),
                          })}
                        </span>
                      </span>
                      <span>{formatRupiah(e.amount, locale)}</span>
                      {e.planned && (
                        <button className="btn btn--soft btn--sm" onClick={() => markPaid(e)}>
                          <Icon name="check" size={16} label={t('finance2.markSettled')} />
                        </button>
                      )}
                    </li>
                  ))}
              </ul>
            )}
          </div>

          <details>
            <summary style={{ fontSize: 13, fontWeight: 700, cursor: 'pointer' }}>
              {t('finance2.addEntry')}
            </summary>
            <div className="stack" style={{ marginTop: 'var(--space-2)' }}>
              <Field label={t('finance2.entryLabel')}>
                {(p) => (
                  <input {...p} type="text" value={label} onChange={(x) => setLabel(x.target.value)} />
                )}
              </Field>
              <Field label={t('finance2.entryAmount')}>
                {(p) => (
                  <input
                    {...p}
                    type="number"
                    min="0"
                    inputMode="numeric"
                    value={amount}
                    onChange={(x) => setAmount(x.target.value)}
                  />
                )}
              </Field>
              <OptionList
                legend={t('finance2.entryDirection')}
                options={['out', 'in'] as const}
                value={dir}
                onChange={setDir}
                label={(d) => (d === 'out' ? t('finance2.dirOut') : t('finance2.dirIn'))}
              />
              <Field label={t('finance2.entryCategory')}>
                {(p) => (
                  <input
                    {...p}
                    type="text"
                    value={category}
                    placeholder={t('finance2.entryCategoryPlaceholder')}
                    onChange={(x) => setCategory(x.target.value)}
                  />
                )}
              </Field>
              <Field label={t('finance2.entryDate')}>
                {(p) => (
                  <input {...p} type="date" value={date} onChange={(x) => setDate(x.target.value)} />
                )}
              </Field>
              <label className="row" style={{ gap: 'var(--space-2)' }}>
                <input
                  type="checkbox"
                  checked={planned}
                  onChange={(x) => setPlanned(x.target.checked)}
                />
                <span style={{ fontSize: 13 }}>{t('finance2.entryPlanned')}</span>
              </label>
              {planned && (
                <Field label={t('finance2.entryDue')} hint={t('finance2.entryDueHint')}>
                  {(p) => (
                    <input {...p} type="date" value={due} onChange={(x) => setDue(x.target.value)} />
                  )}
                </Field>
              )}
              <PeoplePicker
                legend={t('finance2.responsible')}
                hint={t('finance2.entryRightsHint')}
                people={people}
                value={responsible}
                onChange={setEntryResponsible}
              />
              {planned && (
                <PeoplePicker
                  legend={t('finance2.decider')}
                  hint={t('finance2.entryRightsHint')}
                  people={people}
                  value={decider}
                  onChange={setEntryDecider}
                />
              )}
              <button className="btn btn--block" onClick={addEntry} disabled={!label.trim() || !amount}>
                {t('common.save')}
              </button>
            </div>
          </details>

          <p className="disclaimer">{t('finance2.safeToSpendCaveat')}</p>

          {owner && (
            <button
              className="btn btn--danger btn--block"
              onClick={async () => {
                await removeFinance('accounts', account.id, me)
                onClose()
              }}
            >
              <Icon name="close" size={16} /> {t('finance2.deleteAccount')}
            </button>
          )}
        </div>
      )}
    </Sheet>
  )
}
