import { useState } from 'react'
import { format } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { useI18n } from '@/i18n'
import { formatRupiah, whenLabel } from '@/i18n/format'
import { OptionList, PeoplePicker, amountOf, useNameOf, useParticipants } from './parts'
import { addFinance, useFinance } from './store'
import { CONTRIBUTION_MODELS, ruleAt, type ContributionModel } from './money'

/**
 * Kesepakatan — how the couple divides money, with a date attached.
 *
 * Writing a new agreement never edits the old one. That is the point: the
 * question "why was March split like that?" has to stay answerable after the
 * couple changes their minds in July.
 */
export default function Agreements({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const nameOf = useNameOf()
  const people = useParticipants()
  const [open, setOpen] = useState(false)

  const rules = useFinance('contributionRules', me, (a, b) => a.createdAt.localeCompare(b.createdAt))
  const today = format(new Date(), 'yyyy-MM-dd')
  const active = ruleAt(rules ?? [], today)
  const newestFirst = [...(rules ?? [])].reverse()

  return (
    <div className="stack">
      <Card
        title={t('finance2.agreementTitle')}
        icon="mentalload"
        hint={t('finance2.agreementHint')}
        action={
          <button className="btn btn--sm" onClick={() => setOpen(true)}>
            <Icon name="plus" size={16} /> {t('finance2.addAgreement')}
          </button>
        }
      >
        {newestFirst.length === 0 ? (
          <EmptyState
            icon="mentalload"
            title={t('finance2.noAgreement')}
            hint={t('finance2.noAgreementHint')}
          />
        ) : (
          <ul className="list">
            {newestFirst.map((r, i) => {
              // Everything above this row in the list starts later, so the first
              // one of those is what replaced it.
              const replacedBy = newestFirst[i - 1]
              return (
                <li key={r.id} className="list__item" style={{ alignItems: 'flex-start' }}>
                  <Icon name="mentalload" size={18} />
                  <span className="grow stack stack--tight">
                    <strong style={{ fontSize: 14 }}>{t(`finance2.model.${r.model}`)}</strong>
                    <span className="card__hint">
                      {t('finance2.activeSince', { date: whenLabel(r.effectiveFrom, t, locale) })}
                      {replacedBy
                        ? ` · ${t('finance2.supersededBy', {
                            date: whenLabel(replacedBy.effectiveFrom, t, locale),
                          })}`
                        : ''}
                    </span>
                    <span className="card__hint">
                      {t('finance2.thresholdSummary', {
                        notify: formatRupiah(r.notifyAbove, locale),
                        agree: formatRupiah(r.agreeAbove, locale),
                      })}
                    </span>
                    {r.incomes && (
                      <span className="card__hint">
                        {Object.entries(r.incomes)
                          .map(
                            ([p, v]) =>
                              `${t('finance2.incomeOf', { name: nameOf(p) })}: ${formatRupiah(v, locale)}`,
                          )
                          .join(' · ')}
                      </span>
                    )}
                    {r.model === 'gantian' && r.rotation && r.rotation.length > 0 && (
                      <span className="card__hint">
                        {t('finance2.rotationHint', { names: r.rotation.map(nameOf).join(' → ') })}
                      </span>
                    )}
                    {r.note && <span className="card__hint">{r.note}</span>}
                    {r.id === active?.id && (
                      <span className="chip chip--mint">
                        <Icon name="check" size={14} />
                        {t('finance2.activeNow')}
                      </span>
                    )}
                  </span>
                </li>
              )
            })}
          </ul>
        )}
      </Card>

      <NewAgreement me={me} people={people} open={open} onClose={() => setOpen(false)} />
    </div>
  )
}

function NewAgreement({
  me,
  people,
  open,
  onClose,
}: {
  me: string
  people: string[]
  open: boolean
  onClose: () => void
}) {
  const { t } = useI18n()
  const nameOf = useNameOf()
  const [model, setModel] = useState<ContributionModel>('sama_rata')
  const [from, setFrom] = useState(() => format(new Date(), 'yyyy-MM-dd'))
  const [incomes, setIncomes] = useState<Record<string, string>>({})
  const [needs, setNeeds] = useState<Record<string, string>>({})
  const [fixed, setFixed] = useState<Record<string, string>>({})
  const [shares, setShares] = useState<Record<string, string>>({})
  const [rotation, setRotation] = useState<string[]>(people)
  const [payer, setPayer] = useState<string[]>([me])
  const [cats, setCats] = useState<{ category: string; who: string }[]>([])
  const [notify, setNotify] = useState('500000')
  const [agree, setAgree] = useState('2000000')
  const [note, setNote] = useState('')

  const numbers = (src: Record<string, string>) =>
    Object.fromEntries(people.map((p) => [p, amountOf(src[p] ?? '')]))

  async function save() {
    await addFinance('contributionRules', me, 'C2_shared_ops', {
      kind: 'rule',
      model,
      effectiveFrom: from,
      notifyAbove: amountOf(notify),
      agreeAbove: amountOf(agree),
      // Two models need income, three need a fixed amount, one needs both plus
      // the essentials — so the terms are written per model rather than wholesale.
      ...(model === 'proporsional' || model === 'sesuai_kebutuhan' || model === 'campuran'
        ? { incomes: numbers(incomes) }
        : {}),
      ...(model === 'sesuai_kebutuhan' ? { needs: numbers(needs) } : {}),
      ...(model === 'nominal_tetap' || model === 'campuran' ? { fixed: numbers(fixed) } : {}),
      ...(model === 'kesepakatan' ? { shares: numbers(shares) } : {}),
      ...(model === 'gantian' ? { rotation } : {}),
      ...(model === 'satu_pihak' ? { payerProfileId: payer[0] ?? me } : {}),
      ...(model === 'per_kategori'
        ? {
            byCategory: Object.fromEntries(
              cats.filter((c) => c.category.trim()).map((c) => [c.category.trim(), c.who]),
            ),
          }
        : {}),
      ...(note.trim() ? { note: note.trim() } : {}),
    })
    setNote('')
    onClose()
  }

  const perPerson = (
    label: (name: string) => string,
    value: Record<string, string>,
    set: (next: Record<string, string>) => void,
  ) => (
    <>
      {people.map((p) => (
        <Field key={p} label={label(nameOf(p))}>
          {(props) => (
            <input
              {...props}
              type="number"
              min="0"
              inputMode="numeric"
              value={value[p] ?? ''}
              onChange={(e) => set({ ...value, [p]: e.target.value })}
            />
          )}
        </Field>
      ))}
    </>
  )

  return (
    <Sheet open={open} onClose={onClose} title={t('finance2.addAgreement')}>
      <div className="stack">
        <OptionList
          legend={t('finance2.model')}
          options={CONTRIBUTION_MODELS}
          value={model}
          onChange={setModel}
          label={(m) => t(`finance2.model.${m}`)}
          describe={(m) => t(`finance2.model.${m}Desc`)}
        />
        <Field label={t('finance2.effectiveFrom')}>
          {(p) => <input {...p} type="date" value={from} onChange={(e) => setFrom(e.target.value)} />}
        </Field>

        {(model === 'proporsional' || model === 'sesuai_kebutuhan' || model === 'campuran') &&
          perPerson((n) => t('finance2.incomeOf', { name: n }), incomes, setIncomes)}
        {model === 'sesuai_kebutuhan' && (
          <>
            <p className="field__hint">{t('finance2.needsHint')}</p>
            {perPerson((n) => t('finance2.needsOf', { name: n }), needs, setNeeds)}
          </>
        )}
        {(model === 'nominal_tetap' || model === 'campuran') &&
          perPerson((n) => t('finance2.fixedOf', { name: n }), fixed, setFixed)}
        {model === 'kesepakatan' &&
          perPerson((n) => t('finance2.shareOf', { name: n }), shares, setShares)}

        {model === 'gantian' && (
          <PeoplePicker
            legend={t('finance2.model.gantian')}
            hint={t('finance2.rotationHint', { names: rotation.map(nameOf).join(' → ') })}
            people={people}
            value={rotation}
            onChange={setRotation}
          />
        )}

        {model === 'satu_pihak' && (
          <PeoplePicker
            legend={t('finance2.payerPick')}
            people={people}
            value={payer}
            onChange={setPayer}
            single
          />
        )}

        {model === 'per_kategori' && (
          <div className="stack stack--tight">
            <strong style={{ fontSize: 13 }}>{t('finance2.categoryMap')}</strong>
            <span className="field__hint">{t('finance2.categoryMapHint')}</span>
            {cats.map((c, i) => (
              <div key={i} className="stack stack--tight">
                <Field label={t('finance2.splitCategory')}>
                  {(p) => (
                    <input
                      {...p}
                      type="text"
                      value={c.category}
                      placeholder={t('finance2.entryCategoryPlaceholder')}
                      onChange={(e) =>
                        setCats(cats.map((x, j) => (j === i ? { ...x, category: e.target.value } : x)))
                      }
                    />
                  )}
                </Field>
                <PeoplePicker
                  legend={t('finance2.payerPick')}
                  people={people}
                  value={[c.who]}
                  onChange={(next) =>
                    setCats(cats.map((x, j) => (j === i ? { ...x, who: next[0] ?? me } : x)))
                  }
                  single
                />
              </div>
            ))}
            <button
              className="btn btn--soft btn--sm"
              onClick={() => setCats([...cats, { category: '', who: me }])}
            >
              <Icon name="plus" size={16} /> {t('finance2.addCategory')}
            </button>
          </div>
        )}

        <Field label={t('finance2.notifyAbove')} hint={t('finance2.thresholdHint')}>
          {(p) => (
            <input
              {...p}
              type="number"
              min="0"
              inputMode="numeric"
              value={notify}
              onChange={(e) => setNotify(e.target.value)}
            />
          )}
        </Field>
        <Field label={t('finance2.agreeAbove')}>
          {(p) => (
            <input
              {...p}
              type="number"
              min="0"
              inputMode="numeric"
              value={agree}
              onChange={(e) => setAgree(e.target.value)}
            />
          )}
        </Field>
        <Field label={t('finance2.agreementNote')} hint={t('common.optional')}>
          {(p) => (
            <input
              {...p}
              type="text"
              value={note}
              placeholder={t('finance2.agreementNotePlaceholder')}
              onChange={(e) => setNote(e.target.value)}
            />
          )}
        </Field>

        <button className="btn btn--block" onClick={save}>
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}
