import { useMemo, useState } from 'react'
import { format } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { useI18n } from '@/i18n'
import { formatRupiah, whenLabel } from '@/i18n/format'
import { PeoplePicker, amountOf, useNameOf, useParticipants } from './parts'
import { addFinance, patchFinance, useFinance, type ContributionRule } from './store'
import { allocate, ruleAt, settlement } from './money'

/**
 * Bagi & saldo — shared expenses and the settlement position.
 *
 * A split freezes the shares it was created with. The couple can change how
 * they split next month without silently rewriting what March meant, which is
 * the whole reason the agreements are effective-dated.
 */
export default function Splits({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const nameOf = useNameOf()
  const people = useParticipants()
  const [open, setOpen] = useState(false)

  const rules = useFinance('contributionRules', me, (a, b) => a.createdAt.localeCompare(b.createdAt))
  const splits = useFinance('splits', me, (a, b) => b.date.localeCompare(a.date))

  const owing = useMemo(() => settlement(splits ?? []), [splits])

  return (
    <div className="stack">
      <Card
        title={t('finance2.settlement')}
        icon="money"
        hint={t('finance2.splitsHint')}
      >
        {/* One neutral line: a position, never a comparison of the two people. */}
        <p className="banner">
          <Icon name="info" size={16} />
          {owing
            ? t('finance2.settlementLine', {
                name: nameOf(owing.debtorProfileId),
                amount: formatRupiah(owing.amount, locale),
              })
            : t('finance2.settlementClear')}
        </p>
      </Card>

      <Card
        title={t('finance2.splitsTitle')}
        icon="money"
        action={
          <button className="btn btn--sm" onClick={() => setOpen(true)}>
            <Icon name="plus" size={16} /> {t('finance2.addSplit')}
          </button>
        }
      >
        {(splits ?? []).length === 0 ? (
          <EmptyState
            icon="money"
            title={t('finance2.noSplits')}
            hint={t('finance2.noSplitsHint')}
          />
        ) : (
          <ul className="list">
            {(splits ?? []).map((s) => (
              <li key={s.id} className="list__item" style={{ alignItems: 'flex-start' }}>
                <Icon name="money" size={18} />
                <span className="grow stack stack--tight">
                  <strong style={{ fontSize: 14 }}>{s.label}</strong>
                  <span className="card__hint">
                    {whenLabel(s.date, t, locale)} · {formatRupiah(s.amount, locale)} ·{' '}
                    {t('finance2.splitPaidBy')}: {nameOf(s.paidByProfileId)}
                  </span>
                  <span className="card__hint">
                    {t('finance2.splitPreview', {
                      detail: Object.entries(s.shares)
                        .map(([p, v]) =>
                          t('finance2.sharePart', { name: nameOf(p), amount: formatRupiah(v, locale) }),
                        )
                        .join(' · '),
                    })}
                  </span>
                  <span className="chip chip--lavender">
                    <Icon name="check" size={14} />
                    {t(`finance2.model.${s.model}`)}
                  </span>
                </span>
                {s.settledAt ? (
                  <span className="chip chip--mint">
                    <Icon name="check" size={14} />
                    {t('finance2.settledOn', { date: whenLabel(s.settledAt, t, locale) })}
                  </span>
                ) : (
                  <button
                    className="btn btn--soft btn--sm"
                    onClick={() =>
                      patchFinance('splits', s.id, { settledAt: format(new Date(), 'yyyy-MM-dd') })
                    }
                  >
                    {t('finance2.markSettled')}
                  </button>
                )}
              </li>
            ))}
          </ul>
        )}
      </Card>

      <NewSplit
        me={me}
        people={people}
        rules={rules ?? []}
        turn={(splits ?? []).length}
        open={open}
        onClose={() => setOpen(false)}
      />
    </div>
  )
}

function NewSplit({
  me,
  people,
  rules,
  turn,
  open,
  onClose,
}: {
  me: string
  people: string[]
  rules: ContributionRule[]
  /** How many splits already exist — the position in a `gantian` rotation. */
  turn: number
  open: boolean
  onClose: () => void
}) {
  const { t, locale } = useI18n()
  const nameOf = useNameOf()
  const [label, setLabel] = useState('')
  const [amount, setAmount] = useState('')
  const [category, setCategory] = useState('')
  const [date, setDate] = useState(() => format(new Date(), 'yyyy-MM-dd'))
  const [paidBy, setPaidBy] = useState<string[]>([me])

  // The rule is looked up by the expense's own date, not today's — that is what
  // makes "a change never overwrites history" true rather than a slogan.
  const rule = ruleAt(rules, date)
  const shares = rule
    ? allocate(amountOf(amount), people, rule, {
        ...(category.trim() ? { category: category.trim() } : {}),
        turn,
      })
    : {}

  async function save() {
    if (!rule || !label.trim() || amountOf(amount) <= 0) return
    await addFinance('splits', me, 'C2_shared_ops', {
      kind: 'split',
      label: label.trim(),
      amount: amountOf(amount),
      category: category.trim(),
      date,
      paidByProfileId: paidBy[0] ?? me,
      model: rule.model,
      shares,
    })
    setLabel('')
    setAmount('')
    setCategory('')
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={t('finance2.addSplit')}>
      <div className="stack">
        <Field label={t('finance2.splitLabel')}>
          {(p) => <input {...p} type="text" value={label} onChange={(e) => setLabel(e.target.value)} />}
        </Field>
        <Field label={t('finance2.splitAmount')}>
          {(p) => (
            <input
              {...p}
              type="number"
              min="0"
              inputMode="numeric"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
            />
          )}
        </Field>
        <Field label={t('finance2.splitCategory')}>
          {(p) => (
            <input
              {...p}
              type="text"
              value={category}
              placeholder={t('finance2.entryCategoryPlaceholder')}
              onChange={(e) => setCategory(e.target.value)}
            />
          )}
        </Field>
        <Field label={t('finance2.splitDate')}>
          {(p) => <input {...p} type="date" value={date} onChange={(e) => setDate(e.target.value)} />}
        </Field>
        <PeoplePicker
          legend={t('finance2.splitPaidBy')}
          people={people}
          value={paidBy}
          onChange={setPaidBy}
          single
        />

        {rule ? (
          <div className="stack stack--tight">
            <p className="card__hint">
              {t('finance2.usingRule', {
                model: t(`finance2.model.${rule.model}`),
                date: whenLabel(rule.effectiveFrom, t, locale),
              })}
            </p>
            <p className="banner">
              <Icon name="info" size={16} />
              {t('finance2.splitPreview', {
                detail: Object.entries(shares)
                  .map(([p, v]) =>
                    t('finance2.sharePart', { name: nameOf(p), amount: formatRupiah(v, locale) }),
                  )
                  .join(' · '),
              })}
            </p>
          </div>
        ) : (
          <EmptyState
            icon="info"
            title={t('finance2.needRule')}
            hint={t('finance2.needRuleHint')}
          />
        )}

        <button
          className="btn btn--block"
          onClick={save}
          disabled={!rule || !label.trim() || !amount}
        >
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}
