import { useState } from 'react'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { useI18n } from '@/i18n'
import { formatRupiah } from '@/i18n/format'
import { amountOf, OptionList } from './parts'
import { MONEY_SPACES, type MoneySpace } from './money'
import { arisanRound } from './arisanMath'
import {
  addArisan,
  advanceRound,
  removeArisan,
  toggleCollected,
  useArisan,
  type ArisanGroup,
} from './arisanStore'

/**
 * Arisan (F20) — rotating savings.
 *
 * Whose turn, the pot, and who still owes this round — computed by the pure
 * `arisan.ts`, rendered from real IndexedDB rows. Members are names the user
 * typed; the app invents none. Marking a member "sudah setor" is a fact the user
 * records, never a reminder the app pushes at anyone.
 */

export default function Arisan({ me }: { me: string }) {
  const { t } = useI18n()
  const [open, setOpen] = useState(false)
  const groups = useArisan(me)

  return (
    <div className="stack">
      <Card
        title={t('finance2.arisanTitle')}
        icon="money"
        hint={t('finance2.arisanHint')}
        action={
          <button className="btn btn--sm" onClick={() => setOpen(true)}>
            <Icon name="plus" size={16} /> {t('finance2.addArisan')}
          </button>
        }
      >
        {(groups ?? []).length === 0 ? (
          <EmptyState icon="money" title={t('finance2.noArisan')} hint={t('finance2.noArisanHint')} />
        ) : (
          <div className="stack">
            {(groups ?? []).map((g) => (
              <ArisanCard key={g.id} me={me} group={g} />
            ))}
          </div>
        )}
      </Card>

      <p className="disclaimer">{t('finance2.arisanCaveat')}</p>
      <NewArisan me={me} open={open} onClose={() => setOpen(false)} />
    </div>
  )
}

function ArisanCard({ me, group }: { me: string; group: ArisanGroup }) {
  const { t, locale } = useI18n()
  const r = arisanRound({
    members: group.members,
    order: group.order,
    amount: group.amount,
    round: group.round,
    collected: group.collected,
  })

  return (
    <div className="stack stack--tight" style={{ borderTop: '1px solid var(--border)', paddingTop: 'var(--space-2)' }}>
      <div className="row row--between">
        <strong style={{ fontSize: 14 }}>{group.label}</strong>
        <button className="btn btn--ghost btn--sm btn--icon" onClick={() => removeArisan(group.id, me)}>
          <Icon name="close" size={16} label={t('common.deleteX', { name: group.label })} />
        </button>
      </div>
      <span className="card__hint">
        {t('finance2.arisanRoundLabel', { round: r.roundInCycle, of: r.rounds, cycle: r.cycle })} ·{' '}
        {t('finance2.arisanPer', { amount: formatRupiah(group.amount, locale) })}
      </span>

      {r.recipient && (
        <span className="chip chip--mint">
          <Icon name="check" size={14} />
          {t('finance2.arisanTurn', { name: r.recipient, pot: formatRupiah(r.pot, locale) })}
        </span>
      )}

      <span className="card__hint">
        {r.allPaid
          ? t('finance2.arisanAllPaid')
          : t('finance2.arisanOwed', { amount: formatRupiah(r.owedTotal, locale), n: r.owed.length })}
      </span>

      <ul className="list">
        {group.members.map((m) => {
          const paid = group.collected.includes(m)
          const isRecipient = m === r.recipient
          return (
            <li key={m} className="list__item">
              <button
                className="choice"
                aria-pressed={paid}
                style={{ flexGrow: 1, textAlign: 'left' }}
                onClick={() => toggleCollected(group, m)}
              >
                <span className="choice__title">
                  {m}
                  {isRecipient ? ` · ${t('finance2.arisanReceiver')}` : ''}
                </span>
                <span className="choice__desc">
                  {paid ? t('finance2.arisanPaid') : t('finance2.arisanNotPaid')}
                </span>
              </button>
            </li>
          )
        })}
      </ul>

      {r.allPaid && (
        <button className="btn btn--soft btn--sm" onClick={() => advanceRound(group)}>
          <Icon name="chevron-right" size={16} /> {t('finance2.arisanNext')}
        </button>
      )}
    </div>
  )
}

function NewArisan({ me, open, onClose }: { me: string; open: boolean; onClose: () => void }) {
  const { t } = useI18n()
  const [name, setName] = useState('')
  const [amount, setAmount] = useState('')
  const [members, setMembers] = useState('')
  const [space, setSpace] = useState<MoneySpace>('mine')

  const parsed = members
    .split(/[\n,]/)
    .map((m) => m.trim())
    .filter(Boolean)

  async function save() {
    if (!name.trim() || amountOf(amount) <= 0 || parsed.length < 2) return
    await addArisan(me, { name: name.trim(), amount: amountOf(amount), members: parsed, space })
    setName('')
    setAmount('')
    setMembers('')
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={t('finance2.addArisan')}>
      <div className="stack">
        <Field label={t('finance2.arisanName')}>
          {(p) => (
            <input
              {...p}
              type="text"
              value={name}
              placeholder={t('finance2.arisanNamePlaceholder')}
              onChange={(e) => setName(e.target.value)}
            />
          )}
        </Field>
        <Field label={t('finance2.arisanAmount')} hint={t('finance2.arisanAmountHint')}>
          {(p) => (
            <input
              {...p}
              type="number"
              min="0"
              inputMode="numeric"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
            />
          )}
        </Field>
        <Field label={t('finance2.arisanMembers')} hint={t('finance2.arisanMembersHint')}>
          {(p) => (
            <textarea
              {...p}
              value={members}
              placeholder={t('finance2.arisanMembersPlaceholder')}
              onChange={(e) => setMembers(e.target.value)}
            />
          )}
        </Field>
        {parsed.length > 0 && (
          <span className="card__hint">{t('finance2.arisanMemberCount', { n: parsed.length })}</span>
        )}
        <OptionList
          legend={t('finance2.goalSpace')}
          options={MONEY_SPACES}
          value={space}
          onChange={setSpace}
          label={(s) => t(`finance2.space.${s}`)}
          describe={(s) => t(`finance2.space.${s}Hint`)}
        />
        <button
          className="btn btn--block"
          onClick={save}
          disabled={!name.trim() || amountOf(amount) <= 0 || parsed.length < 2}
        >
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}
