import { addMonths, format, parseISO } from 'date-fns'

/**
 * Savings goals (F17) and the emergency-fund runway (F18) — pure, no React, no
 * Dexie, no copy. Returns numbers and keys; the screens call `t()`.
 *
 * Two deliberate refusals shape this file:
 *
 *   1. **No shaming.** There is no "you're behind", no "you missed this month",
 *      no on-track/off-track verdict — those computations simply do not exist
 *      here. A month with no contribution is absent from the history, never a
 *      red mark. Progress is described, a target is never a deadline you failed.
 *   2. **No bare number.** The runway is months-of-expenses, and it is only ever
 *      shown next to the expense figure it was divided by and how many months
 *      that figure came from. An estimate with no stated basis is the kind of
 *      false certainty the brief forbids.
 */

// ---------------------------------------------------------------------------
// F17 — savings goals with contribution history
// ---------------------------------------------------------------------------

export interface GoalProgress {
  saved: number
  target: number
  /** Never below zero — passing the target is not a debt owed back. */
  remaining: number
  /** 0..100, capped. A goal with no target reads 0 rather than dividing by zero. */
  pct: number
  reached: boolean
}

export function goalProgress(target: number, saved: number): GoalProgress {
  const tg = Math.max(0, Math.round(target))
  const sv = Math.max(0, Math.round(saved))
  return {
    saved: sv,
    target: tg,
    remaining: Math.max(0, tg - sv),
    pct: tg > 0 ? Math.min(100, Math.round((sv / tg) * 100)) : 0,
    reached: tg > 0 && sv >= tg,
  }
}

export interface Contribution {
  amount: number
  /** yyyy-MM-dd. Only the month is used for the history buckets. */
  date: string
}

/** Total saved into a goal so far — the sum of its contribution rows. */
export function savedTotal(contribs: Contribution[]): number {
  let total = 0
  for (const c of contribs) total += Math.max(0, Math.round(c.amount))
  return total
}

export interface MonthTotal {
  /** yyyy-MM. */
  month: string
  total: number
  count: number
}

/**
 * The contribution history, one row per month that actually had a contribution,
 * newest first. Months with nothing are *not* included — their absence is not a
 * failure to display, it is simply a month the couple put nothing in, which is
 * allowed and unremarked.
 */
export function contributionMonths(contribs: Contribution[]): MonthTotal[] {
  const m = new Map<string, { total: number; count: number }>()
  for (const c of contribs) {
    const key = c.date.slice(0, 7)
    const cur = m.get(key) ?? { total: 0, count: 0 }
    cur.total += Math.max(0, Math.round(c.amount))
    cur.count += 1
    m.set(key, cur)
  }
  return [...m.entries()]
    .map(([month, v]) => ({ month, total: v.total, count: v.count }))
    .sort((a, b) => b.month.localeCompare(a.month))
}

/** What was put in during one month. Shown plainly (even Rp0), never as a miss. */
export function savedInMonth(contribs: Contribution[], month: string): number {
  return savedTotal(contribs.filter((c) => c.date.slice(0, 7) === month))
}

// ---------------------------------------------------------------------------
// F18 — emergency fund expressed in months of expenses
// ---------------------------------------------------------------------------

/** How sure the expense basis is. A key, never copy. `belum` = not enough history. */
export type ExpenseConfidence = 'tinggi' | 'sedang' | 'rendah' | 'belum'

export interface ExpenseBasis {
  /** The typical month's outflow (median, robust to a one-off big month). */
  perMonth: number
  /** How many months of history it was measured over. */
  months: number
  confidence: ExpenseConfidence
}

const median = (xs: number[]): number => {
  if (xs.length === 0) return 0
  const s = [...xs].sort((a, b) => a - b)
  const mid = Math.floor(s.length / 2)
  if (s.length % 2) return s[mid] as number
  return Math.round(((s[mid - 1] as number) + (s[mid] as number)) / 2)
}

export interface OutflowPoint {
  /** Positive rupiah spent. Callers pass the magnitude, not the signed ledger value. */
  amount: number
  /** yyyy-MM-dd. */
  date: string
}

/**
 * The monthly-expense figure the runway divides by, with an honest basis.
 *
 * The window is the last `windowMonths` months but never starts before the first
 * record, so a couple two months in is measured over two months, not six. Empty
 * months inside the range count as zero real spend. Confidence falls out of two
 * facts: how many months there are and how much they swing — never dressed up as
 * more certain than the data.
 */
export function expenseBasis(
  outflows: OutflowPoint[],
  opts: { today: string; windowMonths?: number },
): ExpenseBasis {
  const windowMonths = Math.max(1, opts.windowMonths ?? 6)
  const clean = outflows.filter((o) => Number.isFinite(o.amount) && o.amount > 0)
  if (clean.length === 0) return { perMonth: 0, months: 0, confidence: 'belum' }

  const thisMonth = opts.today.slice(0, 7)
  const firstMonth = clean.reduce((min, o) => (o.date.slice(0, 7) < min ? o.date.slice(0, 7) : min), thisMonth)
  const windowStart = format(addMonths(parseISO(`${thisMonth}-01`), 1 - windowMonths), 'yyyy-MM')
  const start = firstMonth > windowStart ? firstMonth : windowStart

  const months: string[] = []
  let cur = parseISO(`${start}-01`)
  for (let i = 0; i < 240 && format(cur, 'yyyy-MM') <= thisMonth; i++) {
    months.push(format(cur, 'yyyy-MM'))
    cur = addMonths(cur, 1)
  }
  const totals = months.map((m) =>
    clean.reduce((sum, o) => (o.date.slice(0, 7) === m ? sum + Math.round(o.amount) : sum), 0),
  )

  return { perMonth: median(totals), months: totals.length, confidence: confidenceOf(totals) }
}

function confidenceOf(totals: number[]): ExpenseConfidence {
  const n = totals.length
  if (n < 2) return 'belum'
  const mean = totals.reduce((a, b) => a + b, 0) / n
  if (mean <= 0) return 'rendah'
  const variance = totals.reduce((a, b) => a + (b - mean) ** 2, 0) / n
  const cov = Math.sqrt(variance) / mean
  if (cov <= 0.12) return 'tinggi'
  if (cov <= 0.4) return 'sedang'
  return 'rendah'
}

/**
 * Runway in months of expenses: fund ÷ monthly expense, one decimal.
 *
 * Null when there is no positive expense basis — "berapa bulan" has no answer if
 * we do not know what a month costs, and inventing one would be the false
 * certainty the brief forbids. The screen shows the basis (perMonth, months)
 * beside this so the figure is never a bare, authoritative-looking number.
 */
export function runwayMonths(fund: number, monthlyExpense: number): number | null {
  const e = Math.round(monthlyExpense)
  if (e <= 0) return null
  return Math.round((Math.max(0, Math.round(fund)) / e) * 10) / 10
}
