import { useState } from 'react'
import { format, startOfMonth } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field } from '@/components/ui'
import { useI18n } from '@/i18n'
import { formatRupiah } from '@/i18n/format'
import { amountOf, useNameOf, useParticipants } from './parts'
import { useFinance } from './store'
import { ruleAt } from './money'
import { compareModels, turnHolder, type MissingInput } from './calculator'

/**
 * Kalau dihitung pakai cara lain (FIN-02) — the eight presets side by side.
 *
 * Everything on this screen comes from records the couple already has: the
 * amount defaults to the shared expenses they logged this month, and the
 * incomes, needs and fixed amounts come from the agreement in force. Nothing is
 * written back — this is a what-if, and a what-if that quietly edited the
 * agreement would be the worst kind of surprise on a money screen.
 *
 * There is no "recommended", no highlight, no ordering by fairness. The app
 * has no business telling two people how to divide their money; it can only
 * show them what each way of dividing it would come to.
 */
export default function Compare({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const nameOf = useNameOf()
  const people = useParticipants()

  const rules = useFinance('contributionRules', me, (a, b) => a.createdAt.localeCompare(b.createdAt))
  const splits = useFinance('splits', me, (a, b) => b.date.localeCompare(a.date))

  const today = format(new Date(), 'yyyy-MM-dd')
  const rule = ruleAt(rules ?? [], today)

  // Real state, not a sample: what they have actually split so far this month.
  const monthFrom = format(startOfMonth(new Date()), 'yyyy-MM-dd')
  const thisMonth = (splits ?? []).filter((s) => s.date >= monthFrom)
  const monthTotal = thisMonth.reduce((n, s) => n + Math.max(0, Math.round(s.amount)), 0)

  const [amount, setAmount] = useState('')
  const [category, setCategory] = useState('')
  const [incomes, setIncomes] = useState<Record<string, string>>({})
  const [needs, setNeeds] = useState<Record<string, string>>({})
  const [fixed, setFixed] = useState<Record<string, string>>({})

  // The agreement's numbers are the starting point; a typed override wins for
  // this screen only. `??` on the string keeps an intentional "0" meaningful.
  const merge = (
    typed: Record<string, string>,
    saved: Record<string, number> | undefined,
  ): Record<string, number> =>
    Object.fromEntries(
      people.map((p) => [p, typed[p] !== undefined && typed[p] !== '' ? amountOf(typed[p]) : (saved?.[p] ?? 0)]),
    )

  const divided = amountOf(amount) || monthTotal
  // ponytail: eight small allocations per render, no memo. If this ever shows up
  // in a profile, memoise on the inputs rather than caching inside `allocate`.
  const rows = compareModels({
    amount: divided,
    participants: people,
    category: category.trim() || undefined,
    // Position in a rotation = how many shared expenses are already recorded, the
    // same count `Splits` uses, so the two screens agree on whose turn it is.
    turn: (splits ?? []).length,
    terms: {
      incomes: merge(incomes, rule?.incomes),
      needs: merge(needs, rule?.needs),
      fixed: merge(fixed, rule?.fixed),
      ...(rule?.byCategory ? { byCategory: rule.byCategory } : {}),
      ...(rule?.rotation ? { rotation: rule.rotation } : {}),
      ...(rule?.payerProfileId ? { payerProfileId: rule.payerProfileId } : {}),
      ...(rule?.shares ? { shares: rule.shares } : {}),
    },
  })

  const perPerson = (
    label: (name: string) => string,
    value: Record<string, string>,
    saved: Record<string, number> | undefined,
    set: (next: Record<string, string>) => void,
  ) => (
    <>
      {people.map((p) => (
        <Field key={p} label={label(nameOf(p))}>
          {(props) => (
            <input
              {...props}
              type="number"
              min="0"
              inputMode="numeric"
              value={value[p] ?? (saved?.[p] ? String(saved[p]) : '')}
              onChange={(e) => set({ ...value, [p]: e.target.value })}
            />
          )}
        </Field>
      ))}
    </>
  )

  return (
    <Card title={t('finance2.calcTitle')} icon="mentalload" hint={t('finance2.calcHint')}>
      {divided <= 0 ? (
        <EmptyState
          icon="info"
          title={t('finance2.calcNoAmount')}
          hint={t('finance2.calcNoAmountHint')}
        />
      ) : (
        <div className="stack">
          <p className="card__hint">
            {monthTotal > 0
              ? t('finance2.calcBasis', {
                  amount: formatRupiah(monthTotal, locale),
                  n: thisMonth.length,
                })
              : t('finance2.calcBasisNone')}
          </p>

          <Field label={t('finance2.calcAmount')} hint={t('finance2.calcAmountHint')}>
            {(p) => (
              <input
                {...p}
                type="number"
                min="0"
                inputMode="numeric"
                value={amount}
                placeholder={String(monthTotal || '')}
                onChange={(e) => setAmount(e.target.value)}
              />
            )}
          </Field>

          <details>
            <summary style={{ fontSize: 13, fontWeight: 700, cursor: 'pointer' }}>
              {t('finance2.calcTweak')}
            </summary>
            <div className="stack" style={{ marginTop: 'var(--space-2)' }}>
              <p className="field__hint">{t('finance2.calcTweakHint')}</p>
              {perPerson((n) => t('finance2.incomeOf', { name: n }), incomes, rule?.incomes, setIncomes)}
              {perPerson((n) => t('finance2.needsOf', { name: n }), needs, rule?.needs, setNeeds)}
              {perPerson((n) => t('finance2.fixedOf', { name: n }), fixed, rule?.fixed, setFixed)}
              <Field label={t('finance2.splitCategory')} hint={t('finance2.calcCategoryHint')}>
                {(p) => (
                  <input
                    {...p}
                    type="text"
                    value={category}
                    placeholder={t('finance2.entryCategoryPlaceholder')}
                    onChange={(e) => setCategory(e.target.value)}
                  />
                )}
              </Field>
            </div>
          </details>

          <ul className="list">
            {rows.map((r) => {
              const isActive = rule?.model === r.model
              const turn =
                r.model === 'gantian'
                  ? turnHolder(people, rule?.rotation, (splits ?? []).length)
                  : undefined
              return (
                <li key={r.model} className="list__item" style={{ alignItems: 'flex-start' }}>
                  <Icon name="money" size={18} />
                  <span className="grow stack stack--tight">
                    <strong style={{ fontSize: 14 }}>{t(`finance2.model.${r.model}`)}</strong>
                    <span className="card__hint">{t(`finance2.model.${r.model}Desc`)}</span>
                    <span className="row" style={{ flexWrap: 'wrap', gap: 'var(--space-1)' }}>
                      {people.map((p) => (
                        <span key={p} className="chip">
                          {t('finance2.sharePart', {
                            name: nameOf(p),
                            amount: formatRupiah(r.shares[p] ?? 0, locale),
                          })}
                        </span>
                      ))}
                    </span>
                    {turn && (
                      <span className="card__hint">
                        {t('finance2.calcTurnNow', { name: nameOf(turn) })}
                      </span>
                    )}
                    {/* The numbers stay visible, and their basis is stated. Hiding
                        them would be tidier and less honest. */}
                    {r.missing.length > 0 && (
                      <span className="card__hint">
                        {t('finance2.calcMissing', {
                          what: r.missing
                            .map((m: MissingInput) => t(`finance2.calcNeeds.${m}`))
                            .join(', '),
                        })}
                      </span>
                    )}
                    {isActive && (
                      <span className="chip chip--mint">
                        <Icon name="check" size={14} />
                        {t('finance2.calcCurrent')}
                      </span>
                    )}
                  </span>
                </li>
              )
            })}
          </ul>

          <p className="disclaimer">{t('finance2.calcNoRecommend')}</p>
        </div>
      )}
    </Card>
  )
}
