import { addMonths, format, parseISO } from 'date-fns'
import { monthOf } from './budget'

/**
 * Income records with a confidence band (FIN F12) — pure, no React, no Dexie,
 * no copy.
 *
 * A single "monthly income" number is a lie for most couples: freelancers, cash
 * tips, bonuses, a side job that some months brings nothing. So this never
 * returns one figure. It returns a *band* — low, expected, high — over the
 * months actually observed, plus a confidence that is honest about how thin the
 * history is and how much it swings. Per the house rule, an estimate always
 * carries a range and a confidence, never a bare number.
 */

export interface IncomePoint {
  amount: number
  /** yyyy-MM-dd. Only the month is used. */
  date: string
  /** Salary-like, expected every month. Irregular income leaves this false. */
  regular: boolean
  /** Cash / off-the-books. Kept for the record; the band treats it like any income. */
  cash: boolean
}

/** How sure the band is. A key, never copy — `belum` means "not enough history". */
export type IncomeConfidence = 'tinggi' | 'sedang' | 'rendah' | 'belum'

export interface IncomeBand {
  /** The leanest month observed in the window. */
  low: number
  /** The typical month (median), rounded to whole rupiah. */
  expected: number
  /** The best month observed in the window. */
  high: number
  /** How many months of history the band is built from. */
  months: number
  confidence: IncomeConfidence
}

const median = (xs: number[]): number => {
  if (xs.length === 0) return 0
  const s = [...xs].sort((a, b) => a - b)
  const mid = Math.floor(s.length / 2)
  if (s.length % 2) return s[mid] as number
  return Math.round(((s[mid - 1] as number) + (s[mid] as number)) / 2)
}

/** yyyy-MM strings from `start` to `end` inclusive. Both are yyyy-MM. */
function monthsBetween(start: string, end: string): string[] {
  const out: string[] = []
  let cur = parseISO(`${start}-01`)
  const stop = `${end}-01`
  // Guard against a bad range producing an unbounded loop.
  for (let i = 0; i < 240 && format(cur, 'yyyy-MM-dd') <= stop; i++) {
    out.push(format(cur, 'yyyy-MM'))
    cur = addMonths(cur, 1)
  }
  return out
}

/**
 * The income band over the last `windowMonths` months (default 6).
 *
 * The window starts no earlier than the first record — a couple two months into
 * tracking is measured over two months, not six, so five empty months do not
 * fake a lean band. Empty months *inside* the observed range count as zero,
 * because for irregular income a dry month is real signal, not missing data.
 *
 * Confidence falls out of two honest facts: how many months there are, and how
 * much the monthly total swings (coefficient of variation). One month can never
 * be more than `belum` — a band needs at least a second month to have a shape.
 */
export function incomeBand(
  records: IncomePoint[],
  opts: { today: string; windowMonths?: number } = { today: format(new Date(), 'yyyy-MM-dd') },
): IncomeBand {
  const windowMonths = Math.max(1, opts.windowMonths ?? 6)
  const clean = records.filter((r) => Number.isFinite(r.amount) && r.amount > 0)
  if (clean.length === 0) {
    return { low: 0, expected: 0, high: 0, months: 0, confidence: 'belum' }
  }

  const thisMonth = monthOf(opts.today)
  const firstMonth = clean.reduce((min, r) => (monthOf(r.date) < min ? monthOf(r.date) : min), thisMonth)
  const windowStart = monthOf(format(addMonths(parseISO(`${thisMonth}-01`), 1 - windowMonths), 'yyyy-MM-dd'))
  const start = firstMonth > windowStart ? firstMonth : windowStart

  const monthsList = monthsBetween(start, thisMonth)
  const totals = monthsList.map((m) =>
    clean.reduce((sum, r) => (monthOf(r.date) === m ? sum + Math.round(r.amount) : sum), 0),
  )

  const low = Math.min(...totals)
  const high = Math.max(...totals)
  const expected = median(totals)
  const n = totals.length

  return { low, expected, high, months: n, confidence: confidenceOf(totals, n) }
}

function confidenceOf(totals: number[], n: number): IncomeConfidence {
  if (n < 2) return 'belum'
  const mean = totals.reduce((a, b) => a + b, 0) / n
  if (mean <= 0) return 'rendah'
  const variance = totals.reduce((a, b) => a + (b - mean) ** 2, 0) / n
  const cov = Math.sqrt(variance) / mean
  if (cov <= 0.12) return 'tinggi'
  if (cov <= 0.4) return 'sedang'
  return 'rendah'
}
