import { format } from 'date-fns'
import { db, logAudit, newEnvelope, newId } from '@/db/db'
import { useOwned } from '@/db/hooks'
import type { Bill, Envelope, Recurrence } from '@/types/domain'
import { addFinance, type SplitRecord } from './store'
import type { MoneySpace } from './money'
import { nextDue, type SplitMethod } from './ledger'

/**
 * Persistence for the shared book and the bills (F05, F07, F08).
 *
 * No new store: a book line *is* a `splits` row and an obligation *is* a `bills`
 * row — both already exist, both already carry an envelope, and both are already
 * in backup and in the unpair sweep. What they were missing is four optional
 * fields each.
 *
 * ponytail: optional, unindexed fields on existing stores, so no `.version(n)`
 * block is needed and rows written before today still read correctly (they
 * simply have no correction and no settlement attached). Promote them to
 * required with a backfill only if a query ever needs to index one.
 */

// ---------------------------------------------------------------------------
// Records
// ---------------------------------------------------------------------------

/** A line in the shared book. Superset of the split row the earlier screens write. */
export type LedgerLineRecord = SplitRecord & {
  /** Which money space this expense actually hit. */
  space?: MoneySpace
  /** How it was divided, frozen at write time. */
  method?: SplitMethod
  /** Set together with `settledAt`: which settlement closed it. */
  settlementId?: string
  /** A correction: this line cancels the one it names. The book is append-only. */
  reversalOf?: string
}

/** An obligation. `Bill` already separates owner (envelope) from `payerProfileId`. */
export type BillRecord = Bill & {
  recurrence?: Recurrence
  /** Links the occurrences of one repeating obligation together. */
  seriesId?: string
}

const dataClassFor = (space: MoneySpace) => (space === 'mine' ? 'C1_personal' : 'C2_shared_ops')
const visibilityFor = (space: MoneySpace): Envelope['visibility'] =>
  space === 'mine' ? 'private' : 'shared'

// ---------------------------------------------------------------------------
// Reads — through the one gate, like everything else
// ---------------------------------------------------------------------------

export function useLedger(viewerProfileId: string | undefined): LedgerLineRecord[] | undefined {
  return useOwned<LedgerLineRecord>('splits', viewerProfileId, (a, b) =>
    b.date.localeCompare(a.date) || b.createdAt.localeCompare(a.createdAt),
  )
}

export function useBills(viewerProfileId: string | undefined): BillRecord[] | undefined {
  return useOwned<BillRecord>('bills', viewerProfileId, (a, b) => a.dueDate.localeCompare(b.dueDate))
}

// ---------------------------------------------------------------------------
// Writes — the book
// ---------------------------------------------------------------------------

export async function addLedgerLine(
  ownerProfileId: string,
  body: Omit<LedgerLineRecord, keyof Envelope>,
): Promise<string> {
  const space = body.space ?? 'shared'
  return addFinance('splits', ownerProfileId, dataClassFor(space), body, {
    visibility: visibilityFor(space),
  })
}

/**
 * A correction. Nothing is edited and nothing is deleted: the wrong line stays
 * on the book and a new line cancels it, so both are still there to read.
 */
export async function correctLedgerLine(
  actorProfileId: string,
  line: LedgerLineRecord,
): Promise<string> {
  // Field by field, not a spread: the old row's envelope (its id, its owner, its
  // version) must not ride along into the new one.
  return addLedgerLine(actorProfileId, {
    kind: 'split',
    label: line.label,
    amount: line.amount,
    category: line.category,
    date: format(new Date(), 'yyyy-MM-dd'),
    paidByProfileId: line.paidByProfileId,
    model: line.model,
    shares: line.shares,
    ...(line.space ? { space: line.space } : {}),
    ...(line.method ? { method: line.method } : {}),
    reversalOf: line.id,
  })
}

/**
 * Close a set of lines with one settlement (F07).
 *
 * Atomic on purpose: half a settlement is worse than none, because the couple
 * would be looking at a position that matches neither what they transferred nor
 * what the book says. Every line is stamped inside one transaction, and a set
 * naming a line that is gone (or already closed) commits nothing at all.
 *
 * Returns the settlement id, which is what ties the closed lines together.
 */
export async function settleUp(input: {
  actorProfileId: string
  entryIds: string[]
  /** The day the money actually moved. */
  date: string
}): Promise<string> {
  if (input.entryIds.length === 0) throw new Error('Tidak ada catatan yang ditutup.')
  const settlementId = newId()
  const now = new Date().toISOString()

  await db.transaction('rw', db.splits, async () => {
    const rows = (await db.splits.bulkGet(input.entryIds)) as (LedgerLineRecord | undefined)[]
    const open = rows.filter((r): r is LedgerLineRecord => Boolean(r) && !r?.settledAt && !r?.deletedAt)
    if (open.length !== input.entryIds.length) {
      // Dexie rolls the whole transaction back on a throw — that is the point.
      throw new Error('Ada catatan yang sudah berubah. Coba muat ulang posisinya.')
    }
    await db.splits.bulkPut(
      open.map((r) => ({
        ...r,
        settledAt: input.date,
        settlementId,
        updatedAt: now,
        version: r.version + 1,
      })) as never,
    )
  })

  await logAudit({
    actorProfileId: input.actorProfileId,
    action: 'update',
    objectStore: 'splits',
    objectId: settlementId,
    summary: 'settle-up',
  })
  return settlementId
}

// ---------------------------------------------------------------------------
// Writes — the obligations
// ---------------------------------------------------------------------------

export async function addBill(
  ownerProfileId: string,
  body: Omit<BillRecord, keyof Envelope>,
): Promise<string> {
  const shared = body.space === 'shared'
  const env = newEnvelope(ownerProfileId, shared ? 'C2_shared_ops' : 'C1_personal', {
    visibility: shared ? 'shared' : 'private',
  })
  const row: BillRecord = { ...env, ...body, seriesId: body.seriesId ?? env.id }
  await db.bills.put(row as never)
  await logAudit({
    actorProfileId: ownerProfileId,
    action: 'create',
    objectStore: 'bills',
    objectId: env.id,
    summary: 'bills dibuat',
  })
  return env.id
}

/**
 * Mark an obligation paid, and — if it repeats — write the next occurrence in
 * the same transaction. Two rows or none: a "lunas" that loses next month's
 * bill is how a recurring obligation quietly stops existing.
 *
 * Only the payer is stamped; the owner of the row never changes, because who
 * paid this month is not a transfer of whose obligation it is.
 */
export async function payBill(
  actorProfileId: string,
  bill: BillRecord,
  paidOnISO: string,
): Promise<string | undefined> {
  const now = new Date().toISOString()
  const upcoming = nextDue(bill.dueDate, bill.recurrence, bill.dueDate)
  let nextId: string | undefined

  await db.transaction('rw', db.bills, async () => {
    await db.bills.put({
      ...bill,
      status: 'paid',
      paidAt: paidOnISO,
      updatedAt: now,
      version: bill.version + 1,
    } as never)
    if (!upcoming) return
    const env = newEnvelope(bill.ownerProfileId, bill.dataClass, {
      visibility: bill.visibility,
      coOwnerProfileIds: bill.coOwnerProfileIds,
      sharedWithProfileIds: bill.sharedWithProfileIds,
    })
    nextId = env.id
    const next: BillRecord = {
      ...bill,
      ...env,
      dueDate: upcoming,
      status: 'unpaid',
      paidAt: undefined,
      seriesId: bill.seriesId ?? bill.id,
    }
    await db.bills.put(next as never)
  })

  await logAudit({
    actorProfileId,
    action: 'update',
    objectStore: 'bills',
    objectId: bill.id,
    summary: 'bill paid',
  })
  return nextId
}
