/**
 * The monthly money conversation (F21) — pure, returns message keys only.
 *
 * A short, ordered list of *questions*, never a scorecard. It reports no amount,
 * never says who spent more, never grades the month. Real records only decide
 * *which* open question to surface ("ada 3 tagihan belum kebayar — mau atur
 * siapa yang pegang?"), and never turn into a verdict. Two feeling-first
 * questions always lead, and one forward-looking question always closes, so the
 * conversation opens and ends on people rather than figures.
 */

export type PromptKind = 'open' | 'data'

export interface ReviewPrompt {
  key: string
  kind: PromptKind
  params?: Record<string, number | string>
}

export interface ReviewInputs {
  /** Bills still unpaid this month. */
  unpaidBills: number
  /** Envelopes that went past what was set aside — a heads-up, never a red flag. */
  overBudgetPots: number
  /** Shared goals not yet reached. */
  openGoals: number
  /** Money-related talking points already raised. */
  moneyTopics: number
}

export function reviewPrompts(input: ReviewInputs): ReviewPrompt[] {
  const prompts: ReviewPrompt[] = [
    { key: 'finance2.review.q.wentWell', kind: 'open' },
    { key: 'finance2.review.q.feltTight', kind: 'open' },
  ]
  if (input.unpaidBills > 0)
    prompts.push({ key: 'finance2.review.q.bills', kind: 'data', params: { n: input.unpaidBills } })
  if (input.overBudgetPots > 0)
    prompts.push({ key: 'finance2.review.q.overBudget', kind: 'data', params: { n: input.overBudgetPots } })
  if (input.openGoals > 0)
    prompts.push({ key: 'finance2.review.q.goals', kind: 'data', params: { n: input.openGoals } })
  if (input.moneyTopics > 0)
    prompts.push({ key: 'finance2.review.q.topics', kind: 'data', params: { n: input.moneyTopics } })
  prompts.push({ key: 'finance2.review.q.nextMonth', kind: 'open' })
  return prompts
}
