import { useState } from 'react'
import { format } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { useI18n } from '@/i18n'
import { formatRupiah, whenLabel } from '@/i18n/format'
import { OptionList, amountOf } from './parts'
import { addDebt, removeDebt, repayDebt, useDebts, type DebtRecord } from './debtStore'
import { debtOverdue, debtRemaining, debtStatus, debtSummary, type DebtDirection } from './debt'
import type { MoneySpace } from './money'

/**
 * Utang — debt tracking (F16), including the informal family debt that is the
 * common Indonesian case: money borrowed from or lent to a relative, no
 * contract, often no fixed date. The counterparty is a name you type, interest
 * is not modelled, and a debt with no due date is normal. Nothing here advises
 * or nags — it records a fact and describes where it stands.
 */

const DEBT_SPACES: readonly MoneySpace[] = ['mine', 'shared']

export default function Debts({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const [open, setOpen] = useState(false)
  const debts = useDebts(me)
  const today = format(new Date(), 'yyyy-MM-dd')

  const live = (debts ?? []).filter((d) => !d.deletedAt)
  const sum = debtSummary(live)
  const owe = live.filter((d) => d.direction === 'owe')
  const owed = live.filter((d) => d.direction === 'owed')

  return (
    <div className="stack">
      <Card
        title={t('finance2.debtsTitle')}
        icon="money"
        hint={t('finance2.debtsHint')}
        action={
          <button className="btn btn--sm" onClick={() => setOpen(true)}>
            <Icon name="plus" size={16} /> {t('finance2.addDebt')}
          </button>
        }
      >
        {live.length === 0 ? (
          <EmptyState icon="money" title={t('finance2.noDebts')} hint={t('finance2.noDebtsHint')} />
        ) : (
          <>
            <p className="banner">
              <Icon name="info" size={16} />
              {t('finance2.debtSummary', {
                owe: formatRupiah(sum.owe, locale),
                owed: formatRupiah(sum.owed, locale),
              })}
            </p>

            <DebtList
              me={me}
              legend={t('finance2.debtOwe')}
              debts={owe}
              today={today}
            />
            <DebtList
              me={me}
              legend={t('finance2.debtOwed')}
              debts={owed}
              today={today}
            />
          </>
        )}
      </Card>

      <p className="disclaimer">{t('finance2.disclaimer')}</p>

      <NewDebt me={me} open={open} onClose={() => setOpen(false)} today={today} />
    </div>
  )
}

function DebtList({
  me,
  legend,
  debts,
  today,
}: {
  me: string
  legend: string
  debts: DebtRecord[]
  today: string
}) {
  const { t, locale } = useI18n()
  const [payId, setPayId] = useState<string | null>(null)
  if (debts.length === 0) return null

  return (
    <div className="stack stack--tight">
      <h3 style={{ fontSize: 13, fontWeight: 700, margin: 0 }}>{legend}</h3>
      <ul className="list">
        {debts.map((d) => {
          const status = debtStatus(d)
          const overdue = debtOverdue(d, today)
          return (
            <li key={d.id} className="list__item" style={{ alignItems: 'flex-start' }}>
              <Icon name="money" size={18} />
              <span className="grow stack stack--tight">
                <strong style={{ fontSize: 14 }}>{d.label}</strong>
                <span className="card__hint">
                  {t('finance2.debtRemaining', { amount: formatRupiah(debtRemaining(d), locale) })}
                  {d.paid > 0 && status !== 'settled'
                    ? ` · ${t('finance2.debtOf', { amount: formatRupiah(d.amount, locale) })}`
                    : ''}
                </span>
                {d.dueDate && (
                  <span className="card__hint">
                    {t('finance2.debtDueOn', { date: whenLabel(d.dueDate, t, locale) })}
                  </span>
                )}
                {d.note && <span className="card__hint">{d.note}</span>}
                <span className="row" style={{ flexWrap: 'wrap', gap: 'var(--space-1)' }}>
                  <span className={`chip ${status === 'settled' ? 'chip--blue' : ''}`}>
                    <Icon name="info" size={14} />
                    {t(`finance2.debtStatus.${status}`)}
                  </span>
                  {overdue && (
                    <span className="chip chip--yellow">
                      <Icon name="info" size={14} />
                      {t('finance2.debtOverdue')}
                    </span>
                  )}
                </span>
                {payId === d.id && status !== 'settled' && (
                  <RepayForm debt={d} onDone={() => setPayId(null)} />
                )}
              </span>
              {status !== 'settled' && payId !== d.id && (
                <button className="btn btn--soft btn--sm" onClick={() => setPayId(d.id)}>
                  {t('finance2.repay')}
                </button>
              )}
              <button
                className="btn btn--soft btn--sm"
                onClick={() => removeDebt(d.id, me)}
                aria-label={t('common.delete')}
              >
                <Icon name="close" size={16} label={t('common.delete')} />
              </button>
            </li>
          )
        })}
      </ul>
    </div>
  )
}

function RepayForm({ debt, onDone }: { debt: DebtRecord; onDone: () => void }) {
  const { t } = useI18n()
  const [amount, setAmount] = useState('')

  async function save() {
    if (amountOf(amount) <= 0) return
    await repayDebt(debt, amountOf(amount))
    onDone()
  }

  return (
    <div className="row" style={{ gap: 'var(--space-1)', flexWrap: 'wrap' }}>
      <Field label={t('finance2.repayAmount')}>
        {(p) => (
          <input
            {...p}
            type="number"
            min="0"
            inputMode="numeric"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
          />
        )}
      </Field>
      <button className="btn btn--sm" onClick={save} disabled={!amount}>
        {t('common.save')}
      </button>
    </div>
  )
}

function NewDebt({
  me,
  open,
  onClose,
  today,
}: {
  me: string
  open: boolean
  onClose: () => void
  today: string
}) {
  const { t } = useI18n()
  const [counterparty, setCounterparty] = useState('')
  const [direction, setDirection] = useState<DebtDirection>('owe')
  const [amount, setAmount] = useState('')
  const [space, setSpace] = useState<MoneySpace>('mine')
  const [date, setDate] = useState(today)
  const [due, setDue] = useState('')
  const [note, setNote] = useState('')

  async function save() {
    if (!counterparty.trim() || amountOf(amount) <= 0) return
    await addDebt(me, {
      counterparty: counterparty.trim(),
      direction,
      amount: amountOf(amount),
      space,
      date: date || today,
      ...(due ? { dueDate: due } : {}),
      ...(note.trim() ? { note: note.trim() } : {}),
    })
    setCounterparty('')
    setDirection('owe')
    setAmount('')
    setSpace('mine')
    setDate(today)
    setDue('')
    setNote('')
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={t('finance2.addDebt')}>
      <div className="stack">
        <OptionList
          legend={t('finance2.debtDirection')}
          options={['owe', 'owed'] as const}
          value={direction}
          onChange={setDirection}
          label={(o) => t(`finance2.debtDir.${o}`)}
          describe={(o) => t(`finance2.debtDir.${o}Desc`)}
        />
        <Field label={t('finance2.debtCounterparty')} hint={t('finance2.debtCounterpartyHint')}>
          {(p) => (
            <input
              {...p}
              type="text"
              value={counterparty}
              placeholder={t('finance2.debtCounterpartyPlaceholder')}
              onChange={(e) => setCounterparty(e.target.value)}
            />
          )}
        </Field>
        <Field label={t('finance2.debtAmount')}>
          {(p) => (
            <input
              {...p}
              type="number"
              min="0"
              inputMode="numeric"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
            />
          )}
        </Field>
        <OptionList
          legend={t('finance2.debtSpace')}
          options={DEBT_SPACES}
          value={space}
          onChange={setSpace}
          label={(s) => t(`finance2.space.${s}`)}
          describe={(s) => t(`finance2.space.${s}Hint`)}
        />
        <Field label={t('finance2.debtDate')}>
          {(p) => <input {...p} type="date" value={date} onChange={(e) => setDate(e.target.value)} />}
        </Field>
        <Field label={t('finance2.debtDue')} hint={t('finance2.debtDueHint')}>
          {(p) => <input {...p} type="date" value={due} onChange={(e) => setDue(e.target.value)} />}
        </Field>
        <Field label={t('finance2.proposalNote')} hint={t('common.optional')}>
          {(p) => <textarea {...p} value={note} onChange={(e) => setNote(e.target.value)} />}
        </Field>

        <button
          className="btn btn--block"
          onClick={save}
          disabled={!counterparty.trim() || !amount}
        >
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}
