import { useState } from 'react'
import { format } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { useI18n } from '@/i18n'
import { formatRupiah, whenLabel } from '@/i18n/format'
import { OptionList, PeoplePicker, amountOf, useNameOf, useParticipants } from './parts'
import { addBill, payBill, useBills, type BillRecord } from './ledgerStore'
import { nextDue, type DueState } from './ledger'
import { routeReminders } from './budget'

/**
 * Tagihan & langganan (FIN F08).
 *
 * Owner and payer are two separate answers: the envelope owns the row, the
 * `payerProfileId` says who is actually paying, and the two are allowed to
 * differ. Nothing here nags or scores — a due date is described, never used to
 * push a real-world action.
 */

const today = () => format(new Date(), 'yyyy-MM-dd')

const STATE_CHIP: Record<DueState, string> = {
  overdue: 'chip--coral',
  today: 'chip--yellow',
  soon: 'chip--lavender',
  later: '',
  paid: 'chip--mint',
}

export default function Bills({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const nameOf = useNameOf()
  const [open, setOpen] = useState(false)
  const [showPaid, setShowPaid] = useState(false)

  const bills = useBills(me)
  // F09 — a reminder has one addressee. `mine` are the bills the viewer is on the
  // hook to pay; `theirs` are shown read-only, so a nudge never lands on both.
  const { mine, theirs } = routeReminders(bills ?? [], me, today())
  const paid = (bills ?? []).filter((b) => !b.deletedAt && b.status === 'paid')

  const renderBill = (bill: BillRecord, state: DueState, own: boolean) => {
    const next = bill.recurrence ? nextDue(bill.dueDate, bill.recurrence, today()) : undefined
    return (
      <li key={bill.id} className="list__item" style={{ alignItems: 'flex-start' }}>
        <Icon name="money" size={18} />
        <span className="grow stack stack--tight">
          <strong style={{ fontSize: 14 }}>{bill.title}</strong>
          <span className="card__hint">
            {formatRupiah(bill.amount, locale)} ·{' '}
            {t('finance2.dueOn', { date: whenLabel(bill.dueDate, t, locale) })}
          </span>
          <span className="card__hint">
            {t('finance2.billPaidBy', { name: nameOf(bill.payerProfileId) })}
            {next ? ` · ${t('finance2.billNext', { date: whenLabel(next, t, locale) })}` : ''}
          </span>
          <span className={`chip ${STATE_CHIP[state]}`}>
            <Icon name="info" size={14} />
            {t(`finance2.due.${state}`)}
          </span>
        </span>
        {own && (
          <button className="btn btn--soft btn--sm" onClick={() => payBill(me, bill, today())}>
            {t('finance2.markPaid')}
          </button>
        )}
      </li>
    )
  }

  return (
    <div className="stack">
      <Card
        title={t('finance2.billsTitle')}
        icon="money"
        hint={t('finance2.billsHint')}
        action={
          <button className="btn btn--sm" onClick={() => setOpen(true)}>
            <Icon name="plus" size={16} /> {t('finance2.addBill')}
          </button>
        }
      >
        {mine.length === 0 && theirs.length === 0 ? (
          <EmptyState icon="money" title={t('finance2.noBills')} hint={t('finance2.noBillsHint')} />
        ) : (
          <div className="stack">
            <div className="stack stack--tight">
              <strong style={{ fontSize: 13 }}>{t('finance2.remindersMine')}</strong>
              {mine.length === 0 ? (
                <p className="card__hint">{t('finance2.remindersMineNone')}</p>
              ) : (
                <ul className="list">{mine.map(({ bill, state }) => renderBill(bill, state, true))}</ul>
              )}
            </div>
            {theirs.length > 0 && (
              <div className="stack stack--tight">
                <strong style={{ fontSize: 13 }}>{t('finance2.remindersTheirs')}</strong>
                <span className="card__hint">{t('finance2.remindersTheirsHint')}</span>
                <ul className="list">{theirs.map(({ bill, state }) => renderBill(bill, state, false))}</ul>
              </div>
            )}
          </div>
        )}

        {paid.length > 0 && (
          <button
            className="btn btn--soft btn--sm"
            style={{ marginTop: 'var(--space-2)' }}
            onClick={() => setShowPaid((v) => !v)}
          >
            {showPaid ? t('finance2.hidePaid') : t('finance2.showPaid', { n: paid.length })}
          </button>
        )}
        {showPaid && paid.length > 0 && (
          <ul className="list" style={{ marginTop: 'var(--space-2)' }}>
            {paid.map((bill) => (
              <li key={bill.id} className="list__item">
                <Icon name="check" size={16} />
                <span className="grow stack stack--tight">
                  <span style={{ fontSize: 14 }}>{bill.title}</span>
                  <span className="card__hint">
                    {formatRupiah(bill.amount, locale)}
                    {bill.paidAt
                      ? ` · ${t('finance2.paidOn', { date: whenLabel(bill.paidAt, t, locale) })}`
                      : ''}
                  </span>
                </span>
                <span className={`chip ${STATE_CHIP.paid}`}>{t('finance2.due.paid')}</span>
              </li>
            ))}
          </ul>
        )}
      </Card>

      <NewBill me={me} open={open} onClose={() => setOpen(false)} />
    </div>
  )
}

type BillSpace = 'mine' | 'shared'
const BILL_SPACES: readonly BillSpace[] = ['mine', 'shared']
type Freq = 'daily' | 'weekly' | 'monthly' | 'yearly'
const FREQS: readonly Freq[] = ['monthly', 'weekly', 'yearly', 'daily']

function NewBill({ me, open, onClose }: { me: string; open: boolean; onClose: () => void }) {
  const { t } = useI18n()
  const people = useParticipants()
  const [title, setTitle] = useState('')
  const [amount, setAmount] = useState('')
  const [due, setDue] = useState(today)
  const [space, setSpace] = useState<BillSpace>('shared')
  const [payer, setPayer] = useState<string[]>([me])
  const [recurs, setRecurs] = useState(false)
  const [interval, setInterval] = useState('1')
  const [freq, setFreq] = useState<Freq>('monthly')

  async function save() {
    if (!title.trim() || amountOf(amount) <= 0) return
    await addBill(me, {
      kind: 'bill',
      title: title.trim(),
      amount: amountOf(amount),
      currency: 'IDR',
      dueDate: due,
      payerProfileId: payer[0] ?? me,
      splitModel: 'equal',
      status: 'unpaid',
      space,
      ...(recurs
        ? { recurrence: { freq, interval: Math.max(1, amountOf(interval) || 1) } }
        : {}),
    })
    setTitle('')
    setAmount('')
    setRecurs(false)
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={t('finance2.addBill')}>
      <div className="stack">
        <Field label={t('finance2.billTitle')}>
          {(p) => (
            <input
              {...p}
              type="text"
              value={title}
              placeholder={t('finance2.billTitlePlaceholder')}
              onChange={(e) => setTitle(e.target.value)}
            />
          )}
        </Field>
        <Field label={t('finance2.billAmount')}>
          {(p) => (
            <input
              {...p}
              type="number"
              min="0"
              inputMode="numeric"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
            />
          )}
        </Field>
        <Field label={t('finance2.billDue')}>
          {(p) => <input {...p} type="date" value={due} onChange={(e) => setDue(e.target.value)} />}
        </Field>
        <OptionList
          legend={t('finance2.billSpace')}
          options={BILL_SPACES}
          value={space}
          onChange={setSpace}
          label={(s) => t(`finance2.space.${s}`)}
          describe={(s) => t(`finance2.space.${s}Hint`)}
        />
        <PeoplePicker
          legend={t('finance2.billPayer')}
          hint={t('finance2.billPayerHint')}
          people={people}
          value={payer}
          onChange={setPayer}
          single
        />
        <label className="row" style={{ gap: 'var(--space-2)' }}>
          <input type="checkbox" checked={recurs} onChange={(e) => setRecurs(e.target.checked)} />
          <span style={{ fontSize: 13 }}>{t('finance2.billRecurs')}</span>
        </label>
        {recurs && (
          <div className="stack stack--tight">
            <Field label={t('finance2.billInterval')}>
              {(p) => (
                <input
                  {...p}
                  type="number"
                  min="1"
                  inputMode="numeric"
                  value={interval}
                  onChange={(e) => setInterval(e.target.value)}
                />
              )}
            </Field>
            <OptionList
              legend={t('finance2.billFreq')}
              options={FREQS}
              value={freq}
              onChange={setFreq}
              label={(f) => t(`finance2.freq.${f}`)}
            />
          </div>
        )}
        <button
          className="btn btn--block"
          onClick={save}
          disabled={!title.trim() || amountOf(amount) <= 0}
        >
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}
