import { addDays, addYears, format, parseISO } from 'date-fns'
import type { Recurrence } from '@/types/domain'
import { expand } from '@/features/calendar/recurrence'
import {
  allocate,
  balances,
  distribute,
  settlement,
  type AllocationContext,
  type RuleTerms,
  type SplitLike,
} from './money'

/**
 * The shared book (FIN F05–F08) — pure, no React, no Dexie, no copy.
 *
 * Three ideas hold this file together:
 *
 *   1. **The book is append-only.** A line that turned out wrong is never
 *      edited and never deleted; a *correction* is a new line pointing back at
 *      the one it cancels. Both stay visible, so "kok berubah sendiri?" can
 *      never happen to a couple's money.
 *   2. **Nothing rounds away.** Every method routes through `distribute()`
 *      (largest remainder) so the shares add back to the rupiah. The one method
 *      that cannot promise that — typing exact amounts — reports the gap
 *      instead of quietly swallowing it.
 *   3. **A settlement closes a set, not a number.** Settling stamps the exact
 *      lines it covers, so later lines are never silently counted as paid.
 */

// ---------------------------------------------------------------------------
// F06 — the split engine
// ---------------------------------------------------------------------------

/**
 * How one line is divided.
 *
 * `agreement` defers to the contribution rule in force on that date (the eight
 * presets in `money.ts`); the rest are per-line overrides, because one dinner
 * does not have to follow the household arrangement. `none` is "aku yang
 * tanggung, kamu nggak utang apa-apa": the line is on the book, the other
 * person owes nothing for it.
 */
export type SplitMethod = 'agreement' | 'even' | 'exact' | 'percent' | 'shares' | 'none'
export const SPLIT_METHODS: readonly SplitMethod[] = [
  'agreement',
  'even',
  'exact',
  'percent',
  'shares',
  'none',
]

export interface SplitInput {
  method: SplitMethod
  /** exact → rupiah per person · percent → 0..100 · shares → any positive weights. */
  values?: Record<string, number>
  /** `none` → the one person who carries the whole line. Usually whoever paid. */
  soleProfileId?: string
  /** `agreement` → the terms effective on the line's own date. */
  rule?: RuleTerms
  ruleContext?: AllocationContext
}

/** Why the shares do not add up. A key, never copy — the screen calls `t()`. */
export type SplitNoteKey =
  | 'finance2.splitGapUnder'
  | 'finance2.splitGapOver'
  | 'finance2.splitPercentOff'
  | 'finance2.splitNeedsWeights'
  | 'finance2.splitNeedsPerson'
  | 'finance2.splitNeedsRule'

export interface SplitResult {
  /** profileId → rupiah owed. Everyone appears, including the people owing 0. */
  shares: Record<string, number>
  /** `amount − Σshares`. Zero for every method except an `exact` that misses. */
  residual: number
  noteKey?: SplitNoteKey
}

const sum = (r: Record<string, number>) => Object.values(r).reduce((a, b) => a + b, 0)

/**
 * One expense → who owes how much, under the chosen method.
 *
 * Never throws and never returns half an answer: a method that cannot be
 * computed yet (no rule, no payer picked, weights all blank) gives everybody
 * zero, reports the whole amount as unallocated, and says why in `noteKey`. The
 * screen refuses to save while `residual !== 0`, so a line can never enter the
 * book owing more or less than it cost.
 */
export function splitAmount(
  amount: number,
  participants: string[],
  input: SplitInput,
): SplitResult {
  const ids = [...new Set(participants)].filter(Boolean).sort()
  const target = Math.max(0, Math.round(amount))
  const zero = (): Record<string, number> => Object.fromEntries(ids.map((i) => [i, 0]))
  if (ids.length === 0) return { shares: {}, residual: target }

  const done = (shares: Record<string, number>, noteKey?: SplitNoteKey): SplitResult => ({
    shares,
    residual: target - sum(shares),
    ...(noteKey ? { noteKey } : {}),
  })
  const weightsOf = () =>
    Object.fromEntries(ids.map((i) => [i, Math.max(0, input.values?.[i] ?? 0)]))

  switch (input.method) {
    case 'exact': {
      const shares = Object.fromEntries(
        ids.map((i) => [i, Math.max(0, Math.round(input.values?.[i] ?? 0))]),
      )
      const gap = target - sum(shares)
      // No auto-balancing. If the two numbers do not meet, the couple decides
      // where the difference goes, not the app.
      return done(shares, gap > 0 ? 'finance2.splitGapUnder' : gap < 0 ? 'finance2.splitGapOver' : undefined)
    }
    case 'percent': {
      const w = weightsOf()
      const stated = sum(w)
      if (stated <= 0) return { shares: zero(), residual: target, noteKey: 'finance2.splitPercentOff' }
      // `distribute` normalises, so the rupiah always add up even when the
      // percentages do not — but the screen is still told they do not.
      return done(
        distribute(target, w),
        Math.abs(stated - 100) > 0.5 ? 'finance2.splitPercentOff' : undefined,
      )
    }
    case 'shares': {
      const w = weightsOf()
      if (sum(w) <= 0) return { shares: zero(), residual: target, noteKey: 'finance2.splitNeedsWeights' }
      return done(distribute(target, w))
    }
    case 'none': {
      const who = input.soleProfileId
      if (!who || !ids.includes(who)) {
        return { shares: zero(), residual: target, noteKey: 'finance2.splitNeedsPerson' }
      }
      return done({ ...zero(), [who]: target })
    }
    case 'agreement': {
      if (!input.rule) return { shares: zero(), residual: target, noteKey: 'finance2.splitNeedsRule' }
      return done(allocate(target, ids, input.rule, input.ruleContext ?? {}))
    }
    case 'even':
    default:
      return done(distribute(target, Object.fromEntries(ids.map((i) => [i, 1]))))
  }
}

// ---------------------------------------------------------------------------
// F05 — the append-only book
// ---------------------------------------------------------------------------

export interface LedgerLine extends SplitLike {
  id: string
  date: string
  /** Set on a correction; names the line it cancels. Both rows stay on the book. */
  reversalOf?: string
  /** Which settlement closed it. Present exactly when `settledAt` is. */
  settlementId?: string
  deletedAt?: string
}

/** Ids of lines that a later correction cancelled. Both sides stop counting. */
export function cancelledIds(rows: LedgerLine[]): Set<string> {
  const out = new Set<string>()
  for (const r of rows) {
    if (r.deletedAt || !r.reversalOf) continue
    out.add(r.reversalOf)
    out.add(r.id)
  }
  return out
}

/** The lines that still mean something arithmetically. */
export function liveLines<T extends LedgerLine>(rows: T[]): T[] {
  const cancelled = cancelledIds(rows)
  return rows.filter((r) => !r.deletedAt && !cancelled.has(r.id))
}

// ---------------------------------------------------------------------------
// F07 — settle up
// ---------------------------------------------------------------------------

export interface NetPosition {
  /** profileId → rupiah. Positive means this person is still behind. */
  net: Record<string, number>
  debtorProfileId?: string
  creditorProfileId?: string
  /** 0 when the two of you are square. */
  amount: number
  /** Exactly the lines a settlement would close, oldest first. */
  entryIds: string[]
}

/**
 * Where the two of you stand right now, and which lines that answer is made of.
 *
 * A position, never a comparison: no "kamu lebih boros", no monthly ranking.
 * Settled and cancelled lines are out, so the number only ever describes what
 * is still open.
 */
export function netPosition<T extends LedgerLine>(rows: T[]): NetPosition {
  const open = liveLines(rows).filter((r) => !r.settledAt)
  const s = settlement(open)
  return {
    net: balances(open),
    ...(s
      ? { debtorProfileId: s.debtorProfileId, creditorProfileId: s.creditorProfileId }
      : {}),
    amount: s?.amount ?? 0,
    entryIds: [...open]
      .sort((a, b) => a.date.localeCompare(b.date) || a.id.localeCompare(b.id))
      .map((r) => r.id),
  }
}

// ---------------------------------------------------------------------------
// F08 — bills and recurring obligations
// ---------------------------------------------------------------------------

export interface BillLike {
  dueDate: string
  status: 'unpaid' | 'paid'
  recurrence?: Recurrence
  deletedAt?: string
}

export type DueState = 'paid' | 'overdue' | 'today' | 'soon' | 'later'

/** Where a bill sits relative to today. Description only — no nagging, no score. */
export function dueState(bill: BillLike, todayISO: string, soonDays = 7): DueState {
  if (bill.status === 'paid') return 'paid'
  if (bill.dueDate < todayISO) return 'overdue'
  if (bill.dueDate === todayISO) return 'today'
  const edge = format(addDays(parseISO(todayISO), Math.max(1, soonDays)), 'yyyy-MM-dd')
  return bill.dueDate <= edge ? 'soon' : 'later'
}

/**
 * When this obligation lands again after `afterISO`, or nothing if it does not
 * repeat (or the couple set an end date that has passed).
 *
 * ponytail: reuses the calendar's `expand()` rather than a second date walker,
 * which means it inherits the same month-end drift (31 Jan + 1 bulan → 28 Feb,
 * then 28 Mar). Fix it in `recurrence.ts` for both features if it ever bites.
 */
export function nextDue(
  dueDate: string,
  recurrence: Recurrence | undefined,
  afterISO: string,
): string | undefined {
  if (!recurrence) return undefined
  const from = format(addDays(parseISO(afterISO), 1), 'yyyy-MM-dd')
  const to = format(addYears(parseISO(from), 5), 'yyyy-MM-dd')
  return expand(recurrence, dueDate, from, to)[0]
}

/** Unpaid obligations, soonest first, each with the state the screen renders. */
export function pendingBills<T extends BillLike>(
  bills: T[],
  todayISO: string,
): { bill: T; state: DueState }[] {
  return bills
    .filter((b) => !b.deletedAt && b.status === 'unpaid')
    .sort((a, b) => a.dueDate.localeCompare(b.dueDate))
    .map((bill) => ({ bill, state: dueState(bill, todayISO) }))
}
