/**
 * Conflict-safe UX rules for money (F22).
 *
 * Three product rules turned into functions, so a screen can't quietly break one
 * and no future edit can reintroduce a red overspend chip by hand:
 *
 *   1. Overspending is never coloured red. Over budget is a fact to notice, not
 *      an alarm; red on a couple's shared money reads as blame.
 *   2. No partner-vs-partner comparison chart, ever. There is no "who spent more".
 *   3. No "kamu yang lebih boros" framing anywhere.
 *
 * This module owns rule 1 concretely (the only one with a colour to pick) and
 * states 2 and 3 so the boundary is documented and testable. It returns tokens
 * only; the component maps a token to a chip class. The guarantee that matters:
 * nothing it can ever return is the red/coral token.
 */

/** A money state's tone. There is deliberately no 'danger'/'alarm' member. */
export type SpendTone = 'calm' | 'notice'

/** Chip classes this module is allowed to hand back. `chip--coral` (red) is absent by design. */
export const TONE_CHIP: Record<SpendTone, string> = {
  calm: 'chip chip--mint',
  notice: 'chip chip--lavender',
}

/** Progress-bar fill for a budget, over or not. Over budget is a calm lavender, never coral. */
export const TONE_BAR: Record<SpendTone, string> = {
  calm: 'var(--mint, #4caf88)',
  notice: 'var(--lavender, #8a7fb5)',
}

/**
 * Over budget → 'notice' (a neutral heads-up), otherwise 'calm'. Whatever the
 * overspend, the strongest tone this returns is a soft notice — never an alarm.
 */
export function spendTone(over: boolean): SpendTone {
  return over ? 'notice' : 'calm'
}

/**
 * Rule 2/3, as data other code can assert against: framings this app refuses to
 * build. There is no function that produces a partner-vs-partner comparison,
 * because the answer is always "don't". Kept here so the ban is one importable
 * fact rather than a comment scattered across screens.
 */
export const FORBIDDEN_FRAMINGS = [
  'partner_vs_partner_chart',
  'who_spent_more',
  'spender_ranking',
  'monthly_winner',
] as const
export type ForbiddenFraming = (typeof FORBIDDEN_FRAMINGS)[number]
