import { useState } from 'react'
import { format } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { useSession } from '@/app/session'
import { useI18n } from '@/i18n'
import { formatRupiah, whenLabel } from '@/i18n/format'
import { amountOf, useNameOf } from './parts'
import { addFinance, patchFinance, useFinance, type ContributionRule, type PurchaseProposal } from './store'
import { proposalTier, ruleAt } from './money'
import {
  DEFAULT_PROPOSAL_TTL_DAYS,
  awaitingProfileId,
  canAnswer,
  canWithdraw,
  expiryFromNow,
  proposalState,
  type StoredStatus,
} from './proposalFlow'

/**
 * Usulan beli — a change to shared money is proposed, not applied (F13–F15).
 *
 * Di bawah X bebas · X sampai Y kasih tahu · di atas Y perlu setuju. The two
 * numbers come from the agreement the couple wrote, never from a default the app
 * picked. The other person accepts, edits (a counter-proposal), or declines; the
 * raiser can withdraw while it is still pending; and an unanswered proposal
 * expires on its own, so it is never a permanent obligation (F14).
 */

/** The stored proposal plus the lifecycle fields (see `proposalStore`-less design in store.ts note). */
type ProposalRow = Omit<PurchaseProposal, 'status'> & {
  status: StoredStatus
  expiresAt?: string
  counteredByProfileId?: string
}

const TTL_CHOICES = [7, 30, 0] as const

export default function Proposals({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const { partner } = useSession()
  const nameOf = useNameOf()
  const [editing, setEditing] = useState<ProposalRow | null>(null)
  const [adding, setAdding] = useState(false)

  const rules = useFinance('contributionRules', me, (a, b) => a.createdAt.localeCompare(b.createdAt))
  const proposals = useFinance('proposals', me, (a, b) => b.createdAt.localeCompare(a.createdAt)) as
    | ProposalRow[]
    | undefined
  const rule = ruleAt(rules ?? [], format(new Date(), 'yyyy-MM-dd'))
  const now = new Date().toISOString()

  async function decide(id: string, status: 'agreed' | 'declined' | 'noted') {
    await patchFinance('proposals', id, {
      status,
      decidedAt: now,
      decidedByProfileId: me,
    } as Partial<PurchaseProposal>)
  }

  async function withdraw(id: string) {
    await patchFinance('proposals', id, {
      status: 'withdrawn',
      decidedAt: now,
      decidedByProfileId: me,
    } as never)
  }

  if (!rule) {
    return (
      <Card title={t('finance2.proposalsTitle')} icon="money" hint={t('finance2.proposalsHint')}>
        <EmptyState
          icon="info"
          title={t('finance2.needThresholds')}
          hint={t('finance2.needThresholdsHint')}
        />
      </Card>
    )
  }

  return (
    <div className="stack">
      <Card
        title={t('finance2.proposalsTitle')}
        icon="money"
        hint={t('finance2.proposalsHint')}
        action={
          <button className="btn btn--sm" onClick={() => setAdding(true)}>
            <Icon name="plus" size={16} /> {t('finance2.addProposal')}
          </button>
        }
      >
        <p className="banner">
          <Icon name="info" size={16} />
          {t('finance2.thresholdSummary', {
            notify: formatRupiah(rule.notifyAbove, locale),
            agree: formatRupiah(rule.agreeAbove, locale),
          })}
        </p>

        {(proposals ?? []).length === 0 ? (
          <EmptyState
            icon="money"
            title={t('finance2.noProposals')}
            hint={t('finance2.noProposalsHint')}
          />
        ) : (
          <ul className="list">
            {(proposals ?? []).map((p) => {
              const state = proposalState(p, now)
              const waitingOn = awaitingProfileId(p, partner?.id, now)
              const iAnswer = canAnswer(p, me, partner?.id, now)
              const iWithdraw = !iAnswer && canWithdraw(p, me, now)
              return (
                <li key={p.id} className="list__item" style={{ alignItems: 'flex-start' }}>
                  <Icon name="money" size={18} />
                  <span className="grow stack stack--tight">
                    <strong style={{ fontSize: 14 }}>{p.label}</strong>
                    <span className="card__hint">
                      {formatRupiah(p.amount, locale)}
                      {p.category ? ` · ${p.category}` : ''} ·{' '}
                      {t('finance2.owner', { name: nameOf(p.ownerProfileId) })}
                    </span>
                    {p.note && <span className="card__hint">{p.note}</span>}
                    <span className="row" style={{ flexWrap: 'wrap', gap: 'var(--space-1)' }}>
                      <span
                        className={`chip ${p.tier === 'perlu_setuju' ? 'chip--yellow' : 'chip--blue'}`}
                      >
                        <Icon name="consent" size={14} />
                        {t(`finance2.tier.${p.tier}`)}
                      </span>
                      <span className="chip">
                        <Icon name="info" size={14} />
                        {t(`finance2.status.${state}`)}
                      </span>
                    </span>
                    {state === 'sent' && waitingOn && (
                      <span className="card__hint">
                        {waitingOn === me
                          ? t('finance2.awaitingYou')
                          : t('finance2.awaitingPartner', { name: nameOf(waitingOn) })}
                        {p.counteredByProfileId
                          ? ` · ${t('finance2.counteredBy', { name: nameOf(p.counteredByProfileId) })}`
                          : ''}
                      </span>
                    )}
                    {state === 'sent' && p.expiresAt && (
                      <span className="card__hint">
                        {t('finance2.expiresOn', { date: whenLabel(p.expiresAt.slice(0, 10), t, locale) })}
                      </span>
                    )}
                    {p.decidedAt && p.decidedByProfileId && state !== 'sent' && (
                      <span className="card__hint">
                        {t('finance2.decidedBy', {
                          name: nameOf(p.decidedByProfileId),
                          date: whenLabel(p.decidedAt.slice(0, 10), t, locale),
                        })}
                      </span>
                    )}
                  </span>
                  {iAnswer && (
                    <>
                      {p.tier === 'perlu_setuju' ? (
                        <>
                          <button className="btn btn--sm" onClick={() => decide(p.id, 'agreed')}>
                            {t('finance2.agree')}
                          </button>
                          <button
                            className="btn btn--soft btn--sm"
                            onClick={() => decide(p.id, 'declined')}
                          >
                            {t('finance2.decline')}
                          </button>
                        </>
                      ) : (
                        <button className="btn btn--soft btn--sm" onClick={() => decide(p.id, 'noted')}>
                          {t('finance2.markNoted')}
                        </button>
                      )}
                      <button className="btn btn--soft btn--sm" onClick={() => setEditing(p)}>
                        {t('finance2.counter')}
                      </button>
                    </>
                  )}
                  {iWithdraw && (
                    <button className="btn btn--soft btn--sm" onClick={() => withdraw(p.id)}>
                      {t('finance2.withdraw')}
                    </button>
                  )}
                </li>
              )
            })}
          </ul>
        )}
      </Card>

      <ProposalSheet
        me={me}
        rule={rule}
        open={adding}
        onClose={() => setAdding(false)}
      />
      <ProposalSheet
        me={me}
        rule={rule}
        editing={editing ?? undefined}
        open={editing !== null}
        onClose={() => setEditing(null)}
      />
    </div>
  )
}

function ProposalSheet({
  me,
  rule,
  editing,
  open,
  onClose,
}: {
  me: string
  rule: ContributionRule
  editing?: ProposalRow
  open: boolean
  onClose: () => void
}) {
  const { t } = useI18n()
  const [label, setLabel] = useState(editing?.label ?? '')
  const [amount, setAmount] = useState(editing ? String(editing.amount) : '')
  const [category, setCategory] = useState(editing?.category ?? '')
  const [note, setNote] = useState(editing?.note ?? '')
  const [ttl, setTtl] = useState<number>(DEFAULT_PROPOSAL_TTL_DAYS)

  // The sheet is reused for both a fresh proposal and a counter; keep its fields in
  // step with whichever proposal it was opened on.
  const [seed, setSeed] = useState(editing?.id)
  if (editing?.id !== seed) {
    setSeed(editing?.id)
    setLabel(editing?.label ?? '')
    setAmount(editing ? String(editing.amount) : '')
    setCategory(editing?.category ?? '')
    setNote(editing?.note ?? '')
    setTtl(DEFAULT_PROPOSAL_TTL_DAYS)
  }

  const tier = proposalTier(amountOf(amount), rule.notifyAbove, rule.agreeAbove)

  async function save() {
    if (!label.trim() || amountOf(amount) <= 0) return
    const now = new Date().toISOString()
    const body = {
      label: label.trim(),
      amount: amountOf(amount),
      category: category.trim(),
      // The tier is frozen with the proposal: raising the threshold next month must
      // not silently downgrade something already waiting for an answer.
      tier,
      status: (tier === 'bebas' ? 'noted' : 'sent') as StoredStatus,
      expiresAt: expiryFromNow(now, ttl),
      ...(note.trim() ? { note: note.trim() } : {}),
    }
    if (editing) {
      // An edit is a counter-proposal: the person editing becomes the last mover,
      // the answer flips to the other side, and any earlier decision is cleared.
      await patchFinance('proposals', editing.id, {
        ...body,
        counteredByProfileId: me,
        decidedAt: undefined,
        decidedByProfileId: undefined,
      } as never)
    } else {
      await addFinance('proposals', me, 'C2_shared_ops', { kind: 'proposal', ...body } as never)
    }
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={editing ? t('finance2.counter') : t('finance2.addProposal')}>
      <div className="stack">
        <Field label={t('finance2.proposalLabel')}>
          {(p) => <input {...p} type="text" value={label} onChange={(e) => setLabel(e.target.value)} />}
        </Field>
        <Field label={t('finance2.proposalAmount')}>
          {(p) => (
            <input
              {...p}
              type="number"
              min="0"
              inputMode="numeric"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
            />
          )}
        </Field>
        <Field label={t('finance2.splitCategory')}>
          {(p) => (
            <input
              {...p}
              type="text"
              value={category}
              placeholder={t('finance2.entryCategoryPlaceholder')}
              onChange={(e) => setCategory(e.target.value)}
            />
          )}
        </Field>
        <Field label={t('finance2.proposalNote')} hint={t('common.optional')}>
          {(p) => <textarea {...p} value={note} onChange={(e) => setNote(e.target.value)} />}
        </Field>

        <fieldset style={{ border: 0, padding: 0, margin: 0 }} className="stack stack--tight">
          <legend style={{ fontSize: 13, fontWeight: 700, padding: 0 }}>
            {t('finance2.proposalExpiry')}
          </legend>
          <div className="choices">
            {TTL_CHOICES.map((d) => (
              <button
                key={d}
                type="button"
                className="choice"
                aria-pressed={ttl === d}
                onClick={() => setTtl(d)}
              >
                <span className="choice__title">{t(`finance2.expiry.${d}`)}</span>
              </button>
            ))}
          </div>
        </fieldset>

        <p className="banner">
          <Icon name="consent" size={16} />
          {t('finance2.tierNow', { tier: t(`finance2.tier.${tier}`) })} ·{' '}
          {t(`finance2.tier.${tier}Desc`)}
        </p>

        <button className="btn btn--block" onClick={save} disabled={!label.trim() || !amount}>
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}
