import { useCallback, useMemo } from 'react'
import { useSession } from '@/app/session'
import { useT } from '@/i18n'

/** Small pieces the four finance panels all need. No feature logic lives here. */

/** Display name for a profile id, falling back to "Aku" for the active profile. */
export function useNameOf(): (id: string) => string {
  const { profiles } = useSession()
  const t = useT()
  return useCallback(
    (id: string) => profiles.find((p) => p.id === id)?.displayName ?? t('finance2.me'),
    [profiles, t],
  )
}

/** Everyone a split, rule, or responsibility can point at. One or two people. */
export function useParticipants(): string[] {
  const { profile, partner } = useSession()
  return useMemo(
    () => [profile?.id, partner?.id].filter((x): x is string => Boolean(x)),
    [profile, partner],
  )
}

/**
 * Who is responsible / who decides / who pays. Multi by default; `single` turns
 * it into a one-of choice. Buttons rather than checkboxes so the whole label is
 * the hit target at 320 px.
 */
export function PeoplePicker({
  legend,
  hint,
  people,
  value,
  onChange,
  single = false,
}: {
  legend: string
  hint?: string
  people: string[]
  value: string[]
  onChange: (next: string[]) => void
  single?: boolean
}) {
  const nameOf = useNameOf()
  return (
    <fieldset style={{ border: 0, padding: 0, margin: 0 }} className="stack stack--tight">
      <legend style={{ fontSize: 13, fontWeight: 700, padding: 0 }}>{legend}</legend>
      <div className="choices">
        {people.map((p) => {
          const on = value.includes(p)
          return (
            <button
              key={p}
              type="button"
              className="choice"
              aria-pressed={on}
              onClick={() =>
                onChange(single ? [p] : on ? value.filter((x) => x !== p) : [...value, p])
              }
            >
              <span className="choice__title">{nameOf(p)}</span>
            </button>
          )
        })}
      </div>
      {hint && <span className="field__hint">{hint}</span>}
    </fieldset>
  )
}

/** Radio-style list of options with a description under each label. */
export function OptionList<T extends string>({
  legend,
  options,
  value,
  onChange,
  label,
  describe,
  disabled = false,
}: {
  legend: string
  options: readonly T[]
  value: T
  onChange: (next: T) => void
  label: (o: T) => string
  describe?: (o: T) => string
  disabled?: boolean
}) {
  return (
    <fieldset style={{ border: 0, padding: 0, margin: 0 }} className="stack stack--tight">
      <legend style={{ fontSize: 13, fontWeight: 700, padding: 0 }}>{legend}</legend>
      <div className="choices">
        {options.map((o) => (
          <button
            key={o}
            type="button"
            className="choice"
            aria-pressed={value === o}
            disabled={disabled}
            onClick={() => onChange(o)}
          >
            <span className="choice__title">{label(o)}</span>
            {describe && <span className="choice__desc">{describe(o)}</span>}
          </button>
        ))}
      </div>
    </fieldset>
  )
}

/** Rupiah entry. `inputMode` keeps the numeric keypad on a phone. */
export function amountOf(raw: string): number {
  const n = Number(raw)
  return Number.isFinite(n) ? Math.max(0, Math.round(n)) : 0
}
