import { useMemo, useState } from 'react'
import { format } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { useI18n } from '@/i18n'
import { formatRupiah, whenLabel } from '@/i18n/format'
import { amountOf, OptionList } from './parts'
import { MONEY_SPACES, type MoneySpace } from './money'
import { useFinance, type LedgerEntry } from './store'
import {
  addContribution,
  addGoal,
  removeGoal,
  useContributions,
  useGoals,
  type SavingsGoal,
} from './savingsStore'
import {
  contributionMonths,
  expenseBasis,
  goalProgress,
  runwayMonths,
  savedInMonth,
  savedTotal,
  type Contribution,
} from './savingsMath'

/**
 * Nabung (F17) dan dana darurat (F18).
 *
 * Savings goals per space, each with a real contribution history — every top-up
 * is a dated row, not a number that silently changes. A missed month is never
 * flagged; the app has no concept of "behind". The emergency fund is one goal
 * marked as such, shown as months-of-expenses next to the expense figure it was
 * divided by — a described estimate with its basis, never a bare authority.
 */

const today = () => format(new Date(), 'yyyy-MM-dd')

const confidenceChip = (c: string) =>
  c === 'tinggi' ? 'mint' : c === 'rendah' || c === 'belum' ? 'coral' : 'lavender'

export default function Savings({ me }: { me: string }) {
  const { t } = useI18n()
  const [open, setOpen] = useState(false)
  const [topUp, setTopUp] = useState<SavingsGoal | null>(null)

  const goals = useGoals(me)
  const contribs = useContributions(me)

  const byGoal = useMemo(() => {
    const m = new Map<string, Contribution[]>()
    for (const c of contribs ?? []) {
      const list = m.get(c.goalId) ?? []
      list.push({ amount: c.amount, date: c.date })
      m.set(c.goalId, list)
    }
    return m
  }, [contribs])

  return (
    <div className="stack">
      <EmergencyFund me={me} goals={goals ?? []} byGoal={byGoal} />

      <Card
        title={t('finance2.savingsTitle')}
        icon="money"
        hint={t('finance2.savingsHint')}
        action={
          <button className="btn btn--sm" onClick={() => setOpen(true)}>
            <Icon name="plus" size={16} /> {t('finance2.addGoal')}
          </button>
        }
      >
        {(goals ?? []).length === 0 ? (
          <EmptyState icon="money" title={t('finance2.noGoals2')} hint={t('finance2.noGoals2Hint')} />
        ) : (
          <ul className="list">
            {(goals ?? []).map((g) => (
              <GoalRow
                key={g.id}
                me={me}
                goal={g}
                contribs={byGoal.get(g.id) ?? []}
                onTopUp={() => setTopUp(g)}
              />
            ))}
          </ul>
        )}
      </Card>

      <p className="disclaimer">{t('finance2.savingsCaveat')}</p>

      <NewGoal me={me} open={open} onClose={() => setOpen(false)} />
      <TopUp me={me} goal={topUp} onClose={() => setTopUp(null)} />
    </div>
  )
}

function GoalRow({
  me,
  goal,
  contribs,
  onTopUp,
}: {
  me: string
  goal: SavingsGoal
  contribs: Contribution[]
  onTopUp: () => void
}) {
  const { t, locale } = useI18n()
  const [showHistory, setShowHistory] = useState(false)
  const saved = savedTotal(contribs)
  const p = goalProgress(goal.amount, saved)
  const months = contributionMonths(contribs)
  const thisMonth = savedInMonth(contribs, today().slice(0, 7))

  return (
    <li className="list__item" style={{ alignItems: 'flex-start' }}>
      <Icon name="money" size={18} />
      <span className="grow stack stack--tight">
        <strong style={{ fontSize: 14 }}>
          {goal.label}
          {goal.emergency ? ` · ${t('finance2.emergencyTag')}` : ''}
        </strong>
        <span className="card__hint">
          {t('finance2.goalProgress2', {
            saved: formatRupiah(p.saved, locale),
            target: formatRupiah(p.target, locale),
          })}
          {goal.targetDate ? ` · ${whenLabel(goal.targetDate, t, locale)}` : ''}
        </span>
        <span
          className="goal__bar"
          role="progressbar"
          aria-valuenow={p.pct}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-label={goal.label}
        >
          <span style={{ width: `${p.pct}%` }} />
        </span>
        {/* This month is stated plainly — even Rp0 — never as a red "missed". */}
        <span className="card__hint">
          {t('finance2.savedThisMonth', { amount: formatRupiah(thisMonth, locale) })}
          {p.reached ? ` · ${t('finance2.goalReached')}` : ''}
        </span>
        {months.length > 0 && (
          <button
            className="btn btn--ghost btn--sm"
            style={{ alignSelf: 'flex-start', padding: 0 }}
            onClick={() => setShowHistory((v) => !v)}
          >
            {t('finance2.historyToggle', { n: months.length })}
          </button>
        )}
        {showHistory && (
          <ul className="list">
            {months.map((m) => (
              <li key={m.month} className="list__item">
                <span className="grow card__hint">
                  {whenLabel(`${m.month}-01`, t, locale)} · {t('finance2.historyCount', { n: m.count })}
                </span>
                <span>{formatRupiah(m.total, locale)}</span>
              </li>
            ))}
          </ul>
        )}
      </span>
      <button className="btn btn--soft btn--sm" onClick={onTopUp}>
        {t('finance2.addSaving2')}
      </button>
      <button className="btn btn--ghost btn--sm btn--icon" onClick={() => removeGoal(goal.id, me)}>
        <Icon name="close" size={16} label={t('common.deleteX', { name: goal.label })} />
      </button>
    </li>
  )
}

function EmergencyFund({
  me,
  goals,
  byGoal,
}: {
  me: string
  goals: SavingsGoal[]
  byGoal: Map<string, Contribution[]>
}) {
  const { t, locale } = useI18n()
  const entries = useFinance<'ledger'>('ledger', me)

  const fundGoal = goals.find((g) => g.emergency)
  const fund = fundGoal ? savedTotal(byGoal.get(fundGoal.id) ?? []) : 0

  // The expense basis is real account spending, not a guess — outflows only.
  const outflows = useMemo(
    () =>
      (entries ?? [])
        .filter((e: LedgerEntry) => e.kind === 'ledger' && e.amount < 0)
        .map((e) => ({ amount: -e.amount, date: e.date })),
    [entries],
  )
  const basis = useMemo(() => expenseBasis(outflows, { today: today() }), [outflows])
  const runway = runwayMonths(fund, basis.perMonth)

  return (
    <Card title={t('finance2.emergencyTitle')} icon="money" hint={t('finance2.emergencyHint')}>
      {!fundGoal ? (
        <EmptyState
          icon="money"
          title={t('finance2.noEmergency')}
          hint={t('finance2.noEmergencyHint')}
        />
      ) : (
        <div className="stack stack--tight">
          <div className="row" style={{ gap: 'var(--space-3)', flexWrap: 'wrap' }}>
            <span className="stack stack--tight" style={{ gap: 2 }}>
              <span className="card__hint">{t('finance2.fundBalance')}</span>
              <span style={{ fontSize: 18, fontWeight: 700 }}>{formatRupiah(fund, locale)}</span>
            </span>
            <span className="stack stack--tight" style={{ gap: 2 }}>
              <span className="card__hint">{t('finance2.monthsCovered')}</span>
              <span style={{ fontSize: 20, fontWeight: 700 }}>
                {runway === null ? t('finance2.notYet') : t('finance2.monthsValue', { n: runway })}
              </span>
            </span>
          </div>
          {/* The assumption, always shown next to the figure. */}
          <span className={`chip chip--${confidenceChip(basis.confidence)}`}>
            <Icon name="info" size={14} />
            {basis.perMonth > 0
              ? t('finance2.basisShown', {
                  amount: formatRupiah(basis.perMonth, locale),
                  n: basis.months,
                })
              : t('finance2.basisNone')}
            {' · '}
            {t(`finance2.confidence.${basis.confidence}`)}
          </span>
        </div>
      )}
    </Card>
  )
}

function NewGoal({ me, open, onClose }: { me: string; open: boolean; onClose: () => void }) {
  const { t } = useI18n()
  const [name, setName] = useState('')
  const [target, setTarget] = useState('')
  const [space, setSpace] = useState<MoneySpace>('shared')
  const [targetDate, setTargetDate] = useState('')
  const [emergency, setEmergency] = useState(false)

  async function save() {
    if (!name.trim() || amountOf(target) <= 0) return
    await addGoal(me, {
      name: name.trim(),
      target: amountOf(target),
      space,
      ...(targetDate ? { targetDate } : {}),
      emergency,
    })
    setName('')
    setTarget('')
    setTargetDate('')
    setEmergency(false)
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={t('finance2.addGoal')}>
      <div className="stack">
        <Field label={t('finance2.goalName2')}>
          {(p) => (
            <input
              {...p}
              type="text"
              value={name}
              placeholder={t('finance2.goalPlaceholder2')}
              onChange={(e) => setName(e.target.value)}
            />
          )}
        </Field>
        <Field label={t('finance2.goalTarget2')}>
          {(p) => (
            <input
              {...p}
              type="number"
              min="0"
              inputMode="numeric"
              value={target}
              onChange={(e) => setTarget(e.target.value)}
            />
          )}
        </Field>
        <OptionList
          legend={t('finance2.goalSpace')}
          options={MONEY_SPACES}
          value={space}
          onChange={setSpace}
          label={(s) => t(`finance2.space.${s}`)}
          describe={(s) => t(`finance2.space.${s}Hint`)}
        />
        <Field label={t('finance2.goalDeadline2')} hint={t('finance2.goalDeadlineHint')}>
          {(p) => <input {...p} type="date" value={targetDate} onChange={(e) => setTargetDate(e.target.value)} />}
        </Field>
        <label className="row" style={{ gap: 'var(--space-2)' }}>
          <input type="checkbox" checked={emergency} onChange={(e) => setEmergency(e.target.checked)} />
          <span style={{ fontSize: 13 }}>{t('finance2.markEmergency')}</span>
        </label>
        <button
          className="btn btn--block"
          onClick={save}
          disabled={!name.trim() || amountOf(target) <= 0}
        >
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}

function TopUp({ me, goal, onClose }: { me: string; goal: SavingsGoal | null; onClose: () => void }) {
  const { t } = useI18n()
  const [amount, setAmount] = useState('')

  async function save() {
    if (!goal || amountOf(amount) <= 0) return
    await addContribution(me, goal, amountOf(amount))
    setAmount('')
    onClose()
  }

  return (
    <Sheet open={goal !== null} onClose={onClose} title={t('finance2.addSaving2')}>
      <div className="stack">
        <Field label={t('finance2.savingAmount2')}>
          {(p) => (
            <input
              {...p}
              type="number"
              min="0"
              inputMode="numeric"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
            />
          )}
        </Field>
        <button className="btn btn--block" onClick={save} disabled={amountOf(amount) <= 0}>
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}
