import { useMemo, useState } from 'react'
import { format } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { useI18n, baseLocale } from '@/i18n'
import { formatRupiah, whenLabel } from '@/i18n/format'
import { amountOf } from './parts'
import { useIncomes, addIncome, removeIncome } from './budgetStore'
import { incomeBand, type IncomePoint } from './incomeMath'

/**
 * Pemasukan (FIN F12).
 *
 * Real incomes are lumpy — a salary, a freelance job, cash that some months is
 * there and some months is not. So this never shows one "monthly income": it
 * shows a band (paling sepi · biasanya · paling ramai) over the months actually
 * recorded, and a confidence that stays honest about thin or swingy history.
 * The band is arithmetic on what the user typed, never a forecast or advice.
 */

const today = () => format(new Date(), 'yyyy-MM-dd')

export default function Income({ me }: { me: string }) {
  const { t, locale: uiLocale } = useI18n()
  // `dwi` is a display mode, not a language — formatters and data tables
  // take the real one.
  const locale = baseLocale(uiLocale)
  const [open, setOpen] = useState(false)

  const incomes = useIncomes(me)
  const points: IncomePoint[] = useMemo(
    () => (incomes ?? []).map((r) => ({ amount: r.amount, date: r.date, regular: r.regular, cash: r.cash })),
    [incomes],
  )
  const band = useMemo(() => incomeBand(points, { today: today() }), [points])

  return (
    <div className="stack">
      <Card title={t('finance2.incomeBandTitle')} icon="money" hint={t('finance2.incomeBandHint')}>
        {band.months === 0 ? (
          <EmptyState icon="money" title={t('finance2.noIncome')} hint={t('finance2.noIncomeHint')} />
        ) : (
          <div className="stack stack--tight">
            <div className="row" style={{ gap: 'var(--space-3)', flexWrap: 'wrap' }}>
              <BandCell label={t('finance2.bandLow')} amount={band.low} locale={locale} />
              <BandCell label={t('finance2.bandExpected')} amount={band.expected} locale={locale} strong />
              <BandCell label={t('finance2.bandHigh')} amount={band.high} locale={locale} />
            </div>
            <span className={`chip chip--${band.confidence === 'tinggi' ? 'mint' : band.confidence === 'rendah' || band.confidence === 'belum' ? 'coral' : 'lavender'}`}>
              <Icon name="info" size={14} />
              {t(`finance2.confidence.${band.confidence}`)} · {t('finance2.bandMonths', { n: band.months })}
            </span>
          </div>
        )}
      </Card>

      <Card
        title={t('finance2.incomeListTitle')}
        icon="money"
        hint={t('finance2.incomeListHint')}
        action={
          <button className="btn btn--sm" onClick={() => setOpen(true)}>
            <Icon name="plus" size={16} /> {t('finance2.addIncome')}
          </button>
        }
      >
        {(incomes ?? []).length === 0 ? (
          <EmptyState icon="money" title={t('finance2.noIncome')} hint={t('finance2.noIncomeHint')} />
        ) : (
          <ul className="list">
            {(incomes ?? []).map((r) => (
              <li key={r.id} className="list__item" style={{ alignItems: 'flex-start' }}>
                <Icon name="backup" size={18} />
                <span className="grow stack stack--tight">
                  <strong style={{ fontSize: 14 }}>{r.label}</strong>
                  <span className="card__hint">
                    {whenLabel(r.date, t, locale)} · {formatRupiah(r.amount, locale)}
                  </span>
                  <span className="row" style={{ flexWrap: 'wrap', gap: 'var(--space-1)' }}>
                    <span className="chip">{t(r.regular ? 'finance2.incRegular' : 'finance2.incIrregular')}</span>
                    {r.cash && <span className="chip chip--yellow">{t('finance2.incCash')}</span>}
                  </span>
                </span>
                <button className="btn btn--soft btn--sm" onClick={() => removeIncome(r.id, me)}>
                  <Icon name="close" size={16} label={t('common.delete')} />
                </button>
              </li>
            ))}
          </ul>
        )}
      </Card>

      <p className="disclaimer">{t('finance2.incomeCaveat')}</p>
      <NewIncome me={me} open={open} onClose={() => setOpen(false)} />
    </div>
  )
}

function BandCell({
  label,
  amount,
  locale,
  strong = false,
}: {
  label: string
  amount: number
  locale: 'id' | 'en'
  strong?: boolean
}) {
  return (
    <span className="stack stack--tight" style={{ gap: 2 }}>
      <span className="card__hint">{label}</span>
      <span style={{ fontSize: strong ? 20 : 15, fontWeight: strong ? 700 : 600 }}>
        {formatRupiah(amount, locale)}
      </span>
    </span>
  )
}

function NewIncome({ me, open, onClose }: { me: string; open: boolean; onClose: () => void }) {
  const { t } = useI18n()
  const [source, setSource] = useState('')
  const [amount, setAmount] = useState('')
  const [date, setDate] = useState(today)
  const [regular, setRegular] = useState(true)
  const [cash, setCash] = useState(false)
  const [shared, setShared] = useState(false)

  async function save() {
    if (!source.trim() || amountOf(amount) <= 0) return
    await addIncome(me, { source: source.trim(), amount: amountOf(amount), date, regular, cash, shared })
    setSource('')
    setAmount('')
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={t('finance2.addIncome')}>
      <div className="stack">
        <Field label={t('finance2.incomeSource')}>
          {(p) => (
            <input
              {...p}
              type="text"
              value={source}
              placeholder={t('finance2.incomeSourcePlaceholder')}
              onChange={(e) => setSource(e.target.value)}
            />
          )}
        </Field>
        <Field label={t('finance2.incomeAmount')}>
          {(p) => (
            <input
              {...p}
              type="number"
              min="0"
              inputMode="numeric"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
            />
          )}
        </Field>
        <Field label={t('finance2.incomeDate')}>
          {(p) => <input {...p} type="date" value={date} onChange={(e) => setDate(e.target.value)} />}
        </Field>
        <label className="row" style={{ gap: 'var(--space-2)' }}>
          <input type="checkbox" checked={regular} onChange={(e) => setRegular(e.target.checked)} />
          <span style={{ fontSize: 13 }}>{t('finance2.incomeRegular')}</span>
        </label>
        <label className="row" style={{ gap: 'var(--space-2)' }}>
          <input type="checkbox" checked={cash} onChange={(e) => setCash(e.target.checked)} />
          <span style={{ fontSize: 13 }}>{t('finance2.incomeCash')}</span>
        </label>
        <label className="row" style={{ gap: 'var(--space-2)' }}>
          <input type="checkbox" checked={shared} onChange={(e) => setShared(e.target.checked)} />
          <span style={{ fontSize: 13 }}>{t('finance2.incomeShared')}</span>
        </label>
        <p className="field__hint">{t('finance2.incomeRegularHint')}</p>
        <button
          className="btn btn--block"
          onClick={save}
          disabled={!source.trim() || amountOf(amount) <= 0}
        >
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}
