import { db, logAudit, newEnvelope } from '@/db/db'
import { useOwned } from '@/db/hooks'
import type { Envelope, Owned } from '@/types/domain'
import { patchFinance, removeFinance } from './store'
import type { MoneySpace } from './money'
import { applyRepayment, type DebtDirection } from './debt'

/**
 * Persistence for debts (F16).
 *
 * ponytail: no new Dexie store. A debt is a `ledger` row discriminated by
 * `kind:'debt'` and pinned to `accountId:''` — exactly like the budget/income
 * rows batch 3 added — so the account screens (which match `accountId ===
 * account.id`) never render it, and backup's required ledger fields
 * (accountId, label, amount, date) are all satisfied. Promote to a dedicated
 * `debts` store with a `.version(5)` block only if it ever needs its own index;
 * see the return note. Everything else is the house pattern: `newEnvelope()` on
 * write, `useOwned()` on read.
 */

const NO_ACCOUNT = '' as const

/** One debt. Space drives privacy: personal debt stays private, a shared one is disclosed. */
export type DebtRecord = Owned<{
  kind: 'debt'
  accountId: typeof NO_ACCOUNT
  /** Counterparty, user-typed ("Ibu", "Andi"). Never a lender the app invents. Also the ledger label. */
  label: string
  direction: DebtDirection
  /** Principal. Stored as the ledger `amount`. */
  amount: number
  paid: number
  category: 'debt'
  space: MoneySpace
  /** When it was incurred; also the ledger `date` backup requires. */
  date: string
  /** Informal debt often has none — that is fine, not missing. */
  dueDate?: string
  note?: string
  planned: false
}>

const dataClassFor = (space: MoneySpace) => (space === 'shared' ? 'C2_shared_ops' : 'C1_personal')
const visibilityFor = (space: MoneySpace): Envelope['visibility'] =>
  space === 'shared' ? 'shared' : 'private'

export function useDebts(viewerProfileId: string | undefined): DebtRecord[] | undefined {
  const rows = useOwned<DebtRecord>('ledger', viewerProfileId, (a, b) => b.date.localeCompare(a.date))
  return rows?.filter((r) => r.kind === 'debt')
}

export async function addDebt(
  ownerProfileId: string,
  input: {
    counterparty: string
    direction: DebtDirection
    amount: number
    space: MoneySpace
    date: string
    dueDate?: string
    note?: string
  },
): Promise<string> {
  const env = newEnvelope(ownerProfileId, dataClassFor(input.space), {
    visibility: visibilityFor(input.space),
  })
  const row: DebtRecord = {
    ...env,
    kind: 'debt',
    accountId: NO_ACCOUNT,
    label: input.counterparty,
    direction: input.direction,
    amount: Math.max(0, Math.round(input.amount)),
    paid: 0,
    category: 'debt',
    space: input.space,
    date: input.date,
    ...(input.dueDate ? { dueDate: input.dueDate } : {}),
    ...(input.note ? { note: input.note } : {}),
    planned: false,
  }
  await db.ledger.put(row as never)
  await logAudit({
    actorProfileId: ownerProfileId,
    action: 'create',
    objectStore: 'ledger',
    objectId: env.id,
    summary: 'ledger dibuat',
  })
  return env.id
}

/** Record a repayment. `paid` is clamped so it can never exceed the principal. */
export async function repayDebt(debt: DebtRecord, pay: number): Promise<void> {
  await patchFinance('ledger', debt.id, { paid: applyRepayment(debt, pay) } as never)
}

export async function removeDebt(id: string, actorProfileId: string): Promise<void> {
  await removeFinance('ledger', id, actorProfileId)
}
