import { addDays, parseISO } from 'date-fns'

/**
 * Proposal lifecycle — pure, no React/Dexie/copy (F13–F15).
 *
 * A change to shared money is a *proposal*, never an applied fact: it is raised,
 * the other person accepts / edits / declines, and until they answer it is
 * pending. But "pending" must never harden into a permanent obligation — so a
 * proposal also expires on its own and can be withdrawn by the person who
 * raised it (F14). This module decides the *effective* state from what was
 * stored plus the clock; the store only records the answer, and the screen only
 * renders a message key.
 */

/** The answer as it is stored. `expired` is never stored — it is read off the clock. */
export type StoredStatus = 'sent' | 'agreed' | 'declined' | 'noted' | 'withdrawn'
export type ProposalState = StoredStatus | 'expired'

/** Just the fields the lifecycle turns on. The persisted record carries more. */
export interface ProposalLike {
  ownerProfileId: string
  status: StoredStatus
  /** ISO instant after which an unanswered proposal lapses. Absent = no deadline. */
  expiresAt?: string
  /** Set when the partner edited it into a counter-proposal: they are the last mover. */
  counteredByProfileId?: string
}

/** How long a fresh proposal waits before it lapses, unless the couple picks otherwise. */
export const DEFAULT_PROPOSAL_TTL_DAYS = 7

/** An expiry instant `days` after `nowISO`, or undefined for "no deadline". */
export function expiryFromNow(nowISO: string, days: number): string | undefined {
  if (!Number.isFinite(days) || days <= 0) return undefined
  return addDays(parseISO(nowISO), Math.round(days)).toISOString()
}

/**
 * The state to act on right now. Only a still-waiting proposal can lapse: an
 * answer already given (agreed / declined / noted / withdrawn) is history, and
 * the clock does not get to rewrite it.
 */
export function proposalState(p: ProposalLike, nowISO: string): ProposalState {
  if (p.status === 'sent' && p.expiresAt && p.expiresAt <= nowISO) return 'expired'
  return p.status
}

/** A pending proposal — the only kind that can still be answered, withdrawn, or lapse. */
export function isPending(p: ProposalLike, nowISO: string): boolean {
  return proposalState(p, nowISO) === 'sent'
}

/**
 * Whose answer the proposal is waiting on. It is answered by the person who did
 * *not* make the last move: the raiser at first, and after a counter-proposal,
 * whoever it was countered *to*. Returns undefined when nobody is on the hook
 * (no partner, or it is no longer pending).
 */
export function awaitingProfileId(
  p: ProposalLike,
  partnerProfileId: string | undefined,
  nowISO: string,
): string | undefined {
  if (!partnerProfileId) return undefined
  if (!isPending(p, nowISO)) return undefined
  const lastMover = p.counteredByProfileId ?? p.ownerProfileId
  return lastMover === p.ownerProfileId ? partnerProfileId : p.ownerProfileId
}

/** Whether this viewer is the one who may accept / edit / decline right now. */
export function canAnswer(
  p: ProposalLike,
  viewerProfileId: string,
  partnerProfileId: string | undefined,
  nowISO: string,
): boolean {
  return awaitingProfileId(p, partnerProfileId, nowISO) === viewerProfileId
}

/** Whether this viewer may withdraw it: only the raiser, and only while pending. */
export function canWithdraw(p: ProposalLike, viewerProfileId: string, nowISO: string): boolean {
  return p.ownerProfileId === viewerProfileId && isPending(p, nowISO)
}

/**
 * F15, stated once: below the threshold either partner may act alone; at or
 * above it both must agree. The single number X the couple set is `agreeAbove`
 * from their agreement. (The kasih_tahu band between the notify and agree
 * numbers is a courtesy heads-up, not a second gate — see `proposalTier`.)
 */
export function bothMustAgree(amount: number, agreeAbove: number): boolean {
  return Math.max(0, Math.round(amount)) > Math.max(0, agreeAbove)
}
