/**
 * Category taxonomy tuned to Indonesian households (F19) — pure, no React, no
 * Dexie, no copy.
 *
 * A generic "Groceries / Rent / Utilities" list misses how money actually leaves
 * an Indonesian household: kos/kontrakan rather than a mortgage, listrik token
 * bought in advance, pulsa/paket data, arisan and iuran RT, zakat/perpuluhan,
 * and the seasonal spikes of THR and mudik. This is the canonical set.
 *
 * It is a *suggestion layer*, never a cage: the entry forms still accept any
 * free-typed category. `classify()` maps a typed category onto a canonical id
 * (via aliases) for the overview, and anything it does not recognise lands in
 * `lainnya` rather than being dropped. Each id is a message key
 * `finance2.cat.<id>` / group key `finance2.catGroup.<group>`.
 */

export type CategoryGroup = 'rumah' | 'kebutuhan' | 'sosial' | 'keluarga' | 'musiman' | 'lain'

/** Canonical category ids — a literal union so `finance2.cat.<id>` keys are checked. */
export type CategoryId =
  | 'kos_kontrakan'
  | 'listrik'
  | 'air'
  | 'internet'
  | 'gas'
  | 'makan'
  | 'belanja'
  | 'pulsa'
  | 'transport'
  | 'kesehatan'
  | 'arisan'
  | 'iuran_rt'
  | 'zakat'
  | 'sumbangan'
  | 'kirim_ortu'
  | 'anak'
  | 'cicilan'
  | 'thr'
  | 'mudik'
  | 'liburan'

export interface CategoryDef {
  id: CategoryId
  group: CategoryGroup
  /** Lower-cased spellings that map onto this id. The id itself always matches. */
  aliases: string[]
}

/** Ordered by group, then by everyday frequency within a group. */
export const HOUSEHOLD_CATEGORIES: readonly CategoryDef[] = [
  // Rumah — tempat tinggal & tagihan rutin
  { id: 'kos_kontrakan', group: 'rumah', aliases: ['kos', 'kost', 'kontrakan', 'sewa', 'ngekos', 'sewa rumah'] },
  { id: 'listrik', group: 'rumah', aliases: ['token', 'token listrik', 'pln', 'listrik token', 'setrum'] },
  { id: 'air', group: 'rumah', aliases: ['pdam', 'air pam', 'tagihan air'] },
  { id: 'internet', group: 'rumah', aliases: ['wifi', 'wi-fi', 'indihome', 'wifi rumah'] },
  { id: 'gas', group: 'rumah', aliases: ['lpg', 'gas lpg', 'gas elpiji', 'elpiji', 'gas melon'] },

  // Kebutuhan sehari-hari
  { id: 'makan', group: 'kebutuhan', aliases: ['makan', 'jajan', 'makan siang', 'makan di luar'] },
  { id: 'belanja', group: 'kebutuhan', aliases: ['belanja', 'belanja bulanan', 'sembako', 'pasar', 'groceries'] },
  { id: 'pulsa', group: 'kebutuhan', aliases: ['pulsa', 'paket data', 'kuota', 'paketan', 'data'] },
  { id: 'transport', group: 'kebutuhan', aliases: ['transport', 'transportasi', 'bensin', 'ojek', 'ojol', 'gojek', 'grab', 'bbm'] },
  { id: 'kesehatan', group: 'kebutuhan', aliases: ['kesehatan', 'bpjs', 'obat', 'dokter', 'berobat'] },

  // Sosial & kewajiban
  { id: 'arisan', group: 'sosial', aliases: ['arisan'] },
  { id: 'iuran_rt', group: 'sosial', aliases: ['iuran', 'iuran rt', 'rt', 'keamanan', 'sampah', 'iuran warga', 'iuran rw'] },
  { id: 'zakat', group: 'sosial', aliases: ['zakat', 'infak', 'infaq', 'sedekah', 'perpuluhan', 'persembahan', 'kolekte'] },
  { id: 'sumbangan', group: 'sosial', aliases: ['sumbangan', 'kondangan', 'nyumbang', 'hajatan', 'amplop'] },

  // Keluarga
  { id: 'kirim_ortu', group: 'keluarga', aliases: ['kirim ortu', 'kirim orang tua', 'orang tua', 'ortu', 'kirim kampung'] },
  { id: 'anak', group: 'keluarga', aliases: ['anak', 'sekolah', 'spp', 'uang sekolah', 'susu', 'popok'] },
  { id: 'cicilan', group: 'keluarga', aliases: ['cicilan', 'kredit', 'angsuran', 'kpr', 'paylater', 'cicil'] },

  // Musiman
  { id: 'thr', group: 'musiman', aliases: ['thr', 'thr lebaran', 'angpao', 'angpau'] },
  { id: 'mudik', group: 'musiman', aliases: ['mudik', 'pulang kampung', 'tiket mudik'] },
  { id: 'liburan', group: 'musiman', aliases: ['liburan', 'jalan-jalan', 'wisata', 'healing'] },
]

const INDEX = new Map<string, string>()
for (const c of HOUSEHOLD_CATEGORIES) {
  INDEX.set(c.id, c.id)
  for (const a of c.aliases) INDEX.set(a, c.id)
}

export function normalizeCategory(raw: string): string {
  return raw.trim().toLowerCase()
}

/** Map a typed category onto a canonical id, or `lainnya` if it is unrecognised. */
export function classify(raw: string): string {
  return INDEX.get(normalizeCategory(raw)) ?? 'lainnya'
}

export interface CategoryTotal {
  /** Canonical id, or `lainnya`. */
  id: string
  group: CategoryGroup | 'lain'
  amount: number
}

export interface CategoryOutflow {
  /** Signed ledger amount; only negatives (money out) are counted. */
  amount: number
  category: string
  /** yyyy-MM-dd. */
  date: string
}

const GROUP_OF = new Map<string, CategoryGroup>(HOUSEHOLD_CATEGORIES.map((c) => [c.id, c.group]))

/**
 * Real spend per canonical category, biggest first, over one month (or all time
 * if `month` is omitted). Every figure is the sum of what the user actually
 * recorded — a description of the past, never a budget or a recommendation.
 * Unrecognised categories are summed into `lainnya` so nothing is silently lost.
 */
export function taxonomyTotals(outflows: CategoryOutflow[], month?: string): CategoryTotal[] {
  const sums = new Map<string, number>()
  for (const o of outflows) {
    if (o.amount >= 0) continue
    if (month && o.date.slice(0, 7) !== month) continue
    const id = classify(o.category)
    sums.set(id, (sums.get(id) ?? 0) + Math.round(-o.amount))
  }
  return [...sums.entries()]
    .map(([id, amount]) => ({ id, group: GROUP_OF.get(id) ?? ('lain' as const), amount }))
    .sort((a, b) => b.amount - a.amount || a.id.localeCompare(b.id))
}
