import { canRead, type Envelope } from '@/types/domain'
import { disclosedFields, type Disclosure, type DisclosedFields, type MoneySpace } from './money'

/**
 * The money object model (FIN-01) — pure, no React, no Dexie, no copy.
 *
 * Every money object (rekening, amplop, tagihan, transaksi) answers four
 * questions, and they are four *independent* fields on purpose:
 *
 *   1. Ownership       — whose money it is        → `Envelope.ownerProfileId`
 *   2. Visibility      — who may look, how deep   → `disclosure`
 *   3. Responsibility  — who is on the hook to pay → `responsibleProfileIds`
 *   4. Decision rights — who may say yes to spending → `deciderProfileIds`
 *
 * Real couples split these apart ("rekening dia, dua-duanya lihat, aku yang
 * bayar listrik dari situ, dia yang putuskan"). Collapsing them into one
 * mine/ours flag is what makes joint-finance apps feel like surveillance, so
 * nothing in this module lets one field imply another. Ownership in particular
 * is never stored here: it lives on the envelope, which a feature may not forge.
 */

// ---------------------------------------------------------------------------
// The four answers
// ---------------------------------------------------------------------------

/** The three fields a money row carries in addition to its envelope. */
export interface MoneyRights {
  /** Siapa bertanggung jawab bayar. Empty means "belum diputuskan", not "nobody". */
  responsibleProfileIds: string[]
  /** Siapa boleh memutuskan pengeluaran. */
  deciderProfileIds: string[]
  /** Siapa boleh lihat, dan seberapa dalam. Only the owner may widen this. */
  disclosure: Disclosure
}

/**
 * Any money row. Rights are optional because rows written before this model
 * existed (and rows that deliberately inherit from their account) do not carry
 * them; `resolveRights` is the single place that decides what that means.
 */
export type MoneyObject = Envelope & Partial<MoneyRights> & { space?: MoneySpace }

/**
 * Sensible starting rights for a new row. The space picked in the form is a
 * shorthand for a *default*, never a lock — the owner can still change each of
 * the three afterwards, one at a time.
 */
export function defaultRights(ownerProfileId: string, space: MoneySpace, partnerProfileId?: string): MoneyRights {
  const both = partnerProfileId ? [ownerProfileId, partnerProfileId] : [ownerProfileId]
  switch (space) {
    case 'shared':
      return { responsibleProfileIds: both, deciderProfileIds: both, disclosure: 'detail' }
    case 'disclosed':
      return {
        responsibleProfileIds: [ownerProfileId],
        deciderProfileIds: [ownerProfileId],
        disclosure: 'ringkasan',
      }
    case 'mine':
    default:
      return {
        responsibleProfileIds: [ownerProfileId],
        deciderProfileIds: [ownerProfileId],
        disclosure: 'privat',
      }
  }
}

export interface ResolvedRights extends MoneyRights {
  ownerProfileId: string
  /** True when some field came from the parent account instead of the row. */
  inherited: boolean
}

/**
 * The four answers for one row.
 *
 * A transaction or a bill may set its own responsibility, its own decider and
 * its own disclosure — a bill on her account that he is responsible for is a
 * normal arrangement, not an edge case. What it does not set, it inherits from
 * the account it sits in, because "opening a statement" should be one decision
 * and not one decision per row. Ownership never inherits: the row's own
 * envelope is the only answer to "whose is this".
 */
export function resolveRights(row: MoneyObject, parent?: MoneyObject): ResolvedRights {
  const fallback = parent ?? row
  const responsible = row.responsibleProfileIds ?? fallback.responsibleProfileIds
  const decider = row.deciderProfileIds ?? fallback.deciderProfileIds
  const disclosure = row.disclosure ?? fallback.disclosure
  return {
    ownerProfileId: row.ownerProfileId,
    responsibleProfileIds: responsible ?? [row.ownerProfileId],
    deciderProfileIds: decider ?? [row.ownerProfileId],
    disclosure: disclosure ?? 'privat',
    inherited:
      row.responsibleProfileIds === undefined ||
      row.deciderProfileIds === undefined ||
      row.disclosure === undefined,
  }
}

/**
 * Whether this viewer is one of the people who may say yes to spending here.
 * An empty decider list means the couple has not decided who decides, which is
 * not the same as "anybody may" — so it answers false for everyone, including
 * the owner, and the screen asks them to fill it in.
 */
export function canDecide(row: MoneyObject, viewerProfileId: string, parent?: MoneyObject): boolean {
  return resolveRights(row, parent).deciderProfileIds.includes(viewerProfileId)
}

/** Whether the owner is allowed to widen visibility. Only ever the owner (05 §4). */
export function mayWiden(row: MoneyObject, actorProfileId: string): boolean {
  return row.ownerProfileId === actorProfileId
}

// ---------------------------------------------------------------------------
// The three money spaces (FIN-02)
// ---------------------------------------------------------------------------

/**
 * Uang Saya · Uang Kamu · Uang Kita — relative to whoever is looking.
 *
 * The space is not a stored label, it is a *view*: the same account is "uang
 * saya" to its owner and "uang kamu" to their partner. Storing it per viewer
 * would be the bug that leaks, because then one row would have to claim which
 * side it belongs to.
 */
export type ViewerSpace = 'saya' | 'kamu' | 'kita'
export const VIEWER_SPACES: readonly ViewerSpace[] = ['saya', 'kamu', 'kita']

/**
 * Which of the three spaces this row lands in for this viewer. Co-owned money
 * is "kita" for both of them; everything else is sorted by ownership alone,
 * never by how much of it happens to be shared.
 */
export function spaceOf(row: MoneyObject, viewerProfileId: string): ViewerSpace {
  if (row.space === 'shared') return 'kita'
  if (row.coOwnerProfileIds.length > 0 && row.coOwnerProfileIds.includes(viewerProfileId)) return 'kita'
  return row.ownerProfileId === viewerProfileId ? 'saya' : 'kamu'
}

/**
 * How much of a row this viewer may see. The owner sees all of their own; for
 * anyone else the answer comes from the owner's disclosure level and nothing
 * else — not from the space, not from who pays it, not from who decides.
 */
export function visibleFields(row: MoneyObject, viewerProfileId: string, parent?: MoneyObject): DisclosedFields {
  if (row.ownerProfileId === viewerProfileId) {
    return { exists: true, balance: true, categories: true, entries: true }
  }
  return disclosedFields(resolveRights(row, parent).disclosure)
}

/**
 * The rule that makes the three spaces trustworthy: **a space never silently
 * reveals another.**
 *
 * A row reaches a space only if the read gate passes *and* its owner disclosed
 * that it exists. Rows that fail either check are dropped whole — not counted,
 * not totalled, not shown as "1 rekening tersembunyi". A count is a disclosure
 * too: "kamu punya sesuatu yang kamu sembunyikan" is exactly the reveal this
 * rule exists to prevent, and the app has no business making it.
 *
 * The owner's own view is the exception in the other direction: your own money
 * is always fully visible to you, whatever you have disclosed to your partner.
 */
export function inSpace(row: MoneyObject, viewerProfileId: string): boolean {
  if (row.deletedAt) return false
  if (row.ownerProfileId === viewerProfileId) return true
  if (!canRead(row, viewerProfileId)) return false
  return visibleFields(row, viewerProfileId).exists
}

/** Every readable row, split into the three spaces. One row, at most one space. */
export function partitionSpaces<T extends MoneyObject>(
  rows: T[],
  viewerProfileId: string,
): Record<ViewerSpace, T[]> {
  const out: Record<ViewerSpace, T[]> = { saya: [], kamu: [], kita: [] }
  for (const row of rows) {
    if (!inSpace(row, viewerProfileId)) continue
    out[spaceOf(row, viewerProfileId)].push(row)
  }
  return out
}

/**
 * Total of the balances this viewer may actually see in one space. Rows whose
 * balance is withheld contribute nothing and are reported separately, so a
 * total is never a back door to a number the owner did not disclose.
 */
export function spaceTotal<T extends MoneyObject & { balance: number }>(
  rows: T[],
  viewerProfileId: string,
): { total: number; counted: number; withheld: number } {
  let total = 0
  let counted = 0
  let withheld = 0
  for (const row of rows) {
    if (visibleFields(row, viewerProfileId).balance) {
      total += Math.round(row.balance)
      counted++
    } else withheld++
  }
  return { total, counted, withheld }
}
