import { useMemo } from 'react'
import { format } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState } from '@/components/ui'
import { useI18n } from '@/i18n'
import { formatRupiah } from '@/i18n/format'
import { useFinance, type LedgerEntry } from './store'
import { HOUSEHOLD_CATEGORIES, taxonomyTotals } from './taxonomy'

/**
 * Kategori rumah tangga (F19).
 *
 * The taxonomy is tuned to how an Indonesian household actually spends — kos,
 * token listrik, pulsa, arisan, iuran RT, zakat, THR, mudik — and it is shown
 * beside the real amount recorded against each this month, read from IndexedDB.
 * Nothing here is a budget or a recommendation: it describes what was logged, and
 * anything typed outside the taxonomy is summed into "lainnya", never dropped.
 */

const GROUP_ORDER = ['rumah', 'kebutuhan', 'sosial', 'keluarga', 'musiman'] as const

export default function Categories({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const entries = useFinance<'ledger'>('ledger', me)
  const month = format(new Date(), 'yyyy-MM')

  const { byId, total, other } = useMemo(() => {
    const outflows = (entries ?? [])
      .filter((e: LedgerEntry) => e.kind === 'ledger')
      .map((e) => ({ amount: e.amount, category: e.category, date: e.date }))
    const totals = taxonomyTotals(outflows, month)
    const map = new Map(totals.map((c) => [c.id, c.amount]))
    return {
      byId: map,
      total: totals.reduce((s, c) => s + c.amount, 0),
      other: map.get('lainnya') ?? 0,
    }
  }, [entries, month])

  const hasAny = total > 0

  return (
    <div className="stack">
      <Card title={t('finance2.catTitle')} icon="money" hint={t('finance2.catHint')}>
        {!hasAny ? (
          <EmptyState icon="money" title={t('finance2.catEmpty')} hint={t('finance2.catEmptyHint')} />
        ) : (
          <p className="card__hint">
            {t('finance2.catMonthTotal', { amount: formatRupiah(total, locale) })}
          </p>
        )}

        {GROUP_ORDER.map((group) => {
          const cats = HOUSEHOLD_CATEGORIES.filter((c) => c.group === group)
          return (
            <div key={group} className="stack stack--tight" style={{ marginTop: 'var(--space-3)' }}>
              <strong style={{ fontSize: 13 }}>{t(`finance2.catGroup.${group}`)}</strong>
              <ul className="list">
                {cats.map((c) => {
                  const amt = byId.get(c.id) ?? 0
                  return (
                    <li key={c.id} className="list__item">
                      <Icon name="money" size={16} />
                      <span className="grow">{t(`finance2.cat.${c.id}`)}</span>
                      <span className={amt > 0 ? '' : 'card__hint'}>
                        {amt > 0 ? formatRupiah(amt, locale) : '—'}
                      </span>
                    </li>
                  )
                })}
              </ul>
            </div>
          )
        })}

        {other > 0 && (
          <div className="stack stack--tight" style={{ marginTop: 'var(--space-3)' }}>
            <ul className="list">
              <li className="list__item">
                <Icon name="money" size={16} />
                <span className="grow">{t('finance2.cat.lainnya')}</span>
                <span>{formatRupiah(other, locale)}</span>
              </li>
            </ul>
          </div>
        )}
      </Card>

      <p className="disclaimer">{t('finance2.catCaveat')}</p>
    </div>
  )
}
