import { useMemo, useState } from 'react'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState } from '@/components/ui'
import { useOwned } from '@/db/hooks'
import { exportBackup } from '@/db/backup'
import { downloadJson } from '@/utils/download'
import { useI18n } from '@/i18n'
import { formatRupiah, whenLabel } from '@/i18n/format'
import type { Bill, Envelope, MoneyMeeting, SharedGoal } from '@/types/domain'
import { useFinance } from './store'
import { VIEWER_SPACES, partitionSpaces, spaceTotal } from './model'
import { summarizeFinance, FINANCE_ALL_STORES, type CountedRow } from './summary'

/**
 * F25 — Ringkasan: the one screen that ties the whole money module together.
 *
 * It reads every finance row the viewer is allowed to see, through the same gate
 * as every other screen, and shows two honest things: where their own money sits
 * across the three spaces, and how much of each feature has been written down.
 *
 * It is a mirror, never a scoreboard. No total is compared to the partner's, no
 * count is called good or bad, nothing here is advice. The backup card states the
 * plain fact that all of this travels in a normal app backup, and sends the actual
 * restore — the one risky, irreversible step — to Privasi where it belongs.
 */

const kindOf = (r: unknown): string | undefined => (r as { kind?: string }).kind

export default function Overview({ me }: { me: string }) {
  const { t, locale } = useI18n()

  const accounts = useFinance<'accounts'>('accounts', me)
  const ledger = useFinance<'ledger'>('ledger', me)
  const splits = useFinance<'splits'>('splits', me)
  const rules = useFinance<'contributionRules'>('contributionRules', me)
  const proposals = useFinance<'proposals'>('proposals', me)
  const bills = useOwned<Bill>('bills', me)
  const goals = useOwned<SharedGoal>('goals', me)
  const meetings = useOwned<MoneyMeeting>('meetings', me)

  const loading =
    !accounts || !ledger || !splits || !rules || !proposals || !bills || !goals || !meetings

  // Every readable finance row, tagged with the store (and ledger kind) the
  // summary groups by. `readable`/`useOwned` already dropped soft-deleted and
  // withheld rows, so this is exactly what the screens show.
  const rows = useMemo<CountedRow[]>(() => {
    const tag = (store: string, list: readonly Envelope[] | undefined): CountedRow[] =>
      (list ?? []).map((r) => ({
        store,
        ...(kindOf(r) ? { kind: kindOf(r) } : {}),
        updatedAt: r.updatedAt,
      }))
    return [
      ...tag('accounts', accounts as Envelope[] | undefined),
      ...tag('ledger', ledger as Envelope[] | undefined),
      ...tag('splits', splits as Envelope[] | undefined),
      ...tag('contributionRules', rules as Envelope[] | undefined),
      ...tag('proposals', proposals as Envelope[] | undefined),
      ...tag('bills', bills),
      ...tag('goals', goals),
      ...tag('meetings', meetings),
    ]
  }, [accounts, ledger, splits, rules, proposals, bills, goals, meetings])

  const summary = useMemo(() => summarizeFinance(rows), [rows])

  // Where my own money sits, using the very functions the real partner view uses.
  const view = useMemo(() => partitionSpaces((accounts ?? []) as never[], me), [accounts, me])

  if (loading) return null

  const empty = summary.total === 0

  return (
    <div className="stack">
      {/* Where money sits — position, never a comparison */}
      <Card title={t('finance2.summary.positionTitle')} icon="money" hint={t('finance2.summary.positionHint')}>
        {empty ? (
          <EmptyState
            icon="money"
            title={t('finance2.summary.emptyTitle')}
            hint={t('finance2.summary.emptyHint')}
          />
        ) : (
          <ul className="list">
            {VIEWER_SPACES.map((space) => {
              const sums = spaceTotal(view[space] as never[], me)
              return (
                <li key={space} className="list__item" style={{ alignItems: 'flex-start' }}>
                  <Icon name="money" size={18} />
                  <span className="grow stack stack--tight">
                    <strong style={{ fontSize: 14 }}>{t(`finance2.space.${space}`)}</strong>
                    <span className="card__hint">
                      {sums.counted > 0
                        ? t('finance2.spaceTotal', {
                            amount: formatRupiah(sums.total, locale),
                            n: sums.counted,
                          })
                        : t('finance2.summary.spaceEmpty')}
                      {sums.withheld > 0 ? ` · ${t('finance2.summary.withheld', { n: sums.withheld })}` : ''}
                    </span>
                  </span>
                </li>
              )
            })}
          </ul>
        )}
      </Card>

      {/* What's been written down — per feature, described not ranked */}
      {!empty && (
        <Card title={t('finance2.summary.recordsTitle')} icon="backup" hint={t('finance2.summary.recordsHint')}>
          <ul className="list">
            {summary.sections
              .filter((s) => s.count > 0)
              .map((s) => (
                <li key={s.key} className="list__item" style={{ alignItems: 'flex-start' }}>
                  <Icon name="check" size={18} />
                  <span className="grow stack stack--tight">
                    <strong style={{ fontSize: 14 }}>{t(`finance2.summary.section.${s.key}`)}</strong>
                    {s.lastUpdated && (
                      <span className="card__hint">
                        {t('finance2.summary.lastUpdated', { when: whenLabel(s.lastUpdated.slice(0, 10), t, locale) })}
                      </span>
                    )}
                  </span>
                  <span className="chip">{t('finance2.summary.count', { n: s.count })}</span>
                </li>
              ))}
          </ul>
          <p className="card__hint" style={{ marginTop: 'var(--space-2)' }}>
            {t('finance2.summary.total', { n: summary.total })}
            {summary.lastActivity
              ? ` · ${t('finance2.summary.lastActivity', { when: whenLabel(summary.lastActivity.slice(0, 10), t, locale) })}`
              : ''}
          </p>
        </Card>
      )}

      {/* Backup coverage — the fact, plus a working export; restore lives in Privasi */}
      <BackupCard me={me} financeCount={summary.total} />

      <p className="disclaimer">{t('finance2.summary.disclaimer')}</p>
    </div>
  )
}

function BackupCard({ me, financeCount }: { me: string; financeCount: number }) {
  const { t } = useI18n()
  const [busy, setBusy] = useState(false)

  async function download() {
    setBusy(true)
    try {
      // Finance is all C1/C2, so it travels whether or not health data is opted in.
      const pkg = await exportBackup({ actorProfileId: me, includeSensitive: false })
      downloadJson(`temudua-cadangan-${new Date().toISOString().slice(0, 10)}.json`, pkg)
    } finally {
      setBusy(false)
    }
  }

  return (
    <Card title={t('finance2.summary.backupTitle')} icon="backup" hint={t('finance2.summary.backupHint')}>
      <p className="banner">
        <Icon name="info" size={16} /> {t('finance2.summary.backupCovered', { n: FINANCE_ALL_STORES.length })}
      </p>
      <p className="card__hint">{t('finance2.summary.backupCount', { n: financeCount })}</p>
      <button className="btn btn--block" onClick={download} disabled={busy} style={{ marginTop: 'var(--space-2)' }}>
        <Icon name="backup" size={16} /> {t('finance2.summary.backupDownload')}
      </button>
      <p className="field__hint">{t('finance2.summary.backupRestore')}</p>
    </Card>
  )
}
