import { useLiveQuery } from 'dexie-react-hooks'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState } from '@/components/ui'
import { db } from '@/db/db'
import { useSession } from '@/app/session'
import { useI18n } from '@/i18n'
import { whenLabel } from '@/i18n/format'
import { downloadJson } from '@/utils/download'
import type { AuditEvent, Envelope } from '@/types/domain'
import { useFinance } from './store'
import { useLedger, useBills } from './ledgerStore'
import { freezePlan, myLedgerExport } from './separation'

/**
 * Privasi & pisah — money side (F23 + F24).
 *
 * F23: every widening of who-can-see is an explicit, logged, one-way-per-act
 * change; the widening control itself lives on each account (Ruang uang), and
 * here the owner sees the honest record of those acts, drawn from the audit log
 * — that a change happened and to which level, never the balances behind it.
 *
 * F24: what the couple's money becomes if they separate — shared money freezes
 * to a read-only snapshot, each keeps their own, and neither can read the
 * other's afterward — plus a button to export *your* ledger now, so you leave
 * with your own copy. Nothing here performs the separation; that lives in the
 * privacy module. This is the money-side preview and export.
 */

export default function MoneyPrivacy({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const { partner } = useSession()

  const accounts = useFinance<'accounts'>('accounts', me)
  const ledger = useFinance<'ledger'>('ledger', me)
  const splits = useLedger(me)
  const bills = useBills(me)

  // My own history of widening/closing account visibility. Only my acts, on my
  // own accounts — never a window into what my partner has disclosed.
  const transitions = useLiveQuery(async () => {
    const rows = (await db.audit.toArray()) as AuditEvent[]
    return rows
      .filter(
        (a) =>
          a.actorProfileId === me &&
          a.objectStore === 'accounts' &&
          (a.action === 'share' || a.action === 'revoke'),
      )
      .sort((a, b) => b.timestamp.localeCompare(a.timestamp))
      .slice(0, 12)
  }, [me])

  const allMoney: Envelope[] = [
    ...((accounts ?? []) as Envelope[]),
    ...((ledger ?? []) as Envelope[]),
    ...((splits ?? []) as Envelope[]),
    ...((bills ?? []) as Envelope[]),
  ]
  const plan = partner ? freezePlan(allMoney as never[], me, partner.id) : null

  function exportLedger() {
    const pkg = myLedgerExport(allMoney, me, new Date().toISOString())
    downloadJson(`temudua-uang-${new Date().toISOString().slice(0, 10)}.json`, pkg)
  }

  return (
    <div className="stack">
      {/* F23 — visibility transitions */}
      <Card title={t('finance2.trans.title')} icon="private" hint={t('finance2.trans.hint')}>
        <p className="banner">
          <Icon name="info" size={16} /> {t('finance2.trans.oneWay')}
        </p>
        {(transitions ?? []).length === 0 ? (
          <EmptyState
            icon="private"
            title={t('finance2.trans.none')}
            hint={t('finance2.trans.noneHint')}
          />
        ) : (
          <ul className="list">
            {(transitions ?? []).map((a) => (
              <li key={a.seq} className="list__item" style={{ alignItems: 'flex-start' }}>
                <Icon name={a.action === 'share' ? 'shared' : 'private'} size={18} />
                <span className="grow stack stack--tight">
                  <strong style={{ fontSize: 14 }}>
                    {t(a.action === 'share' ? 'finance2.trans.widened' : 'finance2.trans.narrowed')}
                  </strong>
                  <span className="card__hint">{whenLabel(a.timestamp.slice(0, 10), t, locale)}</span>
                </span>
              </li>
            ))}
          </ul>
        )}
      </Card>

      {/* F24 — separation protocol, money side */}
      <Card title={t('finance2.sep.title')} icon="backup" hint={t('finance2.sep.hint')}>
        <ul className="list">
          <li className="list__item" style={{ alignItems: 'flex-start' }}>
            <Icon name="shared" size={18} />
            <span className="grow">
              {t('finance2.sep.freeze', { n: plan?.freezeShared ?? 0 })}
            </span>
          </li>
          <li className="list__item" style={{ alignItems: 'flex-start' }}>
            <Icon name="self" size={18} />
            <span className="grow">{t('finance2.sep.mine', { n: plan?.staysMine ?? 0 })}</span>
          </li>
          <li className="list__item" style={{ alignItems: 'flex-start' }}>
            <Icon name="private" size={18} />
            <span className="grow">
              {t('finance2.sep.partner', { n: plan?.partnerLosesAccess ?? 0 })}
            </span>
          </li>
        </ul>

        <button className="btn btn--block" onClick={exportLedger} style={{ marginTop: 'var(--space-3)' }}>
          <Icon name="backup" size={16} /> {t('finance2.sep.export')}
        </button>
        <p className="field__hint">{t('finance2.sep.exportHint')}</p>
        <p className="disclaimer" style={{ marginTop: 'var(--space-2)' }}>
          {t('finance2.sep.caveat')}
        </p>
      </Card>
    </div>
  )
}
