import type { Disclosure } from './money'

/**
 * Visibility transitions (F23) — pure classification, returns keys only.
 *
 * Moving a money object from private toward shared is a real act: explicit,
 * confirmed, and logged, one act at a time — never a silent flip. This module
 * decides only *which* kind of move a proposed change is and whether it needs a
 * confirm; the store still does the write and the audit log. Ownership is not in
 * scope here — only the owner ever reaches this, enforced upstream.
 */

/** How much a partner may see, least to most. */
const RANK: Record<Disclosure, number> = { privat: 0, ringkasan: 1, kategori: 2, detail: 3 }

export type TransitionKind = 'widen' | 'narrow' | 'same'

export function classifyTransition(from: Disclosure, to: Disclosure): TransitionKind {
  if (RANK[to] > RANK[from]) return 'widen'
  if (RANK[to] < RANK[from]) return 'narrow'
  return 'same'
}

/**
 * Widening — letting a partner see more — is the one move that must never happen
 * by a stray tap, so it is confirmed. Narrowing (taking visibility back) is
 * always allowed and needs no ceremony; the owner should never be slowed down
 * from closing a door.
 */
export function requiresConfirm(from: Disclosure, to: Disclosure): boolean {
  return classifyTransition(from, to) === 'widen'
}

/** Message key describing the move, for the confirm prompt and the history row. */
export function transitionKey(kind: TransitionKind): string {
  return `finance2.trans.${kind}`
}
