import { format } from 'date-fns'
import { db, logAudit, newEnvelope } from '@/db/db'
import { useOwned } from '@/db/hooks'
import type { Envelope, Owned } from '@/types/domain'
import { patchFinance, removeFinance } from './store'
import { monthOf } from './budget'
import type { MoneySpace } from './money'

/**
 * Persistence for envelopes (F10) and income records (F12).
 *
 * ponytail: no new Dexie store. Both records live in the existing `ledger`
 * store, discriminated by `kind` and pinned to `accountId: ''` — an id no real
 * account has, so the account screens (which filter `accountId === account.id`)
 * never render them, and backup's required `ledger` fields (accountId, label,
 * amount, date) are all satisfied. Promote to dedicated `budgets` / `incomes`
 * stores with a `.version(5)` block if either ever needs its own index; see the
 * return note. Everything else is the house pattern: `newEnvelope()` on write,
 * `useOwned()` on read.
 */

const NO_ACCOUNT = '' as const

/** F10 — a budget pot in one space. `date` is the first of its period, for backup. */
export type PotRecord = Owned<{
  kind: 'budget'
  accountId: typeof NO_ACCOUNT
  /** Shown name; also the ledger `label` required by backup. */
  label: string
  /** The ledger category this pot budgets. Spending is matched to it. */
  category: string
  space: MoneySpace
  /** Monthly budget. Stored as the ledger `amount`. */
  amount: number
  /** Carried-in leftover from previous periods (0 unless rollover). */
  carried: number
  rollover: boolean
  /** yyyy-MM this pot is currently budgeting. */
  periodMonth: string
  date: string
  planned: false
}>

/** F12 — one income event. Irregular and cash are ordinary here, not edge cases. */
export type IncomeRecord = Owned<{
  kind: 'income'
  accountId: typeof NO_ACCOUNT
  /** Where it came from (gaji, freelance, jual online…). Also the ledger `label`. */
  label: string
  amount: number
  date: string
  category: 'income'
  /** Salary-like, expected monthly. Irregular income leaves this false. */
  regular: boolean
  cash: boolean
  planned: false
}>

const dataClassFor = (space: MoneySpace) => (space === 'shared' ? 'C2_shared_ops' : 'C1_personal')
const visibilityFor = (space: MoneySpace): Envelope['visibility'] =>
  space === 'shared' ? 'shared' : 'private'

// ---------------------------------------------------------------------------
// Reads — through the one gate, filtered to our kind
// ---------------------------------------------------------------------------

export function usePots(viewerProfileId: string | undefined): PotRecord[] | undefined {
  const rows = useOwned<PotRecord>('ledger', viewerProfileId, (a, b) => a.label.localeCompare(b.label))
  return rows?.filter((r) => r.kind === 'budget')
}

export function useIncomes(viewerProfileId: string | undefined): IncomeRecord[] | undefined {
  const rows = useOwned<IncomeRecord>('ledger', viewerProfileId, (a, b) => b.date.localeCompare(a.date))
  return rows?.filter((r) => r.kind === 'income')
}

// ---------------------------------------------------------------------------
// Writes
// ---------------------------------------------------------------------------

async function putLedger(ownerProfileId: string, space: MoneySpace, body: object): Promise<string> {
  const env = newEnvelope(ownerProfileId, dataClassFor(space), { visibility: visibilityFor(space) })
  await db.ledger.put({ ...env, ...body } as never)
  await logAudit({
    actorProfileId: ownerProfileId,
    action: 'create',
    objectStore: 'ledger',
    objectId: env.id,
    summary: 'ledger dibuat',
  })
  return env.id
}

export async function addPot(
  ownerProfileId: string,
  input: { label: string; category: string; space: MoneySpace; monthly: number; rollover: boolean },
  todayISO = format(new Date(), 'yyyy-MM-dd'),
): Promise<string> {
  const periodMonth = monthOf(todayISO)
  return putLedger(ownerProfileId, input.space, {
    kind: 'budget',
    accountId: NO_ACCOUNT,
    label: input.label,
    category: input.category,
    space: input.space,
    amount: Math.max(0, Math.round(input.monthly)),
    carried: 0,
    rollover: input.rollover,
    periodMonth,
    date: `${periodMonth}-01`,
    planned: false,
  })
}

/** Persist a rollover step (new carry + period), computed by `advancePot`. */
export async function rollPot(id: string, carried: number, periodMonth: string): Promise<void> {
  await patchFinance('ledger', id, { carried, periodMonth, date: `${periodMonth}-01` } as never)
}

export async function editPot(
  id: string,
  changes: { monthly?: number; rollover?: boolean },
): Promise<void> {
  const patch: Record<string, unknown> = {}
  if (changes.monthly !== undefined) patch.amount = Math.max(0, Math.round(changes.monthly))
  if (changes.rollover !== undefined) patch.rollover = changes.rollover
  await patchFinance('ledger', id, patch as never)
}

export async function removePot(id: string, actorProfileId: string): Promise<void> {
  await removeFinance('ledger', id, actorProfileId)
}

export async function addIncome(
  ownerProfileId: string,
  input: { source: string; amount: number; date: string; regular: boolean; cash: boolean; shared?: boolean },
): Promise<string> {
  return putLedger(ownerProfileId, input.shared ? 'shared' : 'mine', {
    kind: 'income',
    accountId: NO_ACCOUNT,
    label: input.source,
    amount: Math.max(0, Math.round(input.amount)),
    date: input.date,
    category: 'income',
    regular: input.regular,
    cash: input.cash,
    planned: false,
  })
}

export async function removeIncome(id: string, actorProfileId: string): Promise<void> {
  await removeFinance('ledger', id, actorProfileId)
}
