import { OWNED_STORES } from '@/db/db'
import { FINANCE_STORES, type FinanceStore } from './store'

/**
 * F25 — the domain summary, and the backup-coverage guard behind it.
 *
 * The whole money module writes into just a handful of stores: its own five
 * (`FINANCE_STORES`) plus the shared `bills`, `goals` and `meetings`. The busiest
 * of those, `ledger`, holds seven different feature-kinds at once (a plain entry,
 * an envelope, income, a savings goal and its contributions, an informal debt, an
 * arisan). So "tie the domain together" means one thing: read every one of those
 * rows through the normal gate and count them the way the tabs are grouped.
 *
 * It describes, it never ranks. A count of records is not a verdict on the couple
 * and never a comparison between the two people — it is just how much has been
 * written down. No amount, no score, no "who spends more".
 *
 * Coverage: every store the module touches is in `OWNED_STORES`, so it already
 * rides the normal envelope path in `db/backup.ts` with no change there.
 * `backupCoverageGap()` proves that at runtime and the round-trip test proves the
 * data actually survives an export → parse → restore.
 */

/** The stores finance writes into, beyond its own five. All are envelope stores. */
export const FINANCE_SHARED_STORES = ['bills', 'goals', 'meetings'] as const
export type FinanceSharedStore = (typeof FINANCE_SHARED_STORES)[number]

/** Every store the money module touches — the surface backup must cover. */
export const FINANCE_ALL_STORES = [...FINANCE_STORES, ...FINANCE_SHARED_STORES] as const

/** Which summary section a `ledger` row belongs to, by its `kind` discriminator. */
const LEDGER_KIND_SECTION: Record<string, string> = {
  ledger: 'transactions',
  budget: 'envelopes',
  income: 'income',
  savings_goal: 'savings',
  saving: 'savings',
  debt: 'debts',
  arisan: 'arisan',
}

/** Which section a row belongs to, by its store (and, for `ledger`, its kind). */
const STORE_SECTION: Record<string, string> = {
  accounts: 'accounts',
  splits: 'splits',
  contributionRules: 'agreement',
  proposals: 'proposals',
  bills: 'bills',
  goals: 'goals',
  meetings: 'meetings',
}

/**
 * The section a row lands in, or null if nothing claims it — which is a coverage
 * bug, not a normal state, and `summarizeFinance` counts it into `uncovered`.
 */
export function sectionOf(store: string, kind?: string): string | null {
  if (store === 'ledger') return LEDGER_KIND_SECTION[kind ?? 'ledger'] ?? null
  return STORE_SECTION[store] ?? null
}

/** Display order of the summary sections. Each key is an i18n key the screen renders. */
export const SUMMARY_SECTIONS = [
  'accounts',
  'transactions',
  'envelopes',
  'income',
  'savings',
  'debts',
  'arisan',
  'splits',
  'bills',
  'goals',
  'agreement',
  'proposals',
  'meetings',
] as const
export type SummarySection = (typeof SUMMARY_SECTIONS)[number]

export interface CountedRow {
  store: string
  kind?: string
  updatedAt: string
  deletedAt?: string
}

export interface SectionSummary {
  key: SummarySection
  count: number
  /** Most recent `updatedAt` in the section, ISO — absent when the section is empty. */
  lastUpdated?: string
}

export interface FinanceSummary {
  sections: SectionSummary[]
  total: number
  /** Most recent activity across everything, ISO. */
  lastActivity?: string
  /** Rows whose store/kind matched no section. A coverage guard — 0 in practice. */
  uncovered: number
}

const newer = (a: string | undefined, b: string): string => (a && a >= b ? a : b)

/**
 * Count rows per section and find the latest activity. Soft-deleted rows are
 * skipped so the summary matches what the screens show (`readable` already drops
 * them; this keeps the pure function honest when called directly).
 */
export function summarizeFinance(rows: readonly CountedRow[]): FinanceSummary {
  const counts: Record<string, number> = {}
  const last: Record<string, string | undefined> = {}
  let total = 0
  let uncovered = 0
  let lastActivity: string | undefined

  for (const r of rows) {
    if (r.deletedAt) continue
    const section = sectionOf(r.store, r.kind)
    if (!section) {
      uncovered++
      continue
    }
    counts[section] = (counts[section] ?? 0) + 1
    last[section] = newer(last[section], r.updatedAt)
    lastActivity = newer(lastActivity, r.updatedAt)
    total++
  }

  const sections = SUMMARY_SECTIONS.map((key) => ({
    key,
    count: counts[key] ?? 0,
    ...(last[key] ? { lastUpdated: last[key] } : {}),
  }))

  return { sections, total, ...(lastActivity ? { lastActivity } : {}), uncovered }
}

/**
 * Which finance stores are NOT in the given backup surface. Called with the real
 * `OWNED_STORES` it must return [] — every money store rides the normal backup.
 */
export function backupCoverageGap(covered: readonly string[] = OWNED_STORES): FinanceStore[] {
  return FINANCE_ALL_STORES.filter((s) => !covered.includes(s)) as FinanceStore[]
}
