import type { Envelope } from '@/types/domain'

/**
 * Separation protocol — the money side (F24), pure describe + export shaping.
 *
 * The writes that actually cut access live in `privacy/unpair.ts` and stay
 * there. This module is what the money screen shows *before* that happens: what
 * each kind of money row will become, and a portable snapshot of the ledger the
 * actor owns so they leave with their own copy. It never mutates anything.
 *
 * The three rules it states, from blueprint 05 §5:
 *   - shared money freezes to a read-only snapshot (nobody keeps editing a joint
 *     book after the split),
 *   - each partner exports their own ledger,
 *   - after the cutoff neither partner can read the other's — so the export only
 *     ever contains rows the actor already owns or co-owns.
 */

/** Just the fields the disposition depends on. `visibility` is compared as a string. */
interface MoneyRow {
  ownerProfileId: string
  coOwnerProfileIds: string[]
  visibility: string
}

export type MoneyDisposition = 'freeze_shared' | 'stays_mine' | 'partner_loses_access'

export function dispositionOf(row: MoneyRow, me: string, partnerId: string): MoneyDisposition {
  const shared =
    row.visibility === 'shared' ||
    row.visibility === 'both_partners' ||
    row.coOwnerProfileIds.includes(me) ||
    row.coOwnerProfileIds.includes(partnerId)
  if (shared) return 'freeze_shared'
  return row.ownerProfileId === me ? 'stays_mine' : 'partner_loses_access'
}

export interface FreezePlan {
  freezeShared: number
  staysMine: number
  partnerLosesAccess: number
}

/** Counts, so the screen can say plainly what will happen — no row bodies, no amounts. */
export function freezePlan(rows: MoneyRow[], me: string, partnerId: string): FreezePlan {
  const plan: FreezePlan = { freezeShared: 0, staysMine: 0, partnerLosesAccess: 0 }
  for (const r of rows) {
    const d = dispositionOf(r, me, partnerId)
    if (d === 'freeze_shared') plan.freezeShared++
    else if (d === 'stays_mine') plan.staysMine++
    else plan.partnerLosesAccess++
  }
  return plan
}

export interface LedgerExport<T> {
  format: 'temudua-ledger'
  exportedAt: string
  ownerProfileId: string
  rows: T[]
}

/**
 * The actor's own ledger, shaped for a portable file. Only rows they own or
 * co-own leave — a partner's private money is never in it, which is the whole
 * point of "no partner can retroactively read the other".
 */
export function myLedgerExport<T extends Pick<Envelope, 'ownerProfileId' | 'coOwnerProfileIds'>>(
  rows: T[],
  me: string,
  nowISO: string,
): LedgerExport<T> {
  return {
    format: 'temudua-ledger',
    exportedAt: nowISO,
    ownerProfileId: me,
    rows: rows.filter((r) => r.ownerProfileId === me || r.coOwnerProfileIds.includes(me)),
  }
}
