/**
 * Utang — debt tracking, pure (F16), no React/Dexie/copy.
 *
 * The common Indonesian case is informal: money borrowed from or lent to family,
 * no contract, often no interest and no fixed date ("nanti kalau ada"). So the
 * counterparty is a name the user types — never a lender the app invents —
 * interest is deliberately not modelled, and a debt with no due date is normal
 * rather than incomplete. This module only does arithmetic and description; it
 * never advises, never nags, and never compares the two people.
 */

export type DebtDirection = 'owe' | 'owed'
export type DebtStatus = 'outstanding' | 'partial' | 'settled'

export interface DebtLike {
  direction: DebtDirection
  /** Principal, whole rupiah. */
  amount: number
  /** Cumulative repaid so far. */
  paid: number
}

/** What is still outstanding on one debt. Never below zero — an overpayment is not a credit. */
export function debtRemaining(d: Pick<DebtLike, 'amount' | 'paid'>): number {
  return Math.max(0, Math.round(d.amount) - Math.round(d.paid))
}

/** Where the debt stands. Settled once nothing remains; partial once any has been repaid. */
export function debtStatus(d: Pick<DebtLike, 'amount' | 'paid'>): DebtStatus {
  if (debtRemaining(d) <= 0) return 'settled'
  return Math.round(d.paid) > 0 ? 'partial' : 'outstanding'
}

/**
 * A repayment, clamped to what is actually left so `paid` can never overshoot the
 * principal — the returned value is the new cumulative `paid` to store.
 */
export function applyRepayment(d: Pick<DebtLike, 'amount' | 'paid'>, pay: number): number {
  const add = Math.max(0, Math.round(pay))
  return Math.min(Math.round(d.amount), Math.round(d.paid) + add)
}

export interface DebtSummary {
  /** Still to pay out. */
  owe: number
  /** Still to come back. */
  owed: number
  /** owed − owe. Positive means more is owed to you than you owe. Descriptive only. */
  net: number
}

/**
 * Totals across many debts, counting only what is still outstanding. A running
 * position, never a verdict: no "good"/"bad", no comparison between partners —
 * two sums and their difference.
 */
export function debtSummary(debts: DebtLike[]): DebtSummary {
  let owe = 0
  let owed = 0
  for (const d of debts) {
    const rem = debtRemaining(d)
    if (d.direction === 'owe') owe += rem
    else owed += rem
  }
  return { owe, owed, net: owed - owe }
}

/** Overdue only describes a date that has passed; it is not a reminder and carries no penalty. */
export function debtOverdue(
  d: { dueDate?: string; amount: number; paid: number },
  todayISO: string,
): boolean {
  return Boolean(d.dueDate && d.dueDate < todayISO) && debtStatus(d) !== 'settled'
}
