import { useMemo, useState } from 'react'
import { format } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { useOwned } from '@/db/hooks'
import { db, newEnvelope } from '@/db/db'
import { useI18n } from '@/i18n'
import { whenLabel } from '@/i18n/format'
import type { Bill, MoneyMeeting, SharedGoal, Topic } from '@/types/domain'
import { useFinance, type FinanceAccount, type LedgerEntry } from './store'
import { usePots } from './budgetStore'
import { potStatus, spentInPeriod, type SpentInput } from './budget'
import { reviewPrompts } from './conversations'

/**
 * Ngobrolin uang bulan ini (F21).
 *
 * A short, structured, low-heat conversation — questions, not a scorecard. It
 * never shows an amount, never says who spent more, never grades the month. Real
 * records only decide *which* open question to raise; the conversation opens and
 * closes on feelings, and the data prompts in the middle are neutral nudges to
 * talk, in the app's calm tone (no red anywhere — see conflictSafe / F22).
 */

const today = () => format(new Date(), 'yyyy-MM-dd')

export default function Review({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const [open, setOpen] = useState(false)
  const [notes, setNotes] = useState('')

  const bills = useOwned<Bill>('bills', me)
  const goals = useOwned<SharedGoal>('goals', me)
  const topics = useOwned<Topic>('topics', me)
  const pots = usePots(me)
  const accounts = useFinance<'accounts'>('accounts', me)
  const ledger = useFinance<'ledger'>('ledger', me)

  const month = format(new Date(), 'yyyy-MM')

  // Same neutral inputs the meeting agenda already uses, plus over-budget pots.
  const overBudgetPots = useMemo(() => {
    const byAccount = new Map<string, FinanceAccount>()
    for (const a of (accounts ?? []) as FinanceAccount[]) if (a.kind === 'account') byAccount.set(a.id, a)
    const outflows: SpentInput[] = []
    for (const e of (ledger ?? []) as LedgerEntry[]) {
      const acc = byAccount.get(e.accountId)
      if (!acc || e.amount >= 0) continue
      outflows.push({ amount: e.amount, category: e.category, date: e.date, space: acc.space })
    }
    return (pots ?? []).filter((p) => potStatus(p.amount, p.carried, spentInPeriod(outflows, p, month)).over)
      .length
  }, [accounts, ledger, pots, month])

  const inputs = {
    unpaidBills: (bills ?? []).filter((b) => b.status === 'unpaid' && b.dueDate.startsWith(month)).length,
    overBudgetPots,
    openGoals: (goals ?? []).filter((g) => !g.achievedAt).length,
    moneyTopics: (topics ?? []).filter((x) => x.status !== 'talked' && /uang|money|utang|cicil/i.test(x.title))
      .length,
  }
  const prompts = useMemo(() => reviewPrompts(inputs), [inputs.unpaidBills, inputs.overBudgetPots, inputs.openGoals, inputs.moneyTopics])

  const meetings = useOwned<MoneyMeeting>('meetings', me, (a, b) => b.date.localeCompare(a.date))

  async function save() {
    await db.meetings.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'meeting',
      date: today(),
      agenda: { bills: inputs.unpaidBills, goals: inputs.openGoals, topics: inputs.moneyTopics },
      ...(notes.trim() ? { notes: notes.trim() } : {}),
    } as never)
    setNotes('')
    setOpen(false)
  }

  return (
    <div className="stack">
      <Card
        title={t('finance2.review.title')}
        icon="mentalload"
        hint={t('finance2.review.hint')}
        action={
          <button className="btn btn--sm" onClick={() => setOpen(true)}>
            <Icon name="plus" size={16} /> {t('finance2.review.start')}
          </button>
        }
      >
        <ol className="list">
          {prompts.map((p, i) => (
            <li key={p.key} className="list__item" style={{ alignItems: 'flex-start' }}>
              <Icon name={p.kind === 'open' ? 'mentalload' : 'info'} size={18} />
              <span className="grow">
                <span aria-hidden style={{ color: 'var(--text-2)', marginRight: 6 }}>{i + 1}.</span>
                {t(p.key as Parameters<typeof t>[0], p.params)}
              </span>
            </li>
          ))}
        </ol>
        <p className="disclaimer" style={{ marginTop: 'var(--space-3)' }}>
          {t('finance2.review.caveat')}
        </p>
      </Card>

      <Card title={t('finance2.review.pastTitle')} icon="backup" hint={t('finance2.review.pastHint')}>
        {(meetings ?? []).length === 0 ? (
          <EmptyState icon="mentalload" title={t('finance2.review.none')} hint={t('finance2.review.noneHint')} />
        ) : (
          <ul className="list">
            {(meetings ?? []).slice(0, 8).map((m) => (
              <li key={m.id} className="list__item" style={{ alignItems: 'flex-start' }}>
                <Icon name="mentalload" size={18} />
                <span className="grow stack stack--tight">
                  <strong style={{ fontSize: 14 }}>{whenLabel(m.date, t, locale)}</strong>
                  {m.notes && <span className="card__hint">{m.notes}</span>}
                </span>
              </li>
            ))}
          </ul>
        )}
      </Card>

      <Sheet open={open} onClose={() => setOpen(false)} title={t('finance2.review.start')}>
        <div className="stack">
          <ol className="list">
            {prompts.map((p) => (
              <li key={p.key} className="list__item" style={{ alignItems: 'flex-start' }}>
                <Icon name={p.kind === 'open' ? 'mentalload' : 'info'} size={16} />
                <span className="grow">{t(p.key as Parameters<typeof t>[0], p.params)}</span>
              </li>
            ))}
          </ol>
          <Field label={t('finance2.review.notes')}>
            {(pr) => (
              <textarea
                {...pr}
                rows={3}
                value={notes}
                placeholder={t('finance2.review.notesPlaceholder')}
                onChange={(e) => setNotes(e.target.value)}
              />
            )}
          </Field>
          <button className="btn btn--block" onClick={save}>
            {t('finance2.review.save')}
          </button>
          <p className="field__hint">{t('finance2.review.saveHint')}</p>
        </div>
      </Sheet>
    </div>
  )
}
