import type { MoneySpace } from './money'
import { safeToSpend, type PlannedOutflow, type SafeToSpend } from './money'
import { pendingBills, type BillLike, type DueState } from './ledger'

/**
 * Reminders, envelopes and per-space safe-to-spend (FIN F09–F11) — pure, no
 * React, no Dexie, no copy. Returns numbers and message keys; the screens call
 * `t()`.
 *
 * Three ideas:
 *   1. **A reminder has one addressee.** A bill belongs to whoever is on the
 *      hook for it, and its reminder routes to that one person — not to both,
 *      which is how joint apps turn a household into a nag machine.
 *   2. **An envelope is money you already spoke for.** A pot per space with an
 *      optional rollover, so last month's leftover either follows the money or
 *      resets — the couple's choice, stated, never assumed.
 *   3. **Free means free.** Per-space safe-to-spend takes out the bills that are
 *      committed *and* the budget still sitting in envelopes, and reports a
 *      range because undated commitments are genuinely uncertain.
 */

// ---------------------------------------------------------------------------
// F09 — reminders route to the responsible partner, not both
// ---------------------------------------------------------------------------

/** A bill carries who is on the hook to pay it; that is who the reminder is for. */
export type Payable = BillLike & { payerProfileId: string }

export interface Reminder<T> {
  bill: T
  state: DueState
}

export interface RoutedReminders<T> {
  /** The pending bills this viewer is responsible for. Their nudges, no one else's. */
  mine: Reminder<T>[]
  /**
   * The pending bills someone else is responsible for. Shown read-only so the
   * viewer knows what is being handled, never as a task landing on them.
   */
  theirs: Reminder<T>[]
}

/**
 * Split the pending bills into "for me" and "for my partner" by who pays.
 *
 * The whole point is that a reminder lands on exactly one desk. A bill with no
 * payer set is nobody's certainty yet, so it stays on the viewer's own list
 * where it can be assigned, rather than silently pinging both people.
 */
export function routeReminders<T extends Payable>(
  bills: T[],
  viewerProfileId: string,
  todayISO: string,
): RoutedReminders<T> {
  const pending = pendingBills(bills, todayISO)
  const mine: Reminder<T>[] = []
  const theirs: Reminder<T>[] = []
  for (const r of pending) {
    const payer = r.bill.payerProfileId
    if (!payer || payer === viewerProfileId) mine.push(r)
    else theirs.push(r)
  }
  return { mine, theirs }
}

// ---------------------------------------------------------------------------
// F10 — envelopes / budget pots per space, with rollover
// ---------------------------------------------------------------------------

/** yyyy-MM of a yyyy-MM-dd date. The period an envelope is budgeted by. */
export function monthOf(dateISO: string): string {
  return dateISO.slice(0, 7)
}

export interface PotStatus {
  /** What is available this period: the monthly budget plus anything carried in. */
  budget: number
  spent: number
  /** budget − spent. Negative is possible and is reported, never clamped away. */
  remaining: number
  /** Money still earmarked and therefore not free to spend elsewhere. */
  reserved: number
  over: boolean
}

/**
 * Where a pot stands this period, given what was spent against it.
 *
 * `reserved` is the unspent budget — money the couple has already assigned, so
 * safe-to-spend must treat it as gone even though it has not left the account.
 * `remaining` can go negative (you overspent the envelope); that is a fact worth
 * showing, not an error to hide.
 */
export function potStatus(monthly: number, carried: number, spent: number): PotStatus {
  const budget = Math.round(monthly) + Math.round(carried)
  const s = Math.max(0, Math.round(spent))
  const remaining = budget - s
  return {
    budget,
    spent: s,
    remaining,
    reserved: Math.max(0, remaining),
    over: remaining < 0,
  }
}

/**
 * What carries into the next period when the month turns.
 *
 * Rollover on: whatever was left (never a debt — an overspent envelope starts
 * the next month clean, it does not punish forward). Rollover off: nothing
 * carries, the budget resets to its monthly figure.
 */
export function rolloverCarry(
  pot: { monthly: number; carried: number; rollover: boolean },
  spentInPeriod: number,
): number {
  if (!pot.rollover) return 0
  const left = Math.round(pot.monthly) + Math.round(pot.carried) - Math.max(0, Math.round(spentInPeriod))
  return Math.max(0, left)
}

/**
 * Roll a pot forward to `currentMonth` if its stored period is older.
 *
 * ponytail: one step, not one per skipped month. If the app is opened after a
 * three-month gap the leftover rolls once and the period jumps to now, rather
 * than accruing three months of untouched budget into a surprise balance. Walk
 * month by month here only if a couple ever asks for that behaviour.
 */
export function advancePot(
  pot: { monthly: number; carried: number; rollover: boolean; periodMonth: string },
  currentMonth: string,
  spentInStoredPeriod: number,
): { carried: number; periodMonth: string } | undefined {
  if (currentMonth <= pot.periodMonth) return undefined
  return { carried: rolloverCarry(pot, spentInStoredPeriod), periodMonth: currentMonth }
}

export interface SpentInput {
  amount: number
  category: string
  date: string
  space: MoneySpace
}

/**
 * How much hit one pot in one month: the outflows in the pot's space whose
 * category matches, that month. Category match is trimmed and case-folded, so
 * "Makan" and "makan " land in the same envelope; incomes (amount ≥ 0) never do.
 */
export function spentInPeriod(
  outflows: SpentInput[],
  pot: { space: MoneySpace; category: string },
  month: string,
): number {
  const want = pot.category.trim().toLowerCase()
  let total = 0
  for (const o of outflows) {
    if (o.amount >= 0) continue
    if (o.space !== pot.space) continue
    if (monthOf(o.date) !== month) continue
    if (o.category.trim().toLowerCase() !== want) continue
    total += Math.round(-o.amount)
  }
  return total
}

// ---------------------------------------------------------------------------
// F11 — safe-to-spend per space, after committed bills AND envelopes
// ---------------------------------------------------------------------------

export interface SpaceSafeInput {
  balance: number
  today: string
  paydayDom: number
  /** Committed bills for this space, before the next payday. */
  bills: PlannedOutflow[]
  /** Budget still sitting in this space's envelopes — spoken for, so not free. */
  reserved: number
}

/**
 * What is genuinely free in one space.
 *
 * Reuses the account-level `safeToSpend`: the committed bills go in as planned
 * outflows, and the envelope reservation goes in as one undated commitment.
 * Undated money widens the gap between `low` and `high`, which is the honest
 * shape — the couple is told a range and why, never a single confident number.
 */
export function spaceSafeToSpend(input: SpaceSafeInput): SafeToSpend {
  const reserved = Math.max(0, Math.round(input.reserved))
  return safeToSpend({
    balance: input.balance,
    today: input.today,
    paydayDom: input.paydayDom,
    planned: reserved > 0 ? [...input.bills, { amount: reserved }] : input.bills,
  })
}
