/**
 * Arisan (F20) — rotating savings, pure, no React, no Dexie, no copy.
 *
 * Arisan is Indonesia's rotating savings club: every member puts in the same
 * amount each round, and each round one member takes the whole pot. It rotates
 * until everyone has received once (one cycle), then usually starts again.
 *
 * The members are names the user types — an arisan almost always includes people
 * outside the couple (RT, kantor, keluarga) — so no member is ever invented. The
 * recipient contributes too; taking the pot does not exempt you from paying in.
 * This module only answers "whose turn" and "who still owes this round". It never
 * nags a member, never ranks them, and does not model interest, penalties, or a
 * bandar's cut — an informal arisan has none.
 */

export interface ArisanInput {
  /** Everyone in the group, by name. */
  members: string[]
  /** Payout rotation — whose turn each round. Falls back to member order. */
  order: string[]
  /** Contribution per member per round. */
  amount: number
  /** 0-based index of the current round across all cycles. */
  round: number
  /** Members who have already paid into the current round. */
  collected: string[]
}

export interface ArisanRound {
  /** Whose turn it is this round. Undefined only if the group is empty. */
  recipient: string | undefined
  /** The pot one member receives this round: amount × members. */
  pot: number
  /** Members who have not yet paid into this round, each owing `amount`. */
  owed: { member: string; amount: number }[]
  owedTotal: number
  collectedTotal: number
  /** Every member has paid in — the round is ready to hand over. */
  allPaid: boolean
  /** 1-based cycle number (each cycle is one full rotation). */
  cycle: number
  /** 1-based position of this round within its cycle. */
  roundInCycle: number
  /** Rounds per cycle = number of members. */
  rounds: number
}

/** Whose turn at a given round. Wraps cleanly and tolerates a negative round. */
export function arisanTurn(order: string[], round: number): string | undefined {
  const n = order.length
  if (n === 0) return undefined
  return order[((round % n) + n) % n]
}

/**
 * The state of one arisan round: who receives, the pot, and who still owes.
 *
 * `owed` lists everyone who has not paid into this round yet (the recipient
 * included). It is a running who's-left, not a demand — the screen presents it
 * as "yang belum setor", never as a reminder pushed at anyone.
 */
export function arisanRound(input: ArisanInput): ArisanRound {
  const members = input.members
  const n = members.length
  const amt = Math.max(0, Math.round(input.amount))
  const order = input.order.length > 0 ? input.order : members
  const collected = new Set(input.collected)

  const owed = members.filter((m) => !collected.has(m)).map((m) => ({ member: m, amount: amt }))
  const collectedCount = members.filter((m) => collected.has(m)).length

  return {
    recipient: arisanTurn(order, input.round),
    pot: amt * n,
    owed,
    owedTotal: owed.length * amt,
    collectedTotal: collectedCount * amt,
    allPaid: n > 0 && owed.length === 0,
    cycle: n > 0 ? Math.floor(input.round / n) + 1 : 1,
    roundInCycle: n > 0 ? (input.round % n) + 1 : 1,
    rounds: n,
  }
}
